// MARK: - The tests

enum CallsDeviceTests {
    /// What the phone says, unless set: the package's own tests draw the panel with it.
    static var denied: ( camera: Bool, microphone: Bool )?

    static var cameraDenied: Bool {
        if let denied { return denied.camera }

        let status = AVCaptureDevice.authorizationStatus( for: .video )
        return status == .denied || status == .restricted
    }

    static var microphoneDenied: Bool {
        if let denied { return denied.microphone }

        return AVAudioSession.sharedInstance().recordPermission == .denied
    }
}

/// The camera, for the user's eyes alone: a capture session of its own with its picture on a preview layer, never a
/// track, so nothing of it can reach the call. It runs only while the call's own camera is off, and lets go of the
/// camera before the call's capture opens it (`release`): two sessions on one camera interrupt each other. Not
/// mirrored, the front camera included: the user sees what the others would, as every call picture is drawn.
final class CallsCameraPreview: UIView {
    private let queue = DispatchQueue( label: "calls.devices.preview" )
    private var session: AVCaptureSession?
    private var generation = 0
    /// Started and not stopped since: its session may still be opening.
    private var held = false

    private static let all = NSHashTable<CallsCameraPreview>.weakObjects()

    /// Whether a preview holds the camera, or is opening it.
    static var isHeld: Bool {
        all.allObjects.contains { $0.held }
    }

    /// Every preview stopped, and `then` once the camera is let go of: for the call's own capture, before it opens.
    static func release( _ then: @escaping () -> Void ) {
        let group = DispatchGroup()

        for preview in all.allObjects {
            group.enter()
            preview.stop { group.leave() }
        }

        group.notify( queue: .main, execute: then )
    }

    override class var layerClass: AnyClass { AVCaptureVideoPreviewLayer.self }

    private var previewLayer: AVCaptureVideoPreviewLayer { layer as! AVCaptureVideoPreviewLayer }

    override init( frame: CGRect ) {
        super.init( frame: frame )
        previewLayer.videoGravity = .resizeAspectFill
        backgroundColor = .black
    }

    required init?( coder: NSCoder ) { fatalError( "init(coder:) has not been implemented" ) }

    /// Asks for the camera where it was never asked, then shows it: `done(false)` where it is refused or missing.
    func start( front: Bool, done: @escaping ( Bool ) -> Void ) {
        switch AVCaptureDevice.authorizationStatus( for: .video ) {
        case .authorized:
            open( front: front, done: done )
        case .notDetermined:
            AVCaptureDevice.requestAccess( for: .video ) { [weak self] granted in
                DispatchQueue.main.async {
                    guard granted else { return done( false ) }
                    self?.open( front: front, done: done )
                }
            }
        default:
            done( false )
        }
    }

    /// Everything on one serial queue: a stop queued after an open runs once the open has finished, and finds its
    /// session either handed over here or already stopped by the open itself.
    private func open( front: Bool, done: @escaping ( Bool ) -> Void ) {
        generation += 1
        held = true
        Self.all.add( self )

        let mine = generation
        let old = session

        queue.async { [weak self] in
            old?.stopRunning()

            let current: () -> Bool = { DispatchQueue.main.sync { self?.generation == mine } }

            guard current() else { return }

            let session = AVCaptureSession()
            session.sessionPreset = .medium

            guard let device = AVCaptureDevice.default( .builtInWideAngleCamera, for: .video, position: front ? .front : .back ),
                  let input = try? AVCaptureDeviceInput( device: device ),
                  session.canAddInput( input ) else {
                DispatchQueue.main.async {
                    if self?.generation == mine { self?.held = false }
                    done( false )
                }
                return
            }

            session.addInput( input )

            let kept: Bool = DispatchQueue.main.sync {
                guard let self, self.generation == mine else { return false }
                self.session = session
                self.previewLayer.session = session
                self.unmirror()
                return true
            }

            guard kept else { return }

            session.startRunning()

            // Stopped while it was starting: its stop found no session to stop, so this one stops it.
            guard current() else {
                session.stopRunning()
                return
            }

            DispatchQueue.main.async { done( true ) }
        }
    }

    /// Stopped, and `then` once the camera is let go of.
    func stop( _ then: ( () -> Void )? ) {
        generation += 1
        held = false

        let old = session
        session = nil
        previewLayer.session = nil

        queue.async {
            old?.stopRunning()
            DispatchQueue.main.async { then?() }
        }
    }

    /// The layer mirrors the front camera unless told not to.
    private func unmirror() {
        guard let connection = previewLayer.connection, connection.isVideoMirroringSupported else { return }

        connection.automaticallyAdjustsVideoMirroring = false
        connection.isVideoMirrored = false
    }
}

/// The microphone, heard for the user alone: a recorder kept to its level, writing nowhere anyone reads, in the call's
/// own audio session as it is. It runs only while the call does not send the microphone, and only into a session
/// already set for recording: a recorder never sets the session's category or mode, and the host offers the test only
/// while the call's session is live (`CallsEngine.testsMicrophone`), so it adds a listener and changes nothing else.
final class CallsMicrophoneTest {
    private var recorder: AVAudioRecorder?
    private var file: URL?

    /// 0…1, as loud as the last reading.
    var level: Float {
        guard let recorder, recorder.isRecording else { return 0 }

        recorder.updateMeters()

        let power = recorder.averagePower( forChannel: 0 )

        return max( 0, min( 1, ( power + 55 ) / 50 ) )
    }

    func start( done: @escaping ( Bool ) -> Void ) {
        let session = AVAudioSession.sharedInstance()

        switch session.recordPermission {
        case .granted:
            done( open() )
        case .undetermined:
            session.requestRecordPermission { [weak self] granted in
                DispatchQueue.main.async {
                    done( granted && ( self?.open() ?? false ) )
                }
            }
        default:
            done( false )
        }
    }

    private func open() -> Bool {
        let category = AVAudioSession.sharedInstance().category

        // A session the call set up for playing alone would need setting up again to record, which is the call's.
        guard category == .playAndRecord || category == .record else {
            CallsLog.write( "devices: the session does not record (\( category.rawValue )): no microphone test" )
            return false
        }

        let url = FileManager.default.temporaryDirectory.appendingPathComponent( "calls-microphone-test.caf" )
        let settings: [ String: Any ] = [
            AVFormatIDKey: kAudioFormatLinearPCM,
            AVSampleRateKey: 16000,
            AVNumberOfChannelsKey: 1,
            AVLinearPCMBitDepthKey: 16,
            AVLinearPCMIsFloatKey: false,
        ]

        guard let recorder = try? AVAudioRecorder( url: url, settings: settings ) else { return false }

        recorder.isMeteringEnabled = true

        guard recorder.record() else {
            CallsLog.write( "devices: the microphone test did not start" )
            return false
        }

        self.recorder = recorder
        file = url

        return true
    }

    func stop() {
        recorder?.stop()
        recorder = nil

        if let file { try? FileManager.default.removeItem( at: file ) }
        file = nil
    }
}

/// Short sine notes through the call's audio session and route as they are: the speaker's test and the chime of a
/// raised hand.
final class CallsTones {
    static let shared = CallsTones()

    enum Tune {
        /// Three rising notes, 0.22 s apart, each half a second.
        case speakerTest
        /// Two notes, 0.14 s apart, each 0.3 s, quieter.
        case hand
    }

    private var player: AVAudioPlayer?
    private var finished: ( () -> Void )?
    private var timer: Timer?

    func play( _ tune: Tune, done: ( () -> Void )? = nil ) {
        stop()

        let notes: [ ( frequency: Double, start: Double ) ]
        let length: Double
        let peak: Double

        switch tune {
        case .speakerTest:
            notes = [ ( 523.25, 0 ), ( 659.25, 0.22 ), ( 783.99, 0.44 ) ]
            length = 0.5
            peak = 0.18
        case .hand:
            notes = [ ( 660, 0 ), ( 880, 0.14 ) ]
            length = 0.3
            peak = 0.08
        }

        let data = Self.wave( notes: notes, length: length, peak: peak )

        guard let player = try? AVAudioPlayer( data: data ) else {
            done?()
            return
        }

        self.player = player
        finished = done
        player.prepareToPlay()
        player.play()

        timer = Timer.scheduledTimer( withTimeInterval: player.duration + 0.05, repeats: false ) { [weak self] _ in
            self?.stop()
        }
    }

    func stop() {
        timer?.invalidate()
        timer = nil
        player?.stop()
        player = nil

        let finished = finished
        self.finished = nil
        finished?()
    }

    /// A WAV of the notes, each a 20 ms rise to `peak` and an exponential fall over the rest of `length`.
    static func wave( notes: [ ( frequency: Double, start: Double ) ], length: Double, peak: Double ) -> Data {
        let rate = 44100.0
        let total = ( notes.map { $0.start }.max() ?? 0 ) + length
        let count = Int( total * rate )
        var samples = [ Double ]( repeating: 0, count: count )

        for note in notes {
            let first = Int( note.start * rate )
            let span = Int( length * rate )

            for index in 0 ..< span where first + index < count {
                let t = Double( index ) / rate
                let gain: Double

                if t < 0.02 {
                    gain = peak * t / 0.02
                } else {
                    gain = peak * pow( 0.0001 / peak, ( t - 0.02 ) / ( length - 0.02 ) )
                }

                samples[ first + index ] += gain * sin( 2 * .pi * note.frequency * t )
            }
        }

        var data = Data()
        let bytes = count * 2

        func put<T>( _ value: T ) {
            withUnsafeBytes( of: value ) { data.append( contentsOf: $0 ) }
        }

        data.append( contentsOf: Array( "RIFF".utf8 ) )
        put( UInt32( 36 + bytes ).littleEndian )
        data.append( contentsOf: Array( "WAVEfmt ".utf8 ) )
        put( UInt32( 16 ).littleEndian )
        put( UInt16( 1 ).littleEndian )
        put( UInt16( 1 ).littleEndian )
        put( UInt32( rate ).littleEndian )
        put( UInt32( rate * 2 ).littleEndian )
        put( UInt16( 2 ).littleEndian )
        put( UInt16( 16 ).littleEndian )
        data.append( contentsOf: Array( "data".utf8 ) )
        put( UInt32( bytes ).littleEndian )

        for sample in samples {
            put( Int16( max( -1, min( 1, sample ) ) * Double( Int16.max ) ).littleEndian )
        }

        return data
    }
}
"""## ),
    ( "CallsGrid.swift", ##"""
import UIKit
import LiveKit

/// One person, one cell.
///
/// This used to give a screen sharer two — a comment claimed the web did the
/// same, and it does not: `group-video-grid-item.tsx` renders one tile per
/// participant and puts the screen in it, with their camera inset in the
/// corner. Two tiles for one person also cost a place in a grid that has very
/// few of them on a phone.
private struct Cell {
    let person: CallsRoomParticipant
}

/// A call with more than two people in it.
///
/// Two shapes, because the web has two. A **video** room is a wall of pictures:
/// one tile each, laid out in as square a grid as the count allows, because a
/// phone screen is tall and a single column wastes it above four people. An
/// **audio** room has no pictures to show, so the web draws a list instead —
/// a row per person, avatar, name and their microphone — and fifty tall empty
/// rectangles would be a worse answer to the same question.
///
/// Tiles are reused rather than rebuilt: a `VideoView` owns a renderer, and
/// churning them on every roster change is how a grid starts to flicker.
final class CallsGrid: UIView, UIScrollViewDelegate {
    /// What a tile is shaped for when nothing has said otherwise.
    ///
    /// Every camera in a call publishes at it and a laptop's shared screen is
    /// near enough, so it stood in for every picture here. A phone sharing its
    /// own screen is about 9:19.5 — taller than it is wide — and there is no
    /// figure that covers both, so this is now the fallback and the tiles
    /// measure what they are actually drawing: see `Tile.pictureRatio`.
    static let tileRatio: CGFloat = 1.77

    /// The shortest a strip, or the narrowest a column, is allowed to be. The
    /// web's `minSecondaryHeight` and the 16:9 width that goes with it.
    static let minStrip: CGFloat = 100

    /// The ⋯ on a tile, or a long-press on it: a moderator's menu for that person.
    var onPerson: ((CallsRoomParticipant) -> Void)?

    /// The pin on a tile: Pin for Me for that person, anyone's (CallsSpotlight).
    var onPin: ((CallsRoomParticipant) -> Void)?

    /// Who a moderator put in the spotlight for everyone, by identity, in order: the main tiles, each labeled
    /// Spotlight (CallsSpotlight). Drawn again at once.
    var spotlight: [String] = [] {
        didSet {
            guard spotlight != oldValue, !shownPeople.isEmpty else { return }

            show(shownPeople)
        }
    }

    /// This user's own pins (Pin for Me), by identity: the main tiles while nobody is in the spotlight.
    var pinned: [String] = [] {
        didSet {
            guard pinned != oldValue, !shownPeople.isEmpty else { return }

            show(shownPeople)
        }
    }

    /// Whether a tile offers Pin for Me: a group video call's tiles, its pin shown once the tile is tapped and while it
    /// is pinned, as the web's on a phone. Elsewhere a tap on a tile is the screen's, which puts the dock away.
    var pinsOffered = false {
        didSet {
            guard pinsOffered != oldValue else { return }

            rebind()
        }
    }

    /// Who the grid was last given.
    private var shownPeople: [CallsRoomParticipant] = []

    /// Whose menu is open, by identity: their tile is outlined.
    var moderating: String? {
        didSet {
            guard moderating != oldValue else { return }

            for tile in tiles { tile.moderating = moderating != nil && tile.person?.identity == moderating }
        }
    }

    /// Where a person's menu opens: the ⋯ on their tile while it shows, else the tile; nil when they have no tile.
    func manageAnchor(_ identity: String) -> UIView? {
        guard let tile = tiles.first(where: { $0.person?.identity == identity }) else { return nil }

        return tile.manage.isHidden ? tile : tile.manage
    }

    /// Draw the list rather than the wall. Set from the call's own type: an
    /// audio room is a room nobody is publishing video into.
    var audioRoom = false {
        didSet {
            guard audioRoom != oldValue else { return }

            tiles.forEach { $0.isRow = audioRoom }
            setNeedsLayout()
        }
    }

    /// Whether the room is in broadcast mode. It decides who is pulled out
    /// large: the web's grid puts whoever may publish in the primary row while
    /// a room is broadcasting, and pinned participants at any time.
    var broadcastRoom = false {
        didSet {
            guard broadcastRoom != oldValue else { return }

            setNeedsLayout()
        }
    }

    /// A list is taller than the screen once there are enough people in it —
    /// an audio room holds fifty — so the tiles live in a scroller. A wall
    /// scrolls only when the people in it will not fit at the size the web
    /// would have drawn them.
    private let scroll = UIScrollView()

    private final class Tile: UIView, TrackDelegate {
        let video = VideoView()
        /// Over the picture while the person's camera changes codec
        /// (`CallsCameraSwitch`), until the room hears the frame that ends
        /// it: the web's "Optimizing video quality..." tile, in place of a
        /// camera that looks turned off for a second.
        let optimizing = CallsOptimizingView()
        /// Someone sharing their screen is still a face worth seeing, so the
        /// web insets their camera in the corner of the same tile
        /// (`.bm-small-video`: 72px tall, 8px in, a hairline of white).
        let cameraInset = VideoView()
        /// Over the picture, and over the camera in the corner, while it
        /// stopped arriving (`CallsStallWatch`): blurred, and "Video
        /// interrupted" over a camera that alone stopped.
        let stalled = CallsStalledView()
        let insetStalled = CallsStalledView()
        let picture = UIImageView()
        let initial = UILabel()
        let label = UILabel()

        /// The glass pill behind the name on a tile, over a picture too, as the
        /// web's `.bm-info-name` is: who is who stays readable on any video.
        let namePill = UIView()

        /// The tile whose menu is open, outlined in the accent (`.bm-moderating`):
        /// the menu itself may sit away from the tile.
        let outline = UIView()

        /// The web draws each of these as a *chip* — a coloured disc with a
        /// stroked glyph in it — rather than a bare mark: a red one for a
        /// microphone that is off, a translucent green one for one that is on,
        /// and an amber one for a raised hand. So each is a disc with the icon
        /// inset, which is also why they are two views and not one.
        let handChip = UIView()
        let hand = CallsIconView(CallsIcons.raiseHand)
        let micChip = UIView()
        let mic = CallsIconView(CallsIcons.micOff)
        let viewer = UILabel()

        /// The ⋯ that opens the person's menu, on every tile a moderator has
        /// something to do with: the web's `.bm-manage-participant`, always
        /// shown where there is no hover to reveal it. A long-press opens the
        /// same menu.
        let manage = UIControl()
        let more = CallsIconView(CallsIcons.more)
        var onManage: (() -> Void)?

        /// Pin for Me, anyone's, beside the ⋯: the web's `.wplus-pin-for-me`, on a phone shown for a moment once the
        /// tile is tapped, and latched in the accent while the tile is pinned, as a pin waiting for a spotlight to end
        /// is pinned all the same.
        let pin = UIControl()
        let pinIcon = CallsIconView(CallsIcons.pin)
        var onPin: (() -> Void)?
        /// The tap that shows the pin, a group video call's alone (`CallsGrid.pinsOffered`).
        private(set) lazy var tap = UITapGestureRecognizer(target: self, action: #selector(tileTapped(_:)))
        private var tapped = false
        private var tappedFor: String?
        private var tappedEnds: DispatchWorkItem?
        private var pinsOffered = false
        private var pinnedHere = false

        /// A spotlighted tile's label, beside the name, for everyone: the web's `.wplus-call-spotlight-label`, a star
        /// and the word on the accent.
        let spotlightPill = UIView()
        let spotlightStar = CallsIconView(CallsIcons.star)
        let spotlightLabel = UILabel()
        private var spotlit = false

        /// Over the whole tile while its person is away for a moment and held
        /// for a return: the web's `.bm-call-reconnecting`, a 45% black veil
        /// with the word in the middle.
        let reconnecting = UILabel()

        /// Which of the two shapes this tile is drawing. Everything is laid
        /// out by hand, so switching is a relayout and nothing else.
        var isRow = false {
            didSet {
                guard isRow != oldValue else { return }

                setNeedsLayout()
            }
        }

        private var avatarUrl = ""
        private(set) var person: CallsRoomParticipant?
        private(set) var showsScreen = false

        /// Width over height of the picture on show, once the track has said —
        /// zero until then, which means "no better answer than `tileRatio`".
        ///
        /// The shape is not known when the tile is built: the dimensions
        /// arrive with the stream, and for a phone turned over mid-call they
        /// arrive again. So the tile is told rather than asked once. The
        /// Android tile learns exactly the same thing from its renderer's
        /// `onFrameResolutionChanged`.
        private(set) var pictureRatio: CGFloat = 0

        /// What the grid does when that answer changes. A row's height is
        /// worked out by the grid, not by the tile, so a new shape has to
        /// reach further up than `setNeedsLayout` on self.
        var onShape: (() -> Void)?

        /// The track whose shape is being followed, held weakly: the room owns
        /// it and a tile must not keep a dead one alive.
        private weak var watched: Track?

        override init(frame: CGRect) {
            super.init(frame: frame)

            backgroundColor = CallsTheme.tile
            layer.cornerRadius = 10
            clipsToBounds = true

            // Nothing in the grid is mirrored, one's own camera included: you
            // see yourself the way the others do, as the web's grid shows it.
            // A `VideoView` mirrors a local front camera unless told not to.
            video.mirrorMode = .off
            video.isHidden = true

            cameraInset.mirrorMode = .off
            cameraInset.isHidden = true
            cameraInset.layoutMode = .fill
            cameraInset.clipsToBounds = true
            cameraInset.layer.cornerRadius = 8
            cameraInset.layer.borderWidth = 1
            cameraInset.layer.borderColor = UIColor(white: 1, alpha: 0.16).cgColor
            cameraInset.backgroundColor = .black
            cameraInset.alpha = 0.85

            picture.contentMode = .scaleAspectFill
            picture.clipsToBounds = true
            picture.isHidden = true

            // With no picture, the initials on a disc of the accent in the
            // picture's place, as the call screen of one person draws them.
            // The bare letter on the tile read as a picture that had failed.
            initial.font = .systemFont(ofSize: 28, weight: .semibold)
            initial.textColor = .white
            initial.textAlignment = .center
            initial.backgroundColor = CallsTheme.accent
            initial.clipsToBounds = true

            label.font = .systemFont(ofSize: 12, weight: .medium)
            label.textColor = .white
            label.textAlignment = .center
            label.lineBreakMode = .byTruncatingTail

            namePill.backgroundColor = UIColor(white: 0, alpha: 0.55)
            namePill.isUserInteractionEnabled = false
            namePill.isHidden = true

            outline.layer.borderColor = CallsTheme.accent.cgColor
            outline.layer.borderWidth = 2
            outline.layer.cornerRadius = 10
            outline.isUserInteractionEnabled = false
            outline.isHidden = true

            handChip.backgroundColor = CallsTheme.warning
            handChip.isHidden = true
            handChip.clipsToBounds = true
            hand.color = UIColor(red: 0.067, green: 0.075, blue: 0.094, alpha: 1)
            handChip.addSubview(hand)

            micChip.isHidden = true
            micChip.clipsToBounds = true
            mic.color = .white
            micChip.addSubview(mic)

            // `.bm-viewer-badge`: a glass pill with the word as it is written.
            viewer.font = .systemFont(ofSize: 11, weight: .semibold)
            viewer.textColor = UIColor(white: 1, alpha: 0.82)
            viewer.textAlignment = .center
            viewer.backgroundColor = UIColor(white: 0, alpha: 0.55)
            viewer.clipsToBounds = true
            viewer.isHidden = true

            insetStalled.layer.cornerRadius = 8

            addSubview(video)
            addSubview(stalled)
            addSubview(cameraInset)
            addSubview(insetStalled)
            addSubview(picture)
            addSubview(initial)
            addSubview(optimizing)
            addSubview(namePill)
            addSubview(label)
            reconnecting.font = .systemFont(ofSize: 13, weight: .medium)
            reconnecting.textColor = .white
            reconnecting.textAlignment = .center
            reconnecting.numberOfLines = 2
            reconnecting.backgroundColor = UIColor(white: 0, alpha: 0.45)
            reconnecting.isHidden = true

            manage.backgroundColor = UIColor(white: 0, alpha: 0.55)
            manage.layer.borderWidth = 1
            manage.layer.borderColor = UIColor(white: 1, alpha: 0.14).cgColor
            manage.clipsToBounds = true
            manage.isHidden = true
            manage.accessibilityLabel = CallsTheme.string("manage_participant", fallback: "Manage Participant")
            manage.accessibilityTraits = .button
            manage.isAccessibilityElement = true
            more.color = .white
            more.isUserInteractionEnabled = false
            manage.addSubview(more)
            // A recognizer of its own, as the dock's buttons have: the call
            // screen's tap that puts the dock away cancels a plain control's
            // touch under it, and the ⋯ never heard its press.
            manage.addGestureRecognizer(UITapGestureRecognizer(target: self, action: #selector(managePressed)))

            pin.layer.borderWidth = 1
            pin.clipsToBounds = true
            pin.isHidden = true
            pin.accessibilityTraits = .button
            pin.isAccessibilityElement = true
            pinIcon.isUserInteractionEnabled = false
            pin.addSubview(pinIcon)
            pin.addGestureRecognizer(UITapGestureRecognizer(target: self, action: #selector(pinPressed)))

            // `.wplus-call-spotlight-label`: 11 points bold on the accent, a 12 point star before the word.
            spotlightPill.backgroundColor = CallsTheme.accent.withAlphaComponent(0.92)
            spotlightPill.isUserInteractionEnabled = false
            spotlightPill.isHidden = true
            spotlightStar.color = CallsTheme.onAccent
            spotlightLabel.font = .systemFont(ofSize: 11, weight: .bold)
            spotlightLabel.textColor = CallsTheme.onAccent
            spotlightPill.addSubview(spotlightStar)
            spotlightPill.addSubview(spotlightLabel)

            // A tap on the tile shows its pin for a while, in a group video call only (`setPins`).
            tap.isEnabled = false
            addGestureRecognizer(tap)

            addSubview(spotlightPill)
            addSubview(handChip)
            addSubview(micChip)
            addSubview(viewer)
            addSubview(reconnecting)
            addSubview(outline)
            addSubview(manage)
            addSubview(pin)
        }

        @objc private func managePressed() {
            onManage?()
        }

        @objc private func pinPressed() {
            onPin?()
        }

        /// The web's tapped tile on a phone: its pin shows for four seconds, and a second tap puts it away. A tap on
        /// the ⋯ or the pin is theirs.
        @objc private func tileTapped(_ recogniser: UITapGestureRecognizer) {
            let point = recogniser.location(in: self)

            guard !(!manage.isHidden && manage.frame.contains(point)), !(!pin.isHidden && pin.frame.contains(point)) else { return }

            showTapped(!tapped)
        }

        private func showTapped(_ on: Bool) {
            tappedEnds?.cancel()
            tappedEnds = nil
            tapped = on
            tappedFor = on ? person?.identity : nil

            if on {
                let ends = DispatchWorkItem { [weak self] in self?.showTapped(false) }

                tappedEnds = ends
                DispatchQueue.main.asyncAfter(deadline: .now() + 4, execute: ends)
            }

            drawPin()
            setNeedsLayout()
        }

        /// Whether Pin for Me is offered here and this tile is pinned, from the grid.
        func setPins(offered: Bool, pinned: Bool) {
            let offered = offered && !isRow

            pinsOffered = offered
            pinnedHere = pinned
            tap.isEnabled = offered

            // A tap was for the person it was on: the tile handed to someone else as the grid reorders forgets it.
            if tapped, !offered || tappedFor != person?.identity { showTapped(false) }

            drawPin()
        }

        /// The pin, shown once the tile is tapped, while it is pinned, or always for VoiceOver, which has no tap to
        /// show it with; latched in the accent while pinned.
        private func drawPin() {
            pin.isHidden = !pinsOffered || !(tapped || pinnedHere || UIAccessibility.isVoiceOverRunning)
            pin.backgroundColor = pinnedHere ? CallsTheme.accent : UIColor(white: 0, alpha: 0.55)
            pin.layer.borderColor = pinnedHere ? UIColor.clear.cgColor : UIColor(white: 1, alpha: 0.14).cgColor
            pinIcon.set(pinnedHere ? CallsIcons.pinOff : CallsIcons.pin)
            pinIcon.color = pinnedHere ? CallsTheme.onAccent : .white
            pin.accessibilityLabel = pinnedHere
                ? CallsTheme.string("unpin_for_me", fallback: "Unpin for Me")
                : CallsTheme.string("pin_for_me", fallback: "Pin for Me")
            pin.accessibilityTraits = pinnedHere ? [.button, .selected] : .button
        }

        /// Labeled Spotlight, for everyone: a video tile alone, as an audio roster has no main tiles.
        func setSpotlit(_ on: Bool) {
            spotlit = on && !isRow
            spotlightPill.isHidden = !spotlit
            spotlightLabel.text = CallsTheme.string("spotlight", fallback: "Spotlight")
            setNeedsLayout()
        }

        override func accessibilityActivate() -> Bool {
            guard !manage.isHidden else { return false }

            onManage?()
            return true
        }

        /// Whether this tile's menu is open.
        var moderating = false {
            didSet { outline.isHidden = !moderating }
        }

        required init?(coder: NSCoder) {
            fatalError("init(coder:) has not been implemented")
        }

        /// A dropped tile takes its renderer with it: leaving the track
        /// attached keeps a view alive that nothing will ever draw again.
        func release() {
            watch(nil)
            video.track = nil
            cameraInset.track = nil
            person = nil
            optimizing.show(false, picture: nil)
            stalled.show(blurred: false, notice: false)
            insetStalled.show(blurred: false, notice: false)
        }

        /// The placeholder over a camera changing codec: up while the room
        /// holds the person's camera as changing (the frame that ends it is the
        /// room's to hear, so a renderer that stalls brings nothing back), and
        /// never in a row or over a shared screen, which are not the camera.
        /// Said to VoiceOver once a change per person, wherever their tile goes
        /// meanwhile.
        fileprivate func applyOptimizing() {
            guard let who = person, !isRow, !showsScreen else {
                optimizing.show(false, picture: nil)
                return
            }

            optimizing.show(who.optimizing, picture: picture.image, key: who.identity)
        }

        /// The info line of a row. What sits above it is the picture, and how
        /// much room that gets is the grid's to decide — see `layoutList`.
        static let rowHeight: CGFloat = 56

        /// Follow this track's shape, and stop following the last one.
        private func watch(_ track: VideoTrack?) {
            if watched !== track {
                watched?.remove(delegate: self)
                watched = track
                track?.add(delegate: self)
            }

            // Asked as well as told: a track that was already carrying a
            // picture when it was handed over has its dimensions now, and no
            // event is coming to say so.
            apply(track?.dimensions)
        }

        private func apply(_ dimensions: Dimensions?) {
            var ratio: CGFloat = 0

            if let dimensions, dimensions.width > 0, dimensions.height > 0 {
                ratio = CGFloat(dimensions.width) / CGFloat(dimensions.height)
            }

            guard pictureRatio != ratio else { return }

            pictureRatio = ratio

            setNeedsLayout()
            onShape?()
        }

        /// The SDK's own report that the picture changed shape — a phone
        /// turned over swaps its two sides. It arrives off the main thread.
        func track(_ track: VideoTrack, didUpdateDimensions dimensions: Dimensions?) {
            DispatchQueue.main.async { [weak self] in
                guard let self, self.watched === track else { return }

                self.apply(dimensions)
            }
        }

        /// The picture's own rectangle inside a box, centred — the whole box
        /// until a frame has said what shape it is.
        ///
        /// `VideoView` in `.fit` already letterboxes inside whatever frame it
        /// is given, so this changes nothing about the picture; what it moves
        /// is the *view*, so the tile's own ground shows around a share
        /// instead of a black band the width of the row. The web hugs the
        /// picture the same way and the Android tile has `fitted()`.
        func fitted(_ box: CGRect) -> CGRect {
            guard pictureRatio > 0, box.width > 0, box.height > 0 else { return box }

            let shape = box.width / box.height

            if abs(shape - pictureRatio) < 0.001 { return box }

            if pictureRatio > shape {
                let height = box.width / pictureRatio

                return CGRect(x: box.minX, y: box.midY - height / 2, width: box.width, height: height)
            }

            let width = box.height * pictureRatio

            return CGRect(x: box.midX - width / 2, y: box.minY, width: width, height: box.height)
        }

        /// The picture where one has loaded, the initials until it does and for
        /// good where there is none or it can't be drawn. Decided by the
        /// picture itself: a roster comes many times a second while someone
        /// talks, and deciding by the address put an empty picture back over
        /// the initials of one that had failed, which left a blank.
        private func showPicture(covered: Bool) {
            picture.isHidden = covered || picture.image == nil
            initial.isHidden = covered || picture.image != nil
        }

        fileprivate func bind(_ cell: Cell) {
            let who = cell.person
            // A shared screen is what the person meant to be looked at, so it
            // takes the tile — and their camera goes in the corner of the same
            // tile rather than being lost, exactly as the web's item does.
            let sharing = who.screen != nil
            let shown = sharing ? who.screen : who.video

            person = who
            showsScreen = sharing

            if video.track !== shown { video.track = shown }

            // And what shape it is, which decides how much of the list a
            // shared screen gets and how wide a cell holding one has to be.
            watch(shown)

            // The web fits, it does not crop. `.bm-group-call-input-video-inner
            // video` is `object-fit: contain`, and the `cover` variant beside
            // it is behind a `.bm-cover-video` class nothing ever sets — so a
            // grid tile letterboxes and shows the whole frame. Filling here
            // cut the sides off every portrait phone camera in the grid.
            video.layoutMode = .fit

            video.isHidden = shown == nil

            let inset = (sharing && !isRow) ? who.video : nil

            if cameraInset.track !== inset { cameraInset.track = inset }

            cameraInset.isHidden = inset == nil

            handChip.isHidden = !who.handRaised

            // A raised hand breathes, as the web's chip does (`bm-call-hand`:
            // 1 to 1.12 and back over a second and a half).
            if who.handRaised, handChip.layer.animation(forKey: "hand") == nil, !UIAccessibility.isReduceMotionEnabled {
                let breathe = CABasicAnimation(keyPath: "transform.scale")
                breathe.fromValue = 1
                breathe.toValue = 1.12
                breathe.duration = 0.75
                breathe.autoreverses = true
                breathe.repeatCount = .infinity
                breathe.timingFunction = CAMediaTimingFunction(name: .easeInEaseOut)
                handChip.layer.add(breathe, forKey: "hand")
            } else if !who.handRaised {
                handChip.layer.removeAnimation(forKey: "hand")
            }

            // Someone who may not publish is a viewer, and the web says so on
            // the tile rather than leaving an unexplained empty square.
            let isViewer = !who.canPublish

            label.text = who.name

            // A muted person is worth marking, because in a grid the absence
            // of a speaking ring reads the same as silence. Marked the way the
            // web marks it: the struck-through microphone, and the word. The
            // list says it both ways — the web's audio row draws a microphone
            // whether it is on or off, so silence is never the absence of a
            // mark.
            //
            // A microphone a moderator keeps off wears the red chip of one
            // that is off with a speaker crossed out in it, on every tile and
            // row, so a moderator sees whom they muted: the web's
            // MicLockedChip.
            let held = who.micMuted && !isViewer
            let off = who.muted || held

            if isRow {
                micChip.isHidden = isViewer
                mic.set(held ? CallsIcons.silenced : off ? CallsIcons.micOff : CallsIcons.mic)

                // Red for off, translucent green for on — the two states the
                // web's `bm-mic-disabled` / `bm-mic-enabled` chips carry.
                micChip.backgroundColor = off
                    ? CallsTheme.recording.withAlphaComponent(0.92)
                    : CallsTheme.success.withAlphaComponent(0.22)

                mic.color = off ? .white : CallsTheme.success
            } else {
                micChip.isHidden = !off
                mic.set(held ? CallsIcons.silenced : CallsIcons.micOff)
                micChip.backgroundColor = CallsTheme.recording.withAlphaComponent(0.92)
                mic.color = .white
            }

            manage.isHidden = !CallsModeration.moderates(who)

            // Their media stopped arriving while they are still in the call
            // (`CallsStallWatch`): their camera's last frame blurred, and
            // their screen's too when nothing of theirs arrives, which the
            // tile says as "Reconnecting..." as for someone away. "Video
            // interrupted" only where the tile shows their camera, a still
            // screen sending nothing, and not under the placeholder of a
            // camera changing codec, which says why already.
            let stall = who.isLocal || who.reconnecting ? nil : who.stalled

            stalled.show(blurred: shown != nil && (stall == .all || (stall == .video && !sharing)),
                         notice: stall == .video && !sharing && !who.optimizing)
            insetStalled.show(blurred: inset != nil && stall != nil, notice: false)

            // Away for a moment: the veil, and no microphone mark under it,
            // which would say they muted themselves.
            reconnecting.isHidden = !who.reconnecting && stall != .all
            reconnecting.text = CallsTheme.string("reconnecting_self", fallback: "Reconnecting...")

            if who.reconnecting { micChip.isHidden = true }

            viewer.isHidden = !isViewer
            // Two words for the same rule, because the web uses two: someone
            // who cannot publish is a viewer of a video room and a listener to
            // an audio one.
            viewer.text = isRow
                ? CallsTheme.string("listener", fallback: "Listener")
                : CallsTheme.string("viewer", fallback: "Viewer")

            if who.speaking {
                // The web scales its glow with how loudly the person is
                // talking, clamped so that a whisper is still visible and a
                // shout does not take over the tile. Same curve here.
                let level = min(max(who.audioLevel * 100 * 5, 15), 90) / 100

                layer.borderWidth = CGFloat(1 + level * 3)
                layer.borderColor = CallsTheme.accent.cgColor
            } else {
                layer.borderWidth = 0
            }

            // In a row the avatar always shows: the screen sits above the info
            // line rather than in place of it.
            let covered = isRow ? false : shown != nil

            if avatarUrl != who.avatar {
                avatarUrl = who.avatar
                picture.image = nil

                CallsAvatars.load(who.avatar) { [weak self] image in
                    guard let self = self, self.avatarUrl == who.avatar else { return }

                    self.picture.image = image
                    self.showPicture(covered: !self.isRow && !self.video.isHidden)
                    // The placeholder's backdrop is the same face, blurred.
                    if self.optimizing.isUp { self.applyOptimizing() }
                }
            }

            initial.text = CallsAvatars.initials(of: who.name)
            showPicture(covered: covered)

            applyOptimizing()

            // The host's own view over the tile, where it gives one (CallsPieces): the same view again stays.
            let own = CallsPiecesStore.current.tile?(who)
            if own !== piece {
                piece?.removeFromSuperview()
                piece = own
                if let own { addSubview(own) }
            }

            setNeedsLayout()
        }

        /// The host's view over this tile (CallsPieces).
        private var piece: UIView?

        override func layoutSubviews() {
            super.layoutSubviews()

            if isRow { layoutRow() } else { layoutTile() }

            reconnecting.frame = bounds
            optimizing.frame = bounds
            stalled.frame = video.frame
            insetStalled.frame = cameraInset.frame
            outline.frame = bounds

            if let piece {
                piece.frame = bounds
                bringSubviewToFront(piece)
            }
        }

        private func layoutTile() {
            video.frame = bounds

            // `.bm-small-video`: eight points in from the bottom-right corner,
            // no taller than 72, and never more than a third of the tile it is
            // sitting in.
            let height = min(72, bounds.height / 3)
            let width = min(height * 16 / 9, bounds.width / 3)

            cameraInset.frame = CGRect(
                x: bounds.width - width - 8,
                y: bounds.height - height - 8,
                width: width,
                height: height
            )

            // `width: min(38%, 96px)` of the tile, as the web's avatar is, and
            // never taller than half of it, which a wide, low tile would be.
            let size = max(32, min(96, bounds.width * 0.38, bounds.height * 0.5)).rounded()

            picture.frame = CGRect(x: (bounds.width - size) / 2, y: (bounds.height - size) / 2, width: size, height: size)
            picture.layer.cornerRadius = size / 2

            placeInitials(picture.frame)

            // Where the stylesheet puts them, which is not where these were.
            //
            //   .bm-group-call-input-video-inner-info  bottom: 0; padding: 8px;
            //                                          padding-inline-end: 40px
            //   .bm-caller-status                      bottom: 8px; end: 8px
            //   .bm-hand-raised-status                 top: 8px; end: 8px
            //   .bm-viewer-badge                       top: 8px; end: 8px
            //
            // So the name runs along the bottom from the start edge, and the
            // crossed-out microphone sits at the end of the same line with the
            // name held clear of it. This had the name centred on the bottom
            // edge — where the dock lands on it — and the microphone alone in
            // the top corner.
            let chip: CGFloat = 24
            let pad: CGFloat = 8

            // The name in its glass pill, `.bm-info-name`: 9 in at the sides,
            // as wide as the name and no wider than the room the microphone
            // leaves it.
            label.textAlignment = .natural
            label.font = .systemFont(ofSize: 12, weight: .semibold)

            let pillHeight: CGFloat = 22
            var start = pad
            var room = max(0, bounds.width - pad * 2 - chip - pad)

            // A spotlighted tile says so before the name, 6 points from it: the star, 4, the word, padded 7 and 8.
            if spotlit {
                let star: CGFloat = 12
                let width = min(room, ceil(spotlightLabel.intrinsicContentSize.width) + star + 4 + 15)

                spotlightPill.frame = CGRect(x: start, y: bounds.height - pad - pillHeight, width: width, height: pillHeight)
                spotlightPill.layer.cornerRadius = pillHeight / 2
                spotlightStar.frame = CGRect(x: 7, y: (pillHeight - star) / 2, width: star, height: star)
                spotlightLabel.frame = CGRect(x: 7 + star + 4, y: 0, width: max(0, width - star - 4 - 15), height: pillHeight)

                start += width + 6
                room = max(0, room - width - 6)
            }

            let named = min(room, ceil(label.intrinsicContentSize.width) + 18)

            namePill.isHidden = (label.text ?? "").isEmpty
            namePill.frame = CGRect(x: start, y: bounds.height - pad - pillHeight, width: named, height: pillHeight)
            namePill.layer.cornerRadius = pillHeight / 2
            label.frame = namePill.frame.insetBy(dx: 9, dy: 0)

            chipFrame(handChip, icon: hand, rect: CGRect(x: bounds.width - chip - pad, y: pad, width: chip, height: chip))
            chipFrame(
                micChip,
                icon: mic,
                rect: CGRect(x: bounds.width - chip - pad, y: bounds.height - chip - pad, width: chip, height: chip)
            )

            // Under the hand, which shares the top end corner with it — the
            // stylesheet drops one of them to `top: 40px` when both are up.
            pill(viewer, right: bounds.width - pad, centreY: pad + chip + pad + 9)

            // `.bm-admin-controls`: 30 points, eight in from the top start
            // corner, the hand's corner being the other one. Pin for Me after
            // the ⋯, 6 from it, so a moderator's ⋯ stays where it always is.
            chipFrame(manage, icon: more, rect: CGRect(x: pad, y: pad, width: 30, height: 30))
            chipFrame(pin, icon: pinIcon, rect: CGRect(x: manage.isHidden ? pad : pad + 30 + 6, y: pad, width: 30, height: 30))
        }

        /// The initials' disc in the picture's place, its letters to its size:
        /// two of them at the 40 points of a row as at the 96 of a tile.
        private func placeInitials(_ frame: CGRect) {
            initial.frame = frame
            initial.layer.cornerRadius = frame.width / 2

            let points = max(10, (frame.width * 0.36).rounded())

            if initial.font.pointSize != points { initial.font = .systemFont(ofSize: points, weight: .semibold) }
        }

        /// A disc with the glyph inset, the way the stylesheet's call chip is
        /// drawn — the icon view fills whatever it is given, so the padding has
        /// to be a frame rather than a margin.
        private func chipFrame(_ chip: UIView, icon: UIView, rect: CGRect) {
            chip.frame = rect
            chip.layer.cornerRadius = rect.height / 2

            let inset = rect.height <= 24 ? CGFloat(5) : CGFloat(6)

            icon.frame = chip.bounds.insetBy(dx: inset, dy: inset)
        }

        /// The listener badge: a pill sized to its own word, ending at `right`.
        @discardableResult
        private func pill(_ label: UILabel, right: CGFloat, centreY: CGFloat) -> CGFloat {
            let width = min(140, label.intrinsicContentSize.width + 16)

            label.frame = CGRect(x: right - width, y: centreY - 9, width: width, height: 18)
            label.layer.cornerRadius = 9

            return width
        }

        /// `[ avatar ] name … [ listener ] [ hand ] [ mic ]`, over the screen
        /// when there is one — the web's audio row, in the same order.
        private func layoutRow() {
            let info = CGRect(
                x: 0,
                y: bounds.height - Tile.rowHeight,
                width: bounds.width,
                height: Tile.rowHeight
            )

            // The picture at its own shape rather than stretched across the
            // row. A phone's shared screen is taller than it is wide and would
            // otherwise sit as a narrow strip down the middle of a black band
            // the full width of the row.
            video.frame = fitted(CGRect(x: 0, y: 0, width: bounds.width, height: info.minY))

            let size: CGFloat = 40

            picture.frame = CGRect(x: 10, y: info.midY - size / 2, width: size, height: size)
            picture.layer.cornerRadius = size / 2

            placeInitials(picture.frame)

            var right = bounds.width - 10
            let chip: CGFloat = 28

            // The ⋯ last on the row, after the microphone, as the web's caller
            // actions end the audio row.
            if !manage.isHidden {
                chipFrame(manage, icon: more, rect: CGRect(x: right - chip, y: info.midY - chip / 2, width: chip, height: chip))
                right -= chip + 6
            }

            if !micChip.isHidden {
                chipFrame(micChip, icon: mic, rect: CGRect(x: right - chip, y: info.midY - chip / 2, width: chip, height: chip))
                right -= chip + 6
            }

            if !handChip.isHidden {
                chipFrame(handChip, icon: hand, rect: CGRect(x: right - chip, y: info.midY - chip / 2, width: chip, height: chip))
                right -= chip + 6
            }

            if !viewer.isHidden {
                right -= pill(viewer, right: right, centreY: info.midY) + 6
            }

            label.textAlignment = .natural
            label.font = .systemFont(ofSize: 14, weight: .semibold)
            // A row's name stands on the row itself, as the web's roster has it.
            namePill.isHidden = true
            label.frame = CGRect(
                x: picture.frame.maxX + 10,
                y: info.midY - 10,
                width: max(0, right - picture.frame.maxX - 10),
                height: 20
            )
        }
    }

    private var tiles: [Tile] = []
    private var cells: [Cell] = []
    /// How many of them are the web's "primary" row — pinned, or speaking in a
    /// broadcast. They are the first cells, so a count is all the layout needs.
    private var primaryCount = 0
    /// Whose camera changing codec VoiceOver has heard of, shared by every
    /// tile: a person's tile moves to another place in the grid as the order
    /// changes, and the same change is said once, not once a tile.
    private let optimizingSaid = CallsOptimizingSaid()

    override init(frame: CGRect) {
        super.init(frame: frame)

        scroll.showsVerticalScrollIndicator = false
        scroll.isScrollEnabled = false
        scroll.alwaysBounceVertical = false
        scroll.delegate = self

        // No bar is ever over the grid, so it has no edge to soften. iOS 26 softens a scroller's edges under what it
        // takes for the status bar, and a window shrunk into a band under the page's header is still taken to have
        // the whole screen's: the first row of the band was blurred where the status bar would be.
        #if compiler(>=6.2)
        if #available(iOS 26.0, *) {
            for edge in [scroll.topEdgeEffect, scroll.bottomEdgeEffect, scroll.leftEdgeEffect, scroll.rightEdgeEffect] {
                edge.isHidden = true
            }
        }
        #endif

        addSubview(scroll)
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    /// Redraw for whoever is in the room now.
    func show(_ participants: [CallsRoomParticipant]) {
        isHidden = participants.isEmpty
        shownPeople = participants

        if participants.isEmpty {
            tiles.forEach {
                $0.release()
                $0.removeFromSuperview()
            }

            tiles = []
            cells = []
            primaryCount = 0
            optimizingSaid.keep([])
            return
        }

        var built: [Cell]

        if audioRoom {
            // The web's own order for a list: whoever is sharing first, then
            // everyone with a microphone on, then the rest. A row that jumps
            // about is unreadable, so within each group the roster's order is
            // kept as it is.
            let sharing = participants.filter { $0.screen != nil }
            let talking = participants.filter { $0.screen == nil && !$0.muted }
            let quiet = participants.filter { $0.screen == nil && $0.muted }

            built = (sharing + talking + quiet).map { Cell(person: $0) }
            primaryCount = 0
        } else {
            // The web's own split (spotlight.tsx's mainKeys). Whoever a
            // moderator put in the spotlight goes in the primary row, in the
            // order they were spotlighted; while nobody is, this user's own
            // pins, and anyone who may publish while the room is broadcasting
            // — those are the people the room is there to watch.
            let main = CallsSpotlight.main(participants, spotlight: spotlight, pinned: pinned, broadcast: broadcastRoom)
            let primary = main.compactMap { identity in participants.first { $0.identity == identity } }
            let taken = Set(main)
            let rest = participants.filter { !taken.contains($0.identity) }

            // And its order for the rest: anyone with a picture first, then
            // whoever is talking, then everybody else — a phone shows very few
            // tiles, so what is in them matters more than anywhere else.
            // A camera changing codec is still a picture: its tile keeps its
            // place under the placeholder rather than dropping down the grid
            // for the second the camera is away.
            let pictured: (CallsRoomParticipant) -> Bool = { $0.video != nil || $0.screen != nil || $0.optimizing }
            let seen = rest.filter { pictured($0) }
            let heard = rest.filter { !pictured($0) && $0.speaking }
            let quiet = rest.filter { !pictured($0) && !$0.speaking }

            // And your own tile last, wherever the ordering above left it.
            // The web moves it to the end of the page for the same reason —
            // you know what you look like, and the screen is for the people
            // you are talking to. It arrives first in the roster, so without
            // this a call between two people put you on top and them
            // underneath, which is the wrong way round on every platform.
            //
            // Not out of the primary row: a pinned tile, or a speaker in a
            // broadcast room, is what the room came to watch and stays where
            // it is. The web guards the same way.
            let ordered = seen + heard + quiet

            built = (primary + ordered.filter { !$0.isLocal } + ordered.filter { $0.isLocal })
                .map { Cell(person: $0) }

            primaryCount = primary.count
        }

        cells = built

        while tiles.count < cells.count {
            let tile = Tile()

            tile.isRow = audioRoom
            tile.optimizing.said = optimizingSaid

            // A picture reporting its shape changes how much room its tile
            // wants, and that is worked out here rather than in the tile.
            tile.onShape = { [weak self] in self?.setNeedsLayout() }

            tile.addGestureRecognizer(
                UILongPressGestureRecognizer(target: self, action: #selector(tileHeld(_:)))
            )

            tile.onManage = { [weak self, weak tile] in
                guard let person = tile?.person else { return }

                self?.onPerson?(person)
            }

            tile.onPin = { [weak self, weak tile] in
                guard let person = tile?.person else { return }

                self?.onPin?(person)
            }

            tiles.append(tile)
            scroll.addSubview(tile)
        }

        // Anyone who left takes their renderer with them.
        while tiles.count > cells.count {
            let tile = tiles.removeLast()

            tile.release()
            tile.removeFromSuperview()
        }

        rebind()

        // Whoever's camera is no longer changing may be told of the next
        // change.
        optimizingSaid.keep(Set(participants.filter(\.optimizing).map(\.identity)))
    }

    /// Redraw what is already there, for what changes while nobody joins or
    /// leaves.
    private func rebind() {
        // Labeled Spotlight, for everyone, as the main tiles are drawn.
        let spotlit = Set(CallsSpotlight.spotlit(cells.map(\.person), spotlight: spotlight))

        for (index, cell) in cells.enumerated() where index < tiles.count {
            tiles[index].isRow = audioRoom
            tiles[index].bind(cell)
            // Tiles are reused as people come and go: the outline, the label and the pin follow the person.
            tiles[index].moderating = moderating != nil && cell.person.identity == moderating
            tiles[index].setSpotlit(spotlit.contains(cell.person.identity))
            tiles[index].setPins(offered: pinsOffered, pinned: pinned.contains(cell.person.identity))
        }

        setNeedsLayout()
    }

    /// Stop paying for the tiles nobody can see.
    ///
    /// The SDK's adaptive stream decides a `VideoView` is worth receiving from
    /// `didLayout && !isHidden && isEnabled` — it has no idea whether the view
    /// is actually on screen, so a tile scrolled below the fold goes on being
    /// subscribed and decoded. (The web does not have this problem: LiveKit's
    /// browser SDK watches an `IntersectionObserver`, which is what makes its
    /// own sideways paging free.)
    ///
    /// `isEnabled` is the SDK's own hook for exactly this — "useful for
    /// performance optimizations with UICollectionViewCell etc." — and turning
    /// it off both pauses the renderer and drops the subscription, so the
    /// server stops sending within the adaptive stream's 0.3 s tick.
    private func cullOffscreen() {
        let visible = CGRect(origin: scroll.contentOffset, size: scroll.bounds.size)

        for tile in tiles {
            // A pinned tile lives outside the scroller and is always on show.
            let shown = tile.superview === scroll ? tile.frame.intersects(visible) : true

            tile.video.isEnabled = shown
            tile.cameraInset.isEnabled = shown
        }
    }

    func scrollViewDidScroll(_ scrollView: UIScrollView) {
        cullOffscreen()
    }

    @objc private func tileHeld(_ recogniser: UILongPressGestureRecognizer) {
        guard
            recogniser.state == .began,
            let tile = recogniser.view as? Tile,
            let person = tile.person
        else { return }

        onPerson?(person)
    }

    /// Laid out by hand rather than with constraints: the shape changes with
    /// the head count, and rebuilding a constraint set on every join is both
    /// slower and easier to get wrong than arithmetic.
    override func layoutSubviews() {
        super.layoutSubviews()

        scroll.frame = bounds

        guard !tiles.isEmpty else {
            scroll.contentSize = bounds.size
            return
        }

        if audioRoom {
            layoutList()
            return
        }

        layoutWall()
    }

    /// The web's `group-video-grid.tsx`, on a phone.
    ///
    /// Two bands. Whoever is pinned — or, in a broadcast, whoever may speak —
    /// fills a single column down everything but the last hundred points;
    /// everybody else shares that hundred-point strip. With nobody pinned in
    /// an ordinary room there is no primary band at all and the rest take the
    /// whole area, which is the common case on a phone.
    private func layoutWall() {
        let strip: CGFloat = 100
        let primary = min(primaryCount, tiles.count)
        let rest = Array(tiles.dropFirst(primary))

        // The primary band sits *outside* the scroller. The web keeps it still
        // and pages the strip beneath it sideways, and a pinned tile that
        // scrolled away with the strip would be the opposite of pinned.
        for tile in tiles.prefix(primary) where tile.superview !== self {
            addSubview(tile)
        }

        for tile in rest where tile.superview !== scroll {
            scroll.addSubview(tile)
        }

        // The web's grid is padded 4 on top and either side, and each tile 4
        // more inside its cell: 8 from the edges and between tiles, and the
        // last row flush with the grid's floor, where the bar's own padding
        // takes over.
        let area = CGRect(x: Self.gutter, y: Self.gutter, width: max(0, bounds.width - Self.gutter * 2), height: bounds.height)
        var box = area
        var beside = false

        if primary > 0 {
            // A picture taller than it is wide cannot be handed the whole
            // width: the band is then mostly the ground either side of it.
            // Somebody sharing a phone is exactly that — about 9:19.5 — and
            // the stack was the only division this had, so pinning their share
            // drew it as a narrow strip down the middle of a very wide band
            // with everyone else squashed into a hundred points underneath.
            //
            // A tall band stands beside the rest instead, keeping its own
            // shape and taking only the width that shape needs; the others
            // have what is left, as a column rather than a strip. Only on a
            // screen wider than it is tall — a phone turned on its side —
            // only when there is room for a tile either side of the division,
            // and only when there is anybody to stand beside: with everyone
            // pinned the band is the whole call and takes the whole screen.
            // The web divides on the same four tests.
            let shape = tallest(tiles.prefix(primary))
            let minStrip = Self.minStrip * Self.tileRatio

            beside = shape < 1
                && !rest.isEmpty
                && area.width > area.height
                && area.width > minStrip * 2

            // `isMobile()` in the web: the primary row is one column of them,
            // however many there are.
            let height = (beside || rest.isEmpty ? area.height : area.height - strip) / CGFloat(primary)

            let width = beside
                ? min(max(area.height / CGFloat(primary) * shape, minStrip), area.width - minStrip)
                : area.width

            for (index, tile) in tiles.prefix(primary).enumerated() {
                tile.frame = inset(CGRect(x: area.minX, y: area.minY + CGFloat(index) * height, width: width, height: height))
            }

            box = beside
                ? CGRect(x: area.minX + width, y: area.minY, width: area.width - width, height: area.height)
                : CGRect(x: area.minX, y: area.maxY - strip, width: area.width, height: strip)
        }

        scroll.frame = box

        guard !rest.isEmpty else {
            scroll.contentSize = box.size
            scroll.isScrollEnabled = false

            return
        }

        if primary > 0 && !beside {
            // One row running off to the right, which is where the web's own
            // strip puts the overflow — `overflow-x: auto`, no pager.
            let width = stripWidth(box.size, ratio: widest(rest))

            for (index, tile) in rest.enumerated() {
                tile.frame = inset(CGRect(x: CGFloat(index) * width, y: 0, width: width, height: box.height))
            }

            scroll.contentSize = CGSize(width: CGFloat(rest.count) * width, height: box.height)
        } else {
            // Beside a tall band this is a column and not a strip, so it is
            // laid out as a wall too — which is what the web does with it.
            let shape = wallShape(count: rest.count, box: box.size, ratio: widest(rest))
            let width = box.width / CGFloat(shape.columns)
            let height = box.height / CGFloat(shape.rows)

            for (index, tile) in rest.enumerated() {
                tile.frame = inset(CGRect(
                    x: CGFloat(index % shape.columns) * width,
                    y: CGFloat(index / shape.columns) * height,
                    width: width,
                    height: height
                ))
            }

            // With no band above it the web pages sideways too; a full-height
            // wall scrolls down instead, which is the gesture people already
            // make here. Either way each tile keeps the size the web would
            // have drawn it at.
            let drawn = Int(ceil(Double(rest.count) / Double(shape.columns)))

            scroll.contentSize = CGSize(width: box.width, height: max(box.height, CGFloat(drawn) * height))
        }

        scroll.isScrollEnabled = scroll.contentSize.width > box.width || scroll.contentSize.height > box.height

        cullOffscreen()
    }

    /// How wide one tile is in the strip under a pinned speaker.
    ///
    /// Not the strip divided by the people in it. A strip is one tile tall and
    /// the web lays it out by how many tiles fit across it, paging sideways
    /// past that:
    ///
    ///     itemWidth = stripHeight × ratio
    ///     columns   = ceil(width / itemWidth)
    ///
    /// So one person beside a pinned speaker gets a third of the width, not
    /// all of it, and the strip looks the same whether one person is in it or
    /// nine.
    ///
    /// The ratio is the widest picture in the strip rather than 16:9, because
    /// a cell has to hold whatever lands in it — a screen shared from a laptop
    /// is wider than a camera, and one shared from a phone is narrower.
    private func stripWidth(_ box: CGSize, ratio: CGFloat) -> CGFloat {
        let item = box.height * ratio

        guard item > 0 else { return box.width }

        let columns = max(1, Int(ceil(box.width / item)))

        return box.width / CGFloat(columns)
    }

    /// The widest picture among these tiles, and `tileRatio` when none of them
    /// has said what shape it is yet.
    ///
    /// The widest, because a cell has to hold whichever picture lands in it
    /// and the widest is the one that needs the most room. The web works the
    /// same figure out under the same name, `maxRatio`.
    private func widest<S: Sequence>(_ of: S) -> CGFloat where S.Element == Tile {
        of.reduce(Self.tileRatio) { max($0, $1.pictureRatio) }
    }

    /// The tallest — the smallest ratio — for the band a pinned tile is drawn
    /// in, because that is the shape the band has to make room for. The web's
    /// `minRatio`. A tile that has not reported is left out of the reckoning
    /// rather than counted as 16:9.
    private func tallest<S: Sequence>(_ of: S) -> CGFloat where S.Element == Tile {
        of.reduce(Self.tileRatio) { $1.pictureRatio > 0 ? min($0, $1.pictureRatio) : $0 }
    }

    /// The arrangement that makes the pictures biggest.
    ///
    /// Every column count is a candidate. Each one implies a number of rows,
    /// and so a cell of `width / columns` by `height / rows`; the picture
    /// letterboxed into that cell — which is what the renderer draws — has an
    /// area. The largest area wins. One loop, no special cases, and it answers
    /// for any number of people on any screen.
    ///
    /// The picture, not a 16:9 one: `ratio` is what is actually being drawn,
    /// because a phone sharing its screen publishes something taller than it
    /// is wide and a cell shaped for a camera has no room for it.
    ///
    /// It is why two people stack on a phone held upright and sit side by side
    /// on its side, without either being written down: at 402 by 874 one column
    /// of two fits a 402-wide picture and two columns of one fit a 201-wide
    /// one, and turning the phone reverses it exactly.
    ///
    /// What it replaces was `ceil(sqrt(count))` walked down until the tiles
    /// cleared a minimum, and then `if count == 2 { one column }` on top of
    /// that — at every size, which is what the web says too. That is why a
    /// phone turned on its side showed two very wide letterboxes with a small
    /// avatar in each.
    ///
    /// The minimum stays as a ceiling on how many tiles may share a screen: a
    /// phone showing nine faces is showing nine thumbnails. Anything past what
    /// fits scrolls, as it did before.
    private func wallShape(count: Int, box: CGSize, ratio: CGFloat) -> (columns: Int, rows: Int) {
        guard count > 0, box.width > 0, box.height > 0 else { return (1, 1) }

        let minHeight = Self.minStrip
        let minWidth = minHeight * ratio

        let mostColumns = min(count, max(1, Int(box.width / minWidth)))
        let mostRows = max(1, Int(box.height / minHeight))

        var best = (columns: 1, rows: count)
        var bestArea: CGFloat = -1

        for columns in 1...mostColumns {
            let needed = Int(ceil(Double(count) / Double(columns)))
            let rows = min(needed, mostRows)

            let cellWidth = box.width / CGFloat(columns)
            let cellHeight = box.height / CGFloat(rows)

            // The picture inside the cell, letterboxed the way the renderer
            // letterboxes it. The cell's own area would pick the arrangement
            // with the least dead space rather than the biggest faces.
            let drawn = min(cellWidth, cellHeight * ratio)
            let area = drawn * (drawn / ratio)

            if area > bestArea {
                bestArea = area
                best = (columns, rows)
            }
        }

        return best
    }

    /// The web's gutters: its grid's padding, and each tile's inside its cell.
    private static let gutter: CGFloat = 4

    /// The gap between tiles, taken out of the cell rather than added to it,
    /// so the arithmetic above stays the web's.
    private func inset(_ rect: CGRect) -> CGRect {
        rect.insetBy(dx: Self.gutter, dy: Self.gutter)
    }

    /// One row per person down the page, the web's 10-point margin and
    /// 8-point gap, scrolling when there are more people than fit.
    ///
    /// Somebody sharing their screen takes the stage.
    ///
    /// An audio call has no pictures in it, so this is a list of rows — and a
    /// share used to be squeezed into the sharer's row as a band of at most
    /// 320 points, drawn as a 16:9 picture whatever it actually was. That was
    /// tolerable while a share was a laptop's. A phone's is about 9:19.5, and
    /// the same band drew it as a sliver a seventh of the row wide with the
    /// rest of the row black, under a screenful of list nothing was using.
    ///
    /// So a sharing row takes the height the roster does not need, the way the
    /// web's `flex: 1 1 auto` does, and keeps a floor of 45% of the screen
    /// when the roster is long enough to want all of it — the list scrolls
    /// rather than squeezing the thing everyone is looking at. Two people
    /// sharing at once halve the stage between them, which falls out of the
    /// arithmetic rather than being written down.
    private func layoutList() {
        let inset: CGFloat = 10
        let gap: CGFloat = 8
        let width = max(0, bounds.width - inset * 2)

        // A list has no primary band, so nothing belongs outside the scroller.
        for tile in tiles where tile.superview !== scroll {
            scroll.addSubview(tile)
        }

        let sharing = tiles.filter { $0.showsScreen }.count
        let rows = CGFloat(tiles.count - sharing) * Tile.rowHeight
        let gaps = CGFloat(max(0, tiles.count - 1)) * gap
        let spare = bounds.height - inset * 2 - rows - gaps

        var stage: CGFloat = 0

        if sharing > 0 {
            stage = max(spare / CGFloat(sharing), max(bounds.height * 0.45, Tile.rowHeight + 60))
        }

        var top = inset

        for tile in tiles {
            let height = tile.showsScreen ? stage : Tile.rowHeight

            tile.frame = CGRect(x: inset, y: top, width: width, height: height)

            top += height + gap
        }

        scroll.contentSize = CGSize(width: bounds.width, height: max(bounds.height, top - gap + inset))
        scroll.isScrollEnabled = scroll.contentSize.height > bounds.height

        cullOffscreen()
    }
}
