import UIKit

/// One line in a panel.
struct CallsPanelRow {
    let title: String
    var selected: Bool = false
    var destructive: Bool = false
    /// A second, quieter line saying what the row does, as the web's moderation menus say it.
    var note: String? = nil
    let run: () -> Void
}

/// The call's own way of asking a question.
///
/// Configure and Participants used to be `UIAlertController` action sheets.
/// They worked, and they looked like what they were: a piece of iOS put on top
/// of the call rather than a piece of the call. They did not look built into
/// the call natively, and the arrow on the popover pointing back
/// at the dock made the seam obvious.
///
/// This is the same list drawn on the call screen itself, in the language the
/// rest of it already speaks: the glass the peer notice and the error card are
/// made of, the card radius, the dock's own width. Nothing is presented, so
/// nothing takes the screen away from the call — which also settles the second
/// half of the report, a video that stopped while the sheet was up: a view
/// LiveKit thinks nobody is looking at is a view it may stop feeding, and an
/// alert covering the stage is exactly that.
final class CallsPanel: UIView {
    private let card = UIView()
    private let rows = UIStackView()
    private var onDismiss: (() -> Void)?

    /// The second line of the header, kept so a panel showing a figure that
    /// keeps moving can be handed the new one without being rebuilt.
    private weak var detail: UILabel?

    override init(frame: CGRect) {
        super.init(frame: frame)

        // Clear rather than dimmed: the web does not dim behind its Configure
        // panel either, and the call is the thing worth looking at.
        backgroundColor = .clear

        card.translatesAutoresizingMaskIntoConstraints = false
        card.backgroundColor = UIColor(white: 0, alpha: 0.82)
        card.layer.cornerRadius = 14
        card.layer.borderWidth = 1
        card.layer.borderColor = UIColor(white: 1, alpha: 0.08).cgColor
        card.clipsToBounds = true

        rows.translatesAutoresizingMaskIntoConstraints = false
        rows.axis = .vertical
        rows.spacing = 0

        card.addSubview(rows)
        addSubview(card)

        NSLayoutConstraint.activate([
            rows.leadingAnchor.constraint(equalTo: card.leadingAnchor),
            rows.trailingAnchor.constraint(equalTo: card.trailingAnchor),
            rows.topAnchor.constraint(equalTo: card.topAnchor),
            rows.bottomAnchor.constraint(equalTo: card.bottomAnchor)
        ])

        // Off the card alone: its rows are its own.
        addGestureRecognizer(CallsGroundTap(target: self, action: #selector(backdropTapped)) { [weak self] in $0 === self?.card })
    }

    required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }

    /// A tap anywhere off the card closes it, which is what an action sheet
    /// did and what anyone will try first.
    @objc private func backdropTapped() {
        onDismiss?()
    }

    override func point(inside point: CGPoint, with event: UIEvent?) -> Bool {
        // The panel only exists while it is shown, so it may claim the whole
        // screen: outside the card that claim is what closes it.
        bounds.contains(point)
    }

    /// Put it on the call, with the card just above whatever the dock's top
    /// edge is — the same twelve points the error card leaves.
    func place(in host: UIView, above dock: UIView) {
        translatesAutoresizingMaskIntoConstraints = false

        host.addSubview(self)

        NSLayoutConstraint.activate([
            leadingAnchor.constraint(equalTo: host.leadingAnchor),
            trailingAnchor.constraint(equalTo: host.trailingAnchor),
            topAnchor.constraint(equalTo: host.topAnchor),
            bottomAnchor.constraint(equalTo: host.bottomAnchor),

            card.centerXAnchor.constraint(equalTo: centerXAnchor),
            card.bottomAnchor.constraint(equalTo: dock.topAnchor, constant: -12),
            card.leadingAnchor.constraint(greaterThanOrEqualTo: leadingAnchor, constant: 16),
            card.trailingAnchor.constraint(lessThanOrEqualTo: trailingAnchor, constant: -16),
            card.widthAnchor.constraint(lessThanOrEqualToConstant: 420),
            // The dock's own width at every size, so the two read as one
            // object rather than a card and a row that happen to be near
            // each other.
            card.widthAnchor.constraint(greaterThanOrEqualTo: dock.widthAnchor),
            card.topAnchor.constraint(greaterThanOrEqualTo: safeAreaLayoutGuide.topAnchor, constant: 16)
        ])
    }

    func fill(title: String, message: String?, entries: [CallsPanelRow], dismiss: @escaping () -> Void) {
        onDismiss = dismiss

        rows.arrangedSubviews.forEach { $0.removeFromSuperview() }

        rows.addArrangedSubview(header(title: title, message: message))

        for entry in entries {
            rows.addArrangedSubview(separator())
            rows.addArrangedSubview(row(entry))
        }
    }

    /// A new second line for a panel already on screen.
    ///
    /// The byte counts behind the gear are sampled every two seconds and the
    /// web redraws them as they come, so a panel left open there counts up.
    /// Filling this once at open time and leaving it would have shown a figure
    /// frozen at whatever it was when the card appeared.
    func update(message: String?) {
        guard let detail = detail else { return }

        detail.text = message ?? ""
    }

    private func header(title: String, message: String?) -> UIView {
        let holder = UIView()
        let stack = UIStackView()

        stack.translatesAutoresizingMaskIntoConstraints = false
        stack.axis = .vertical
        stack.spacing = 4

        let name = UILabel()
        name.font = .systemFont(ofSize: 15, weight: .semibold)
        name.textColor = .white
        name.numberOfLines = 2
        name.text = title
        stack.addArrangedSubview(name)

        if let message = message, !message.isEmpty {
            let detail = UILabel()
            detail.font = .systemFont(ofSize: 13)
            detail.textColor = UIColor(white: 1, alpha: 0.65)
            detail.numberOfLines = 0
            detail.text = message
            stack.addArrangedSubview(detail)

            self.detail = detail
        }

        holder.addSubview(stack)

        NSLayoutConstraint.activate([
            stack.leadingAnchor.constraint(equalTo: holder.leadingAnchor, constant: 16),
            stack.trailingAnchor.constraint(equalTo: holder.trailingAnchor, constant: -16),
            stack.topAnchor.constraint(equalTo: holder.topAnchor, constant: 14),
            stack.bottomAnchor.constraint(equalTo: holder.bottomAnchor, constant: -14)
        ])

        return holder
    }

    private func separator() -> UIView {
        let line = UIView()

        line.backgroundColor = UIColor(white: 1, alpha: 0.08)
        line.translatesAutoresizingMaskIntoConstraints = false
        line.heightAnchor.constraint(equalToConstant: 1 / UIScreen.main.scale).isActive = true

        return line
    }

    private func row(_ entry: CallsPanelRow) -> UIView {
        let button = CallsPanelRowView(entry: entry) { [weak self] in
            self?.onDismiss?()
            entry.run()
        }

        button.translatesAutoresizingMaskIntoConstraints = false
        button.heightAnchor.constraint(greaterThanOrEqualToConstant: 48).isActive = true

        return button
    }
}

/// One tappable line, highlighting while the finger is down the way a sheet's
/// row does.
private final class CallsPanelRowView: UIControl {
    private let run: () -> Void

    init(entry: CallsPanelRow, run: @escaping () -> Void) {
        self.run = run

        super.init(frame: .zero)

        let title = UILabel()
        title.translatesAutoresizingMaskIntoConstraints = false
        title.font = .systemFont(ofSize: 15)
        title.textColor = entry.destructive
            ? CallsTheme.recording
            : .white
        title.numberOfLines = 1
        title.text = entry.title
        title.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)

        let text = UIStackView(arrangedSubviews: [ title ])
        text.translatesAutoresizingMaskIntoConstraints = false
        text.axis = .vertical
        text.spacing = 2
        text.isUserInteractionEnabled = false

        if let note = entry.note, !note.isEmpty {
            let line = UILabel()
            line.font = .systemFont(ofSize: 12)
            line.textColor = UIColor(white: 1, alpha: 0.6)
            line.numberOfLines = 0
            line.text = note
            text.addArrangedSubview(line)
        }

        addSubview(text)

        NSLayoutConstraint.activate([
            text.leadingAnchor.constraint(equalTo: leadingAnchor, constant: 16),
            text.centerYAnchor.constraint(equalTo: centerYAnchor),
            text.topAnchor.constraint(greaterThanOrEqualTo: topAnchor, constant: 10),
            text.bottomAnchor.constraint(lessThanOrEqualTo: bottomAnchor, constant: -10)
        ])

        let tick = UILabel()
        tick.translatesAutoresizingMaskIntoConstraints = false
        tick.font = .systemFont(ofSize: 15, weight: .semibold)
        tick.textColor = .white
        tick.text = entry.selected ? "✓" : ""

        addSubview(tick)

        NSLayoutConstraint.activate([
            tick.trailingAnchor.constraint(equalTo: trailingAnchor, constant: -16),
            tick.centerYAnchor.constraint(equalTo: centerYAnchor),
            tick.leadingAnchor.constraint(greaterThanOrEqualTo: text.trailingAnchor, constant: 10)
        ])

        addTarget(self, action: #selector(pressed), for: .touchUpInside)
        addTarget(self, action: #selector(down), for: [.touchDown, .touchDragEnter])
        addTarget(self, action: #selector(up), for: [.touchUpInside, .touchUpOutside, .touchCancel, .touchDragExit])
    }

    required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }

    @objc private func pressed() { run() }
    @objc private func down() { backgroundColor = UIColor(white: 1, alpha: 0.1) }
    @objc private func up() { backgroundColor = .clear }
}

/// Add Person as a host gives it (realtime-ui's `people` and `addPerson`, with the rings so far): none, and the dock has
/// no such button, so a host that knows nothing of it draws nothing new. On the main thread.
struct CallsAddPerson {
    struct Person: Equatable {
        let id: String
        let name: String
        let avatar: String
    }

    /// Someone rung into the call: `ringing`, then `answered`, `rejected`, `busy`, `no_answer` or `cancelled`.
    struct Ring: Equatable {
        let id: String
        let to: String
        let state: String
        let canCancel: Bool
    }

    /// Whom the user may bring in, asked as the panel opens.
    let people: ( @escaping ( [ Person ] ) -> Void ) -> Void
    /// Rings them in: `done` with nil, or the error to show.
    let add: ( Person, @escaping ( String? ) -> Void ) -> Void
    /// The rings so far, asked each time the panel draws: a person's last one is what their row says.
    let rings: () -> [ Ring ]
    /// Calls a ring off: `done` with nil, or the error to show.
    let cancel: ( String, @escaping ( String? ) -> Void ) -> Void
}

enum CallsAddPersonStore {
    static var current: CallsAddPerson?
}

/// Add Person (realtime-ui's add-person.tsx): whom the user may bring in, as the call settings' card, on the glass of the
/// panel above. A press rings them. The card then stays and their row says how the ring stands, with Cancel while it
/// rings, where the web closes it: the row is the one place a phone says so. A failure closes it and the screen says why.
final class CallsAddPersonPanel: UIView {
    private let card = UIView()
    private let scroll = UIScrollView()
    private let rows = UIStackView()
    private let close: () -> Void
    private let failed: ( String ) -> Void

    /// Nil until the host answers.
    private var people: [ CallsAddPerson.Person ]?
    private var adding: String?
    private var cancelling: Set<String> = []

    /// What the rows were last drawn from.
    private struct Drawn: Equatable {
        let people: [ CallsAddPerson.Person ]?
        let rings: [ CallsAddPerson.Ring ]
        let adding: String?
        let cancelling: Set<String>
    }

    private var drawn: Drawn?

    init( close: @escaping () -> Void, failed: @escaping ( String ) -> Void ) {
        self.close = close
        self.failed = failed

        super.init( frame: .zero )

        backgroundColor = .clear

        card.translatesAutoresizingMaskIntoConstraints = false
        card.backgroundColor = UIColor( white: 0, alpha: 0.82 )
        card.layer.cornerRadius = 14
        card.layer.borderWidth = 1
        card.layer.borderColor = UIColor( white: 1, alpha: 0.08 ).cgColor
        card.clipsToBounds = true
        card.accessibilityViewIsModal = true

        let title = UILabel()
        title.translatesAutoresizingMaskIntoConstraints = false
        title.font = .systemFont( ofSize: 15, weight: .semibold )
        title.textColor = .white
        title.text = CallsTheme.string( "add_person", fallback: "Add Person" )
        title.accessibilityTraits = .header
        // The rows give way where the screen's room runs out, never the title.
        title.setContentCompressionResistancePriority( .required, for: .vertical )

        scroll.translatesAutoresizingMaskIntoConstraints = false
        scroll.alwaysBounceVertical = false

        rows.translatesAutoresizingMaskIntoConstraints = false
        rows.axis = .vertical

        scroll.addSubview( rows )
        card.addSubview( title )
        card.addSubview( scroll )
        addSubview( card )

        // As tall as its rows, until the screen's room runs out and they scroll.
        let fits = scroll.heightAnchor.constraint( equalTo: rows.heightAnchor )
        fits.priority = .defaultHigh

        NSLayoutConstraint.activate( [
            title.leadingAnchor.constraint( equalTo: card.leadingAnchor, constant: 16 ),
            title.trailingAnchor.constraint( equalTo: card.trailingAnchor, constant: -16 ),
            title.topAnchor.constraint( equalTo: card.topAnchor, constant: 14 ),
            scroll.leadingAnchor.constraint( equalTo: card.leadingAnchor ),
            scroll.trailingAnchor.constraint( equalTo: card.trailingAnchor ),
            scroll.topAnchor.constraint( equalTo: title.bottomAnchor, constant: 10 ),
            scroll.bottomAnchor.constraint( equalTo: card.bottomAnchor ),
            rows.leadingAnchor.constraint( equalTo: scroll.frameLayoutGuide.leadingAnchor ),
            rows.trailingAnchor.constraint( equalTo: scroll.frameLayoutGuide.trailingAnchor ),
            rows.topAnchor.constraint( equalTo: scroll.contentLayoutGuide.topAnchor ),
            rows.bottomAnchor.constraint( equalTo: scroll.contentLayoutGuide.bottomAnchor ),
            fits,
        ] )

        // Off the card alone: its rows are its own.
        addGestureRecognizer( CallsGroundTap( target: self, action: #selector( backdropTapped ) ) { [weak self] in $0 === self?.card } )
    }

    required init?( coder: NSCoder ) { fatalError( "init(coder:) has not been implemented" ) }

    @objc private func backdropTapped() {
        close()
    }

    override func point( inside point: CGPoint, with event: UIEvent? ) -> Bool {
        bounds.contains( point )
    }

    /// On the call, the card just above the dock, as the panel above.
    func place( in host: UIView, above dock: UIView ) {
        translatesAutoresizingMaskIntoConstraints = false

        host.addSubview( self )

        NSLayoutConstraint.activate( [
            leadingAnchor.constraint( equalTo: host.leadingAnchor ),
            trailingAnchor.constraint( equalTo: host.trailingAnchor ),
            topAnchor.constraint( equalTo: host.topAnchor ),
            bottomAnchor.constraint( equalTo: host.bottomAnchor ),

            card.centerXAnchor.constraint( equalTo: centerXAnchor ),
            card.bottomAnchor.constraint( equalTo: dock.topAnchor, constant: -12 ),
            card.leadingAnchor.constraint( greaterThanOrEqualTo: leadingAnchor, constant: 16 ),
            card.trailingAnchor.constraint( lessThanOrEqualTo: trailingAnchor, constant: -16 ),
            card.widthAnchor.constraint( lessThanOrEqualToConstant: 420 ),
            card.widthAnchor.constraint( greaterThanOrEqualTo: dock.widthAnchor ),
            card.topAnchor.constraint( greaterThanOrEqualTo: safeAreaLayoutGuide.topAnchor, constant: 16 ),
        ] )
    }

    /// Asks the host whom it may offer, and draws what it has meanwhile.
    func open() {
        draw()

        CallsAddPersonStore.current?.people { [weak self] found in
            guard let self else { return }

            self.people = found
            self.draw()
        }
    }

    /// Who is offered and how each ring stands, again: the rings change while it is open. Only where something did, as the
    /// call draws this with each of its changes, and rows made again would drop a finger on one.
    func draw() {
        let rings = CallsAddPersonStore.current?.rings() ?? []
        let now = Drawn( people: people, rings: rings, adding: adding, cancelling: cancelling )

        guard now != drawn else { return }

        drawn = now
        rows.arrangedSubviews.forEach { $0.removeFromSuperview() }

        guard let people else {
            rows.addArrangedSubview( line( CallsTheme.string( "add_person_loading", fallback: "Loading..." ) ) )
            return
        }

        guard !people.isEmpty else {
            rows.addArrangedSubview( line( CallsTheme.string( "add_person_empty", fallback: "There is no one else to add" ) ) )
            return
        }

        for person in people {
            rows.addArrangedSubview( separator() )
            rows.addArrangedSubview( row( person, ring: rings.last { $0.to == person.id } ) )
        }
    }

    /// How a ring stands, in the app's words: `add_person_ringing`, `add_person_answered`, `add_person_rejected`,
    /// `add_person_busy`, `add_person_no_answer`, `add_person_cancelled`.
    static func said( _ state: String ) -> String {
        switch state {
        case "ringing": return CallsTheme.string( "add_person_ringing", fallback: "Ringing…" )
        case "answered": return CallsTheme.string( "add_person_answered", fallback: "Answered" )
        case "rejected": return CallsTheme.string( "add_person_rejected", fallback: "Declined" )
        case "busy": return CallsTheme.string( "add_person_busy", fallback: "Busy" )
        case "no_answer": return CallsTheme.string( "add_person_no_answer", fallback: "No answer" )
        case "cancelled": return CallsTheme.string( "add_person_cancelled", fallback: "Cancelled" )
        default: return ""
        }
    }

    private func line( _ text: String ) -> UIView {
        let holder = UIView()
        let label = UILabel()

        label.translatesAutoresizingMaskIntoConstraints = false
        label.font = .systemFont( ofSize: 13 )
        label.textColor = UIColor( white: 1, alpha: 0.65 )
        label.numberOfLines = 0
        label.text = text
        holder.addSubview( label )

        NSLayoutConstraint.activate( [
            label.leadingAnchor.constraint( equalTo: holder.leadingAnchor, constant: 16 ),
            label.trailingAnchor.constraint( equalTo: holder.trailingAnchor, constant: -16 ),
            label.topAnchor.constraint( equalTo: holder.topAnchor, constant: 2 ),
            label.bottomAnchor.constraint( equalTo: holder.bottomAnchor, constant: -14 ),
        ] )

        return holder
    }

    private func separator() -> UIView {
        let line = UIView()

        line.backgroundColor = UIColor( white: 1, alpha: 0.08 )
        line.translatesAutoresizingMaskIntoConstraints = false
        line.heightAnchor.constraint( equalToConstant: 1 / UIScreen.main.scale ).isActive = true

        return line
    }

    private func row( _ person: CallsAddPerson.Person, ring: CallsAddPerson.Ring? ) -> UIView {
        let ringing = ring?.state == "ringing"

        let row = CallsAddPersonRow( person: person, note: ring.map { Self.said( $0.state ) } ?? "" )
        row.isEnabled = adding == nil && !ringing
        row.onPress = { [weak self] in self?.add( person ) }

        if adding == person.id {
            row.spin()
        } else if let ring, ringing, ring.canCancel {
            let cancel = CallsDevicePill( title: CallsTheme.string( "cancel", fallback: "Cancel" ), height: 30 )
            cancel.accessibilityLabel = ( cancel.accessibilityLabel ?? "" ) + " " + person.name
            cancel.isEnabled = !cancelling.contains( ring.id )
            // As wide as its word, which a pill holds to no size of its own: the name has the rest of the row.
            let tight = cancel.widthAnchor.constraint( equalToConstant: 0 )
            tight.priority = UILayoutPriority( 740 )
            tight.isActive = true
            row.onCancel = { [weak self] in self?.cancel( ring.id ) }
            cancel.addTarget( row, action: #selector( CallsAddPersonRow.cancelPressed ), for: .touchUpInside )
            row.end( cancel )
        }

        return row
    }

    private func add( _ person: CallsAddPerson.Person ) {
        guard adding == nil, let host = CallsAddPersonStore.current else { return }

        adding = person.id
        draw()

        host.add( person ) { [weak self] error in
            guard let self else { return }

            self.adding = nil

            if let error { return self.failed( error ) }

            self.draw()
        }
    }

    private func cancel( _ ring: String ) {
        guard let host = CallsAddPersonStore.current else { return }

        cancelling.insert( ring )
        draw()

        host.cancel( ring ) { [weak self] error in
            guard let self else { return }

            self.cancelling.remove( ring )

            if let error { return self.failed( error ) }

            self.draw()
        }
    }
}

/// A person the panel offers: their face, their name, how a ring of theirs stands, and at its end a spinner or Cancel.
private final class CallsAddPersonRow: UIControl {
    var onPress: ( () -> Void )?
    var onCancel: ( () -> Void )?

    private let holder = UIStackView()
    private let text: UIStackView

    init( person: CallsAddPerson.Person, note: String ) {
        let name = UILabel()
        text = UIStackView( arrangedSubviews: [ name ] )

        super.init( frame: .zero )

        translatesAutoresizingMaskIntoConstraints = false
        heightAnchor.constraint( greaterThanOrEqualToConstant: 48 ).isActive = true

        let face = UIView()
        face.translatesAutoresizingMaskIntoConstraints = false
        face.backgroundColor = UIColor( white: 1, alpha: 0.12 )
        face.layer.cornerRadius = 14
        face.clipsToBounds = true
        face.isUserInteractionEnabled = false

        let letters = UILabel()
        letters.translatesAutoresizingMaskIntoConstraints = false
        letters.font = .systemFont( ofSize: 11, weight: .semibold )
        letters.textColor = .white
        letters.text = CallsAvatars.initials( of: person.name )
        face.addSubview( letters )

        let picture = UIImageView()
        picture.translatesAutoresizingMaskIntoConstraints = false
        picture.contentMode = .scaleAspectFill
        face.addSubview( picture )

        name.font = .systemFont( ofSize: 15 )
        name.textColor = .white
        name.lineBreakMode = .byTruncatingTail
        name.text = person.name
        name.setContentCompressionResistancePriority( .defaultLow, for: .horizontal )

        text.axis = .vertical
        text.spacing = 2
        text.isUserInteractionEnabled = false

        if !note.isEmpty {
            let line = UILabel()
            line.font = .systemFont( ofSize: 12 )
            line.textColor = UIColor( white: 1, alpha: 0.6 )
            line.text = note
            text.addArrangedSubview( line )
        }

        holder.translatesAutoresizingMaskIntoConstraints = false
        holder.axis = .horizontal
        holder.alignment = .center
        holder.spacing = 10
        holder.addArrangedSubview( face )
        holder.addArrangedSubview( text )
        addSubview( holder )

        NSLayoutConstraint.activate( [
            face.widthAnchor.constraint( equalToConstant: 28 ),
            face.heightAnchor.constraint( equalToConstant: 28 ),
            letters.centerXAnchor.constraint( equalTo: face.centerXAnchor ),
            letters.centerYAnchor.constraint( equalTo: face.centerYAnchor ),
            picture.leadingAnchor.constraint( equalTo: face.leadingAnchor ),
            picture.trailingAnchor.constraint( equalTo: face.trailingAnchor ),
            picture.topAnchor.constraint( equalTo: face.topAnchor ),
            picture.bottomAnchor.constraint( equalTo: face.bottomAnchor ),
            holder.leadingAnchor.constraint( equalTo: leadingAnchor, constant: 16 ),
            holder.trailingAnchor.constraint( equalTo: trailingAnchor, constant: -16 ),
            holder.topAnchor.constraint( equalTo: topAnchor, constant: 8 ),
            holder.bottomAnchor.constraint( equalTo: bottomAnchor, constant: -8 ),
        ] )

        CallsAvatars.load( person.avatar ) { [weak picture] image in picture?.image = image }

        isAccessibilityElement = true
        accessibilityTraits = .button
        accessibilityLabel = note.isEmpty ? person.name : person.name + ", " + note

        addTarget( self, action: #selector( pressed ), for: .touchUpInside )
        addTarget( self, action: #selector( down ), for: [ .touchDown, .touchDragEnter ] )
        addTarget( self, action: #selector( up ), for: [ .touchUpInside, .touchUpOutside, .touchCancel, .touchDragExit ] )
    }

    required init?( coder: NSCoder ) { fatalError( "init(coder:) has not been implemented" ) }

    override var isEnabled: Bool {
        didSet { accessibilityTraits = isEnabled ? .button : [ .button, .notEnabled ] }
    }

    /// While the ring goes out.
    func spin() {
        let spinner = UIActivityIndicatorView( style: .medium )
        spinner.color = .white
        spinner.startAnimating()
        spinner.isUserInteractionEnabled = false
        holder.addArrangedSubview( spinner )
    }

    /// Cancel at the end of the row: read on its own, beside the words of the row.
    func end( _ view: UIView ) {
        holder.addArrangedSubview( view )
        isAccessibilityElement = false
        text.isAccessibilityElement = true
        text.accessibilityLabel = accessibilityLabel
        accessibilityElements = [ text, view ]
    }

    @objc func cancelPressed() { onCancel?() }
    @objc private func pressed() { onPress?() }
    @objc private func down() { backgroundColor = UIColor( white: 1, alpha: 0.1 ) }
    @objc private func up() { backgroundColor = .clear }
}
"""## ),
    ( "CallsPip.swift", ##"""
import AVKit
import UIKit
import LiveKit
import LiveKitWebRTC

/// The call, still visible once the person has left the app.
///
/// iOS 15's video-call Picture in Picture takes a view controller rather than a
/// sample-buffer layer, so the window is furnished here and drawn by
/// `CallsPipRenderer` — which has to be a second render path, because the
/// Metal view the call screen uses stops the moment the app is off screen.
///
/// It enters by itself when the app is backgrounded during a video call, which
/// is the behaviour people expect from every other calling app, and it is only
/// offered when there is something to look at — PiP over a black square is
/// worse than no PiP. A group call's window shows one person of it
/// (`CallsPipFocus`), by name, and by face while they send no picture.
final class CallsPip: NSObject {
    static let shared = CallsPip()

    /// Whom a group call's window shows.
    struct Who: Equatable {
        let name: String
        let avatar: String
    }

    /// Whom it shows now, nil outside a group call.
    private(set) var who: Who?
    private let nameLabel = UILabel()
    private let face = UIImageView()
    private let faceLetters = UILabel()
    private var faceFor = ""

    /// Whether the device will do this at all. iPhones gained video-call PiP in
    /// iOS 15 but the hardware still decides.
    static var isSupported: Bool { AVPictureInPictureController.isPictureInPictureSupported() }

    private let content = AVPictureInPictureVideoCallViewController()

    /// The call screen the window animates out of, kept so the controller can
    /// be built the moment there is a picture for it.
    private weak var source: UIView?
    private let renderer = CallsPipRenderer()

    private var controller: AVPictureInPictureController?
    private var track: LKRTCVideoTrack?
    private var roomTrack: VideoTrack?

    /// Called when the person taps the PiP window to come back.
    var onRestore: (() -> Void)?

    /// Whether the corner window is up. A backgrounded app is still showing
    /// the call when it is, which is what keeps the size wish honest.
    var isActive: Bool { controller?.isPictureInPictureActive ?? false }

    /// Whether backgrounding the app right now would open the window. Read by
    /// the log, so that a call that opened one over nothing says so.
    var opensAutomatically: Bool { controller != nil }

    /// Whether a window has been asked for and not yet given. A controller
    /// cannot answer that question the instant it is made.
    private var wantsWindow = false
    private var possible: NSKeyValueObservation?

    private override init() {
        super.init()

        let stage = renderer.view

        stage.translatesAutoresizingMaskIntoConstraints = false

        // A call is not a 16:9 film, and it is not a portrait phone either — it
        // is whatever the other camera is pointing at. Until a frame says, the
        // window is the shape of the phone it is on.
        content.preferredContentSize = CGSize(width: 9, height: 16)

        content.view.backgroundColor = .black
        content.view.addSubview(stage)

        NSLayoutConstraint.activate([
            stage.leadingAnchor.constraint(equalTo: content.view.leadingAnchor),
            stage.trailingAnchor.constraint(equalTo: content.view.trailingAnchor),
            stage.topAnchor.constraint(equalTo: content.view.topAnchor),
            stage.bottomAnchor.constraint(equalTo: content.view.bottomAnchor)
        ])

        layOutWho()

        // The window is cut to the picture, so a landscape camera is not shown
        // down a portrait letterbox with a black band either side of it.
        renderer.onDimensions = { [weak self] size in
            guard let self = self else { return }

            CallsLog.write("the corner window is drawing \(Int(size.width))x\(Int(size.height))")

            self.content.preferredContentSize = size
        }

        for name in [ UIApplication.willResignActiveNotification, UIApplication.didBecomeActiveNotification ] {
            NotificationCenter.default.addObserver(
                self,
                selector: #selector(appVisibilityChanged(_:)),
                name: name,
                object: nil
            )
        }
    }

    /// Frames are only worth wrapping while the window is the thing showing
    /// them. The system opens it on `willResignActive`, which is why that is
    /// the notification watched rather than the backgrounding one.
    @objc private func appVisibilityChanged(_ note: Notification) {
        renderer.wanted = note.name == UIApplication.willResignActiveNotification && controller != nil

        if note.name == UIApplication.didBecomeActiveNotification {
            wantsWindow = false
            possible?.invalidate()
            possible = nil
        }
    }

    /// Attach to the call screen. The source view is what the window animates
    /// out of and back into, so it has to be the screen the person is looking
    /// at rather than the PiP content itself.
    func attach(to source: UIView) {
        guard Self.isSupported else { return }

        if self.source !== source { release() }

        self.source = source

        refreshController()
    }

    /// Whether there is a picture to put in the window: someone's face is one.
    private var hasPicture: Bool { track != nil || roomTrack != nil || who != nil }

    /// Whether a window can be had now.
    var hasContent: Bool { hasPicture }

    /// The name and the face over the picture, for a group call's window.
    private func layOutWho() {
        nameLabel.font = .systemFont(ofSize: 12, weight: .semibold)
        nameLabel.textColor = .white
        nameLabel.shadowColor = UIColor(white: 0, alpha: 0.7)
        nameLabel.shadowOffset = CGSize(width: 0, height: 1)
        nameLabel.isHidden = true
        nameLabel.translatesAutoresizingMaskIntoConstraints = false

        face.contentMode = .scaleAspectFill
        face.clipsToBounds = true
        face.layer.cornerRadius = 28
        face.backgroundColor = UIColor(white: 1, alpha: 0.14)
        face.isHidden = true
        face.translatesAutoresizingMaskIntoConstraints = false

        faceLetters.font = .systemFont(ofSize: 20, weight: .semibold)
        faceLetters.textColor = .white
        faceLetters.textAlignment = .center
        faceLetters.translatesAutoresizingMaskIntoConstraints = false

        face.addSubview(faceLetters)
        content.view.addSubview(face)
        content.view.addSubview(nameLabel)

        NSLayoutConstraint.activate([
            face.widthAnchor.constraint(equalToConstant: 56),
            face.heightAnchor.constraint(equalToConstant: 56),
            face.centerXAnchor.constraint(equalTo: content.view.centerXAnchor),
            face.centerYAnchor.constraint(equalTo: content.view.centerYAnchor),
            faceLetters.centerXAnchor.constraint(equalTo: face.centerXAnchor),
            faceLetters.centerYAnchor.constraint(equalTo: face.centerYAnchor),
            nameLabel.leadingAnchor.constraint(equalTo: content.view.leadingAnchor, constant: 8),
            nameLabel.trailingAnchor.constraint(lessThanOrEqualTo: content.view.trailingAnchor, constant: -8),
            nameLabel.bottomAnchor.constraint(equalTo: content.view.bottomAnchor, constant: -6)
        ])
    }

    private func drawWho() {
        let bare = who != nil && roomTrack == nil

        renderer.view.isHidden = bare
        face.isHidden = !bare
        nameLabel.isHidden = who == nil
        nameLabel.text = who?.name

        guard let who, faceFor != who.avatar + "\n" + who.name else { return }

        faceFor = who.avatar + "\n" + who.name
        face.image = nil
        faceLetters.text = CallsAvatars.initials(of: who.name)
        faceLetters.isHidden = false

        let wanted = faceFor

        CallsAvatars.load(who.avatar) { [weak self] image in
            DispatchQueue.main.async {
                guard let self, self.faceFor == wanted, let image else { return }

                self.face.image = image
                self.faceLetters.isHidden = true
            }
        }
    }

    /// The controller exists only while there is something to put in the
    /// window, because its existence is what the automatic entry actually
    /// turns on.
    ///
    /// `canStartPictureInPictureAutomaticallyFromInline` is the switch for a
    /// player's inline PiP; a video-call source ignores it. A phone with that
    /// flag false still opened the window on an audio call — the log has it
    /// opening 291 ms *before* the background notification, and the delegate
    /// closing it again afterwards. Backgrounding a call the system can put in
    /// a corner is enough, and what it puts there is whatever the content view
    /// controller is drawing, black square included. So an audio call, and a
    /// video call with the other camera off, keep no controller at all and the
    /// system's own call indicator is left where it is.
    private func refreshController() {
        guard Self.isSupported else { return }

        guard hasPicture else {
            release()
            return
        }

        guard controller == nil, let source = source else { return }

        let controller = AVPictureInPictureController(
            contentSource: .init(activeVideoCallSourceView: source, contentViewController: content)
        )

        controller.delegate = self

        // Backgrounding a video call is the ordinary way into PiP; requiring a
        // button press for it would make the feature invisible.
        controller.canStartPictureInPictureAutomaticallyFromInline = true

        self.controller = controller

        // A call that was audio when the app went away, and became a video
        // call while it was gone, has no transition left to ride: the system
        // opens the window on `willResignActive` and that already happened.
        // So ask for it, and let the delegate say whether the system agreed —
        // starting from the background is not documented to work, and the log
        // is how we find out rather than guess.
        // A call that was audio when the app went away, and became a video call
        // while it was gone, has no transition left to ride: the system opens
        // the window on `willResignActive`, and that already happened.
        //
        // **Measured on an iPhone 15 Pro, iOS 26.6.1, 10 Sep.** Asking anyway
        // does nothing when the app is properly in the background:
        // `isPictureInPicturePossible` was *true*, `startPictureInPicture()`
        // was called, and neither `didStart` nor
        // `failedToStartPictureInPicture` ever fired — the system simply
        // ignores it. Apple documents no rule either way, which is why this
        // was tested rather than assumed. Foregrounding the app and leaving it
        // again opens the window normally, because by then the controller
        // exists for the transition to use.
        //
        // The ask is kept for the state in between: `.inactive` is the moment
        // of leaving, and a picture arriving *then* can still take the window.
        guard UIApplication.shared.applicationState != .active else { return }

        renderer.wanted = true
        wantsWindow = true

        CallsLog.write("a picture arrived while the app was away, asking for the corner window (possible=\(controller.isPictureInPicturePossible))")

        askForWindow(controller)
    }

    /// Open the window if the controller will have it, and otherwise wait
    /// until it will — a controller can answer `isPictureInPicturePossible`
    /// false until it has had a layout pass.
    private func askForWindow(_ controller: AVPictureInPictureController) {
        possible?.invalidate()
        possible = nil

        guard wantsWindow, !controller.isPictureInPictureActive else { return }

        if controller.isPictureInPicturePossible {
            controller.startPictureInPicture()
            return
        }

        possible = controller.observe(\.isPictureInPicturePossible, options: [.new]) { [weak self] controller, change in
            guard change.newValue == true, self?.wantsWindow == true else { return }

            CallsLog.write("the corner window became possible, opening it")

            self?.possible?.invalidate()
            self?.possible = nil

            controller.startPictureInPicture()
        }
    }

    private func release() {
        renderer.wanted = false
        wantsWindow = false

        possible?.invalidate()
        possible = nil

        guard let controller = controller else { return }

        if controller.isPictureInPictureActive { controller.stopPictureInPicture() }

        controller.delegate = nil

        self.controller = nil
    }

    /// The peer's camera, in a direct call.
    func show(_ track: LKRTCVideoTrack?) {
        guard track !== self.track else { return }

        if let previous = self.track { previous.remove(renderer) }

        self.track = track
        track?.add(renderer)

        if track != nil { detachRoomTrack() }

        refreshController()
    }

    /// The room's video, when the call runs through one, and `who` it is of in a group call.
    func showRoom(_ track: VideoTrack?, who: Who? = nil) {
        guard track !== roomTrack || who != self.who else { return }

        self.who = who

        if track !== roomTrack {
            detachRoomTrack()

            roomTrack = track
            track?.add(videoRenderer: renderer)

            if track != nil, let previous = self.track {
                previous.remove(renderer)
                self.track = nil
            }
        }

        drawWho()
        refreshController()
    }

    private func detachRoomTrack() {
        guard let previous = roomTrack else { return }

        previous.remove(videoRenderer: renderer)

        roomTrack = nil
    }

    func start() {
        guard let controller = controller, controller.isPictureInPictureActive == false else { return }

        // Nothing to show is not worth a window.
        guard hasPicture else { return }

        controller.startPictureInPicture()
    }

    func stop() {
        controller?.stopPictureInPicture()
    }

    /// The call ended: drop the track and the controller so a later call
    /// attaches to its own screen rather than a dead one.
    func detach() {
        if let previous = track { previous.remove(renderer) }

        track = nil

        detachRoomTrack()

        who = nil
        drawWho()

        source = nil

        release()
    }
}

/// Whom a group call's window shows, as the web's pipFocus: someone in the spotlight or pinned (`first`), else a screen
/// someone else shares, else whoever speaks loudest, else who spoke last while they are still there, else the first with
/// a picture, the first other, the user. Their face stands in where they send no picture.
enum CallsPipFocus {
    struct Person: Equatable {
        let identity: String
        let isLocal: Bool
        let screen: Bool
        let camera: Bool
        let speaking: Bool
        let level: Float

        init(identity: String, isLocal: Bool = false, screen: Bool = false, camera: Bool = false, speaking: Bool = false, level: Float = 0) {
            self.identity = identity
            self.isLocal = isLocal
            self.screen = screen
            self.camera = camera
            self.speaking = speaking
            self.level = level
        }

        init(_ person: CallsRoomParticipant) {
            self.init(
                identity: person.identity, isLocal: person.isLocal, screen: person.screen != nil,
                camera: person.video != nil, speaking: person.speaking, level: person.audioLevel
            )
        }
    }

    /// A video call has a window all through, an audio call only while someone else shares a screen, which is all it
    /// would show. A call of nobody has none.
    static func offered(_ people: [Person], video: Bool) -> Bool {
        !people.isEmpty && (video || people.contains { !$0.isLocal && $0.screen })
    }

    static func pick(_ people: [Person], first: [String], last: String?) -> String? {
        func loudest(_ among: [Person]) -> Person? {
            among.filter(\.speaking).max { $0.level < $1.level }
        }

        let others = people.filter { !$0.isLocal }
        var seen = Set<String>()
        let ahead = first.compactMap { key in seen.insert(key).inserted ? people.first { $0.identity == key } : nil }

        if !ahead.isEmpty {
            return (loudest(ahead) ?? ahead.first { $0.identity == last } ?? ahead[0]).identity
        }

        return (others.first(where: \.screen)
            ?? loudest(others)
            ?? others.first { $0.identity == last }
            ?? others.first { $0.camera }
            ?? others.first
            ?? people.first)?.identity
    }
}

extension CallsPip: AVPictureInPictureControllerDelegate {
    /// The picture can stop between the app being backgrounded and the window
    /// opening — the other side turning their camera off is one moment of it —
    /// and by then the flag has been read. An empty window is closed again
    /// rather than left sitting over the call indicator.
    func pictureInPictureControllerDidStartPictureInPicture(_ controller: AVPictureInPictureController) {
        CallsLog.write("the corner window opened")

        // Whatever the app state says, the window is up: it is being drawn for
        // now, and until it stops.
        renderer.wanted = true
        wantsWindow = false

        guard !hasPicture else { return }

        CallsLog.write("the corner window opened with nothing in it, closing it")

        // Not from inside the start it is answering: the transition has to
        // finish before the stop is heard.
        DispatchQueue.main.async { controller.stopPictureInPicture() }
    }

    func pictureInPictureControllerDidStopPictureInPicture(_ controller: AVPictureInPictureController) {
        renderer.wanted = false
        wantsWindow = false
    }

    func pictureInPictureController(
        _ controller: AVPictureInPictureController,
        failedToStartPictureInPictureWithError error: Error
    ) {
        CallsLog.write("the corner window would not open: \(error.localizedDescription)")

        renderer.wanted = UIApplication.shared.applicationState != .active && self.controller != nil
    }

    func pictureInPictureController(
        _ controller: AVPictureInPictureController,
        restoreUserInterfaceForPictureInPictureStopWithCompletionHandler completion: @escaping (Bool) -> Void
    ) {
        onRestore?()
        completion(true)
    }
}
