import UIKit

// A person's face with their status dot, and the typing and activity line: realtime-ui's presence parts
// (components/presence/avatar-face.tsx and presence.tsx) under their names. Views only: whoever draws them says who is
// online and passes the people, so an app feeds them from a presence room, from its own list, or from anything else. None
// of them reads a room or a connection. Their words are `CallScreen.Appearance.strings` and their colours its tokens.

/// A person's status, as the dot and the label say it.
public enum Presence: String, Sendable, CaseIterable {
    case online, busy, away, offline

    /// What a screen reader says of it: `Online` … in the app's words (`presence_online` …), English otherwise.
    var said: String {
        switch self {
        case .online: return CallsTheme.string( "presence_online", fallback: "Online" )
        case .busy: return CallsTheme.string( "presence_busy", fallback: "Do not disturb" )
        case .away: return CallsTheme.string( "presence_away", fallback: "Away" )
        case .offline: return CallsTheme.string( "presence_offline", fallback: "Offline" )
        }
    }
}

/// The colours of these parts, by the tokens of the web, each following the phone's light or dark where no token says.
enum PresenceColors {
    static func of( _ presence: Presence ) -> UIColor {
        switch presence {
        case .online: return CallsTheme.color( "online", fallback: UIColor( red: 61 / 255, green: 165 / 255, blue: 18 / 255, alpha: 1 ) )
        case .busy: return CallsTheme.color( "busy", fallback: UIColor( red: 220 / 255, green: 53 / 255, blue: 69 / 255, alpha: 1 ) )
        case .away: return CallsTheme.color( "away", fallback: UIColor( red: 245 / 255, green: 158 / 255, blue: 11 / 255, alpha: 1 ) )
        case .offline: return CallsTheme.color( "offline", fallback: UIColor( red: 156 / 255, green: 163 / 255, blue: 175 / 255, alpha: 1 ) )
        }
    }

    static var surface: UIColor { CallsTheme.color( "surface", fallback: .systemBackground ) }
    static var textPrimary: UIColor { CallsTheme.color( "text-primary", fallback: .label ) }
    static var textTertiary: UIColor { CallsTheme.color( "text-tertiary", fallback: .secondaryLabel ) }
    static var border: UIColor { CallsTheme.color( "border", fallback: .separator ) }
    static var hover: UIColor { CallsTheme.color( "bg-hover", fallback: .secondarySystemFill ) }
    static var activity: UIColor { CallsTheme.color( "accent-hover", fallback: CallsTheme.accent ) }
}

/// The status dot, in the colour of its status with a ring of what is behind it: `presence` nil draws it as offline.
public final class PresenceDot: UIView {
    public var presence: Presence? { didSet { draw() } }
    /// The ring round it: the surface by default. Clear for none.
    public var ringColor: UIColor? { didSet { draw() } }
    /// A status of the app's own in its colour, while the person is not offline.
    public var color: UIColor? { didSet { draw() } }

    private let size: CGFloat

    public init( presence: Presence?, size: CGFloat = 10, ringColor: UIColor? = nil, color: UIColor? = nil ) {
        self.presence = presence
        self.size = size
        self.ringColor = ringColor
        self.color = color
        super.init( frame: .zero )
        translatesAutoresizingMaskIntoConstraints = false
        isAccessibilityElement = true
        NSLayoutConstraint.activate( [ widthAnchor.constraint( equalToConstant: size ), heightAnchor.constraint( equalToConstant: size ) ] )
        draw()
    }

    @available( *, unavailable )
    required init?( coder: NSCoder ) { fatalError( "init(coder:) is not supported" ) }

    private func draw() {
        let shown = presence ?? .offline
        backgroundColor = shown != .offline ? color ?? PresenceColors.of( shown ) : PresenceColors.of( shown )
        layer.cornerRadius = size / 2
        // Two points outside the dot, as the web's box shadow, so its size is the dot's own.
        layer.shadowColor = ( ringColor ?? PresenceColors.surface ).cgColor
        layer.shadowOpacity = 1
        layer.shadowRadius = 0
        layer.shadowOffset = .zero
        layer.shadowPath = UIBezierPath( ovalIn: CGRect( x: -2, y: -2, width: size + 4, height: size + 4 ) ).cgPath
        accessibilityLabel = shown.said
    }

    public override func traitCollectionDidChange( _ previous: UITraitCollection? ) {
        super.traitCollectionDidChange( previous )
        draw()
    }
}

/// The shape of a face: a circle by default, as the call screen draws them.
public enum AvatarShape: String, Sendable, CaseIterable {
    case circle, rounded, square

    func radius( size: CGFloat ) -> CGFloat {
        switch self {
        case .circle: return size / 2
        case .rounded: return min( 8, size / 2 )
        case .square: return min( 2, size / 2 )
        }
    }
}

/// A person's letters and the colours they are drawn in, where the app gives them: the first letters of their name on the
/// blank of the face otherwise.
public struct AvatarLetters: Sendable {
    public let text: String
    public let background: UIColor
    public let color: UIColor

    public init( text: String, background: UIColor, color: UIColor ) {
        self.text = text
        self.background = background
        self.color = color
    }
}

/// A person's face: their picture, or their letters, with their status dot at its corner. A picture that does not load
/// leaves the letters. A photo and an SVG both draw, as on the call screen.
public final class Avatar: UIView {
    public var name: String? { didSet { draw() } }
    /// The picture's address.
    public var picture: String? { didSet { load() } }
    public var presence: Presence? { didSet { drawDot() } }
    /// The dot for an offline person too, where no dot would say nothing.
    public var showOffline: Bool { didSet { drawDot() } }
    public var shape: AvatarShape { didSet { draw() } }
    /// The status of the app's own in its colour.
    public var presenceColor: UIColor? { didSet { dot?.color = presenceColor } }
    /// The ring round the dot: the surface by default.
    public var presenceRing: UIColor? { didSet { dot?.ringColor = presenceRing } }
    public var letters: AvatarLetters? { didSet { draw() } }
    /// The name is beside the face already: nothing for a screen reader to read twice.
    public var decorative: Bool { didSet { drawLabel() } }

    private let size: CGFloat
    private let dotSize: CGFloat
    private let face = UIView()
    private let lettersLabel = UILabel()
    private let image = UIImageView()
    private var dot: PresenceDot?

    public init(
        name: String? = nil, picture: String? = nil, size: CGFloat = 36, shape: AvatarShape = .circle, presence: Presence? = nil,
        showOffline: Bool = false, dotSize: CGFloat? = nil, presenceColor: UIColor? = nil, presenceRing: UIColor? = nil,
        letters: AvatarLetters? = nil, decorative: Bool = false
    ) {
        self.name = name
        self.picture = picture
        self.size = size
        self.shape = shape
        self.presence = presence
        self.showOffline = showOffline
        self.dotSize = dotSize ?? max( 6, ( size * 0.28 ).rounded() )
        self.presenceColor = presenceColor
        self.presenceRing = presenceRing
        self.letters = letters
        self.decorative = decorative
        super.init( frame: .zero )

        translatesAutoresizingMaskIntoConstraints = false
        face.translatesAutoresizingMaskIntoConstraints = false
        face.clipsToBounds = true
        addSubview( face )

        lettersLabel.translatesAutoresizingMaskIntoConstraints = false
        lettersLabel.textAlignment = .center
        lettersLabel.adjustsFontSizeToFitWidth = true
        lettersLabel.minimumScaleFactor = 0.5
        lettersLabel.font = .systemFont( ofSize: size * 0.38, weight: .semibold )
        face.addSubview( lettersLabel )

        image.translatesAutoresizingMaskIntoConstraints = false
        image.contentMode = .scaleAspectFill
        image.isHidden = true
        face.addSubview( image )

        NSLayoutConstraint.activate( [
            widthAnchor.constraint( equalToConstant: size ),
            heightAnchor.constraint( equalToConstant: size ),
            face.leadingAnchor.constraint( equalTo: leadingAnchor ),
            face.trailingAnchor.constraint( equalTo: trailingAnchor ),
            face.topAnchor.constraint( equalTo: topAnchor ),
            face.bottomAnchor.constraint( equalTo: bottomAnchor ),
            lettersLabel.centerXAnchor.constraint( equalTo: face.centerXAnchor ),
            lettersLabel.centerYAnchor.constraint( equalTo: face.centerYAnchor ),
            lettersLabel.widthAnchor.constraint( lessThanOrEqualTo: face.widthAnchor, multiplier: 0.86 ),
            image.leadingAnchor.constraint( equalTo: face.leadingAnchor ),
            image.trailingAnchor.constraint( equalTo: face.trailingAnchor ),
            image.topAnchor.constraint( equalTo: face.topAnchor ),
            image.bottomAnchor.constraint( equalTo: face.bottomAnchor ),
        ] )

        draw()
        load()
        drawDot()
    }

    @available( *, unavailable )
    required init?( coder: NSCoder ) { fatalError( "init(coder:) is not supported" ) }

    /// The words the face draws with no picture.
    var lettersShown: String { letters?.text ?? CallsAvatars.initials( of: name ?? "" ) }

    private func draw() {
        face.layer.cornerRadius = shape.radius( size: size )
        face.backgroundColor = letters?.background ?? PresenceColors.hover
        lettersLabel.textColor = letters?.color ?? PresenceColors.textTertiary
        lettersLabel.text = lettersShown
        drawLabel()
    }

    private func drawLabel() {
        isAccessibilityElement = !decorative
        // The name, and the status where a dot says one.
        accessibilityLabel = decorative ? nil : [ name, drawnDot?.said ].compactMap { $0 }.joined( separator: ", " )
        accessibilityElementsHidden = decorative
    }

    /// The status the dot says, while it shows.
    private var drawnDot: Presence? {
        guard let presence, presence != .offline || showOffline else { return nil }
        return presence
    }

    private func drawDot() {
        defer { drawLabel() }

        guard let shown = drawnDot else {
            dot?.removeFromSuperview()
            dot = nil
            return
        }

        if let dot {
            dot.presence = shown
            return
        }

        let added = PresenceDot( presence: shown, size: dotSize, ringColor: presenceRing, color: presenceColor )
        added.isAccessibilityElement = false
        addSubview( added )
        // At the corner the line ends on, a fifth of the dot out of the face.
        NSLayoutConstraint.activate( [
            added.trailingAnchor.constraint( equalTo: trailingAnchor, constant: dotSize * 0.2 ),
            added.bottomAnchor.constraint( equalTo: bottomAnchor, constant: dotSize * 0.2 ),
        ] )
        dot = added
    }

    private func load() {
        let wanted = picture ?? ""
        image.image = nil
        image.isHidden = true

        guard !wanted.isEmpty else { return }

        CallsAvatars.load( wanted ) { [weak self] picture in
            // Another picture was asked for since.
            guard let self, self.picture == wanted, let picture else { return }
            self.image.image = picture
            self.image.isHidden = false
        }
    }

    /// The dot, for a test.
    var dotShown: PresenceDot? { dot }

    public override func traitCollectionDidChange( _ previous: UITraitCollection? ) {
        super.traitCollectionDidChange( previous )
        draw()
    }
}

/// Three dots that bounce in turn, still where the phone is asked to reduce motion.
public final class TypingDots: UIView {
    private let dots: [ UIView ]

    public init( small: Bool = false ) {
        let side: CGFloat = small ? 4 : 5
        dots = ( 0..<3 ).map { _ in
            let dot = UIView()
            dot.translatesAutoresizingMaskIntoConstraints = false
            dot.layer.cornerRadius = side / 2
            dot.alpha = 0.7
            dot.widthAnchor.constraint( equalToConstant: side ).isActive = true
            dot.heightAnchor.constraint( equalToConstant: side ).isActive = true
            return dot
        }
        super.init( frame: .zero )

        translatesAutoresizingMaskIntoConstraints = false
        isUserInteractionEnabled = false
        isAccessibilityElement = false

        let row = UIStackView( arrangedSubviews: dots )
        row.translatesAutoresizingMaskIntoConstraints = false
        row.axis = .horizontal
        row.alignment = .center
        row.spacing = small ? 2 : 3
        addSubview( row )

        NSLayoutConstraint.activate( [
            row.leadingAnchor.constraint( equalTo: leadingAnchor ),
            row.trailingAnchor.constraint( equalTo: trailingAnchor ),
            row.centerYAnchor.constraint( equalTo: centerYAnchor ),
            heightAnchor.constraint( greaterThanOrEqualToConstant: side + 3 ),
        ] )
        draw()
    }

    @available( *, unavailable )
    required init?( coder: NSCoder ) { fatalError( "init(coder:) is not supported" ) }

    /// The colour of the dots: the line's.
    public override var tintColor: UIColor! { didSet { draw() } }

    private func draw() {
        dots.forEach { $0.backgroundColor = tintColor }
    }

    public override func tintColorDidChange() {
        super.tintColorDidChange()
        draw()
    }

    /// Whether they are moving, for a test.
    var moving: Bool { dots.first?.layer.animation( forKey: "typing" ) != nil }

    public override func didMoveToWindow() {
        super.didMoveToWindow()
        window == nil ? stop() : start()
    }

    private func stop() {
        dots.forEach { $0.layer.removeAnimation( forKey: "typing" ) }
    }

    private func start() {
        stop()
        guard !UIAccessibility.isReduceMotionEnabled else { return }

        // The web's: 1.2 seconds, a point and a half either side of the line, dimmer below it, each 0.15 after the last.
        for ( index, dot ) in dots.enumerated() {
            let move = CAKeyframeAnimation( keyPath: "transform.translation.y" )
            move.values = [ 1.5, -1.5, 1.5 ]
            let fade = CAKeyframeAnimation( keyPath: "opacity" )
            fade.values = [ 0.35, 1, 0.35 ]
            let both = CAAnimationGroup()
            both.animations = [ move, fade ]
            both.duration = 1.2
            both.repeatCount = .infinity
            both.timingFunction = CAMediaTimingFunction( name: .easeInEaseOut )
            both.beginTime = CACurrentMediaTime() + Double( index ) * 0.15
            both.isRemovedOnCompletion = false
            dot.layer.add( both, forKey: "typing" )
        }
    }
}

/// What someone is doing right now, as the line says it.
public enum Activity: String, Sendable, CaseIterable {
    case typing, recording, uploading
}

/// Someone in the line: their name, or none for the activity alone.
public struct ActivityEntry: Sendable, Equatable {
    public let name: String?
    public let activity: Activity

    public init( name: String? = nil, activity: Activity = .typing ) {
        self.name = name
        self.activity = activity
    }
}

/// The line that says who is typing, recording or sending a file: every activity gets its own part ("Anna, Bob typing,
/// Carol recording"), up to two names are spelled out and more become a count, and the icon is the one activity's, or the
/// typing dots once they mix. Hide it while nobody is: with nobody given it says "typing" alone, as the web's does.
public final class ActivityIndicator: UIView {
    /// Who, each with what they do. Empty, the line is `names` doing `activity`.
    public var entries: [ ActivityEntry ] { didSet { draw() } }
    public var activity: Activity { didSet { draw() } }
    public var names: [ String ] { didSet { draw() } }
    /// The smaller line.
    public var compact: Bool { didSet { draw() } }

    private let row = UIStackView()
    private let holder = UIView()
    private let label = UILabel()

    public init( entries: [ ActivityEntry ] = [], activity: Activity = .typing, names: [ String ] = [], compact: Bool = false ) {
        self.entries = entries
        self.activity = activity
        self.names = names
        self.compact = compact
        super.init( frame: .zero )

        translatesAutoresizingMaskIntoConstraints = false
        isAccessibilityElement = true
        accessibilityTraits = [ .staticText, .updatesFrequently ]

        row.translatesAutoresizingMaskIntoConstraints = false
        row.axis = .horizontal
        row.alignment = .center
        row.spacing = 6
        addSubview( row )

        holder.translatesAutoresizingMaskIntoConstraints = false
        holder.setContentHuggingPriority( .required, for: .horizontal )
        row.addArrangedSubview( holder )

        label.numberOfLines = 1
        label.setContentCompressionResistancePriority( .defaultLow, for: .horizontal )
        row.addArrangedSubview( label )

        NSLayoutConstraint.activate( [
            row.leadingAnchor.constraint( equalTo: leadingAnchor ),
            row.trailingAnchor.constraint( equalTo: trailingAnchor ),
            row.topAnchor.constraint( equalTo: topAnchor ),
            row.bottomAnchor.constraint( equalTo: bottomAnchor ),
        ] )
        draw()
    }

    @available( *, unavailable )
    required init?( coder: NSCoder ) { fatalError( "init(coder:) is not supported" ) }

    /// What the line says, as realtime-ui's ActivityIndicator groups it. `%s` in the app's words (`typing_named`,
    /// `recording_named`, `uploading_named`) is who, the words alone (`typing`, `recording`, `uploading`) for one person
    /// with no name.
    static func said( _ list: [ ActivityEntry ] ) -> String {
        groups( list ).map { group -> String in
            let who = !group.named.isEmpty && group.named.count <= 2 ? group.named.joined( separator: ", " ) : String( group.count )
            let named = !group.named.isEmpty || group.count > 1
            switch group.activity {
            case .recording:
                return named
                    ? CallsTheme.string( "recording_named", fallback: "%s recording" ).replacingOccurrences( of: "%s", with: who )
                    : CallsTheme.string( "recording", fallback: "recording" )
            case .uploading:
                return named
                    ? CallsTheme.string( "uploading_named", fallback: "%s sending file" ).replacingOccurrences( of: "%s", with: who )
                    : CallsTheme.string( "uploading", fallback: "sending file" )
            case .typing:
                return named
                    ? CallsTheme.string( "typing_named", fallback: "%s typing" ).replacingOccurrences( of: "%s", with: who )
                    : CallsTheme.string( "typing", fallback: "typing" )
            }
        }.joined( separator: ", " )
    }

    /// The icon of the line: the one activity's, the typing dots once they mix.
    static func iconActivity( _ list: [ ActivityEntry ] ) -> Activity {
        let found = groups( list )
        return found.count == 1 ? found[ 0 ].activity : .typing
    }

    private static func groups( _ list: [ ActivityEntry ] ) -> [ ( activity: Activity, count: Int, named: [ String ] ) ] {
        Activity.allCases.compactMap { activity in
            let members = list.filter { $0.activity == activity }
            guard !members.isEmpty else { return nil }
            let named = members.map { ( $0.name ?? "" ).trimmingCharacters( in: .whitespacesAndNewlines ) }.filter { !$0.isEmpty }
            return ( activity, members.count, named )
        }
    }

    private var list: [ ActivityEntry ] {
        if !entries.isEmpty { return entries }
        if !names.isEmpty { return names.map { ActivityEntry( name: $0, activity: activity ) } }
        return [ ActivityEntry( activity: activity ) ]
    }

    /// The icon's view, for a test.
    var iconView: UIView? { holder.subviews.first }

    private var drawnIcon: Activity?
    private var drawnCompact: Bool?

    private func draw() {
        let list = self.list
        let said = Self.said( list )
        let colour = PresenceColors.activity
        label.text = said
        label.textColor = colour
        label.font = .systemFont( ofSize: compact ? 12 : 14, weight: .medium )
        accessibilityLabel = said

        let icon = Self.iconActivity( list )
        tintColor = colour

        guard icon != drawnIcon || compact != drawnCompact else {
            holder.subviews.first?.tintColor = colour
            return
        }
        drawnIcon = icon
        drawnCompact = compact

        holder.subviews.forEach { $0.removeFromSuperview() }

        let drawn = iconOf( icon )
        holder.addSubview( drawn )
        NSLayoutConstraint.activate( [
            drawn.leadingAnchor.constraint( equalTo: holder.leadingAnchor ),
            drawn.trailingAnchor.constraint( equalTo: holder.trailingAnchor ),
            drawn.topAnchor.constraint( greaterThanOrEqualTo: holder.topAnchor ),
            drawn.bottomAnchor.constraint( lessThanOrEqualTo: holder.bottomAnchor ),
            drawn.centerYAnchor.constraint( equalTo: holder.centerYAnchor ),
        ] )
    }

    private func iconOf( _ activity: Activity ) -> UIView {
        switch activity {
        case .typing:
            let dots = TypingDots( small: compact )
            dots.tintColor = PresenceColors.activity
            return dots
        case .recording:
            let dot = UIView()
            dot.translatesAutoresizingMaskIntoConstraints = false
            dot.backgroundColor = CallsTheme.recording
            dot.layer.cornerRadius = 3.5
            let mic = glyph( CallsIcons.mic, colour: CallsTheme.recording )
            let both = UIStackView( arrangedSubviews: [ dot, mic ] )
            both.translatesAutoresizingMaskIntoConstraints = false
            both.axis = .horizontal
            both.alignment = .center
            both.spacing = 4
            NSLayoutConstraint.activate( [ dot.widthAnchor.constraint( equalToConstant: 7 ), dot.heightAnchor.constraint( equalToConstant: 7 ) ] )
            return both
        case .uploading:
            return glyph( Self.paperclip, colour: PresenceColors.activity )
        }
    }

    private func glyph( _ data: String, colour: UIColor ) -> UIView {
        let icon = CallsIconView( data )
        icon.color = colour
        NSLayoutConstraint.activate( [ icon.widthAnchor.constraint( equalToConstant: 12 ), icon.heightAnchor.constraint( equalToConstant: 12 ) ] )
        return icon
    }

    /// The web's paperclip (realtime-ui's primitives/icons/chat.ts).
    private static let paperclip = "m21.44 11.05-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48"
}
"""## ),
    ( "Tests/AddPersonTests.swift", ##"""
import UIKit
import XCTest
import WordPlusRealtimeCalls
@testable import WordPlusRealtimeUI

/// Add Person (realtime-ui's add-person.tsx) on the real screen, with a stand-in for the host: the button only where the
/// host gives whom to add and only once the call is up, the list as it loads, a press that rings, how each ring stands,
/// Cancel, and a failure said by the screen. Run on a simulator, as PiecesTests.
@MainActor
final class AddPersonTests: XCTestCase {
    private var asked: [ ( [ CallsAddPerson.Person ] ) -> Void ] = []
    private var added: [ ( person: CallsAddPerson.Person, done: ( String? ) -> Void ) ] = []
    private var cancelled: [ ( ring: String, done: ( String? ) -> Void ) ] = []
    private var rings: [ CallsAddPerson.Ring ] = []

    private let ann = CallsAddPerson.Person( id: "43", name: "Ann", avatar: "" )
    private let ben = CallsAddPerson.Person( id: "44", name: "Ben", avatar: "" )

    override func setUp() {
        super.setUp()
        _ = CallScreen.shared
        asked = []
        added = []
        cancelled = []
        rings = []
        CallsAddPersonStore.current = CallsAddPerson(
            people: { [unowned self] done in self.asked.append( done ) },
            add: { [unowned self] person, done in self.added.append( ( person, done ) ) },
            rings: { [unowned self] in self.rings },
            cancel: { [unowned self] ring, done in self.cancelled.append( ( ring, done ) ) }
        )
    }

    override func tearDown() {
        CallsAddPersonStore.current = nil
        super.tearDown()
    }

    private func screen( phase: String = "in_progress", group: Bool = false ) -> CallsScreen {
        let screen = CallsScreen()
        screen.loadViewIfNeeded()
        screen.view.frame = CGRect( x: 0, y: 0, width: 390, height: 844 )
        screen.apply( state: state( phase: phase, group: group ) )
        screen.view.layoutIfNeeded()
        return screen
    }

    private func state( phase: String, group: Bool = false ) -> [ String: Any ] {
        [ "phase": phase, "type": "video", "group": group, "local": [ "muted": false, "camera": false ] ]
    }

    private func button( _ view: UIView ) -> CallsButton? {
        if view.accessibilityLabel == "Add Person", let found = view as? CallsButton { return found }
        return view.subviews.lazy.compactMap( button ).first
    }

    private func panel( _ view: UIView ) -> CallsAddPersonPanel? {
        if let found = view as? CallsAddPersonPanel { return found }
        return view.subviews.lazy.compactMap( panel ).first
    }

    private func texts( _ view: UIView ) -> [ String ] {
        guard !view.isHidden else { return [] }

        return [ ( view as? UILabel )?.text ].compactMap { $0 } + view.subviews.flatMap( texts )
    }

    private func row( _ name: String, in view: UIView ) -> UIControl? {
        if let found = view as? UIControl, !( view is CallsDevicePill ), texts( found ).contains( name ) { return found }
        return view.subviews.lazy.compactMap { self.row( name, in: $0 ) }.first
    }

    private func pill( _ view: UIView ) -> CallsDevicePill? {
        if let found = view as? CallsDevicePill { return found }
        return view.subviews.lazy.compactMap( pill ).first
    }

    private func press( _ control: UIControl ) {
        for target in control.allTargets {
            for action in control.actions( forTarget: target, forControlEvent: .touchUpInside ) ?? [] {
                _ = ( target as NSObject ).perform( Selector( action ) )
            }
        }
    }

    private func opened( _ people: [ CallsAddPerson.Person ]? = nil ) -> CallsScreen {
        let screen = screen()
        screen.showAddPerson()
        if let people { asked.removeLast()( people ) }
        screen.view.layoutIfNeeded()
        return screen
    }

    func testALongListScrollsUnderItsTitleAboveTheDock() {
        let everyone = ( 0..<100 ).map { CallsAddPerson.Person( id: String( $0 ), name: "Person \( $0 )", avatar: "" ) }
        let screen = opened( everyone )
        screen.view.layoutIfNeeded()

        func find( _ view: UIView ) -> UILabel? {
            if let label = view as? UILabel, label.text == "Add Person" { return label }
            return view.subviews.lazy.compactMap( find ).first
        }
        func scroll( _ view: UIView ) -> UIScrollView? {
            if let found = view as? UIScrollView { return found }
            return view.subviews.lazy.compactMap( scroll ).first
        }
        let card = panel( screen.view )!
        XCTAssertGreaterThan( find( card )?.bounds.height ?? 0, 10, "the rows give way, never the title" )
        XCTAssertGreaterThan( scroll( card )!.contentSize.height, scroll( card )!.bounds.height )
        XCTAssertGreaterThan( scroll( card )!.bounds.height, 100 )
    }

    func testAHostThatGivesNoneDrawsNoButton() {
        CallsAddPersonStore.current = nil
        XCTAssertEqual( button( screen().view )?.isHidden, true )

        let screen = screen()
        screen.showAddPerson()
        XCTAssertNil( panel( screen.view ), "and nothing opens" )
    }

    func testTheButtonIsThereOnceTheCallIsUp() {
        for phase in [ "ringing_out", "ringing_in", "connecting", "reconnecting" ] {
            XCTAssertEqual( button( screen( phase: phase ).view )?.isHidden, true, phase )
        }
        XCTAssertEqual( button( screen().view )?.isHidden, false, "a call between two" )
        XCTAssertEqual( button( screen( group: true ).view )?.isHidden, false, "a group call" )
        XCTAssertEqual( button( screen( phase: "connecting", group: true ).view )?.isHidden, true, "a group call joining" )
    }

    func testTheListSaysItIsLoadingThenWhomItOffersOrThatThereIsNoOne() {
        let loading = opened()
        XCTAssertTrue( texts( loading.view ).contains( "Add Person" ) )
        XCTAssertTrue( texts( loading.view ).contains( "Loading..." ) )
        XCTAssertEqual( button( loading.view )?.isOn, true, "its button latched while it is open" )

        asked.removeLast()( [ ann, ben ] )
        XCTAssertFalse( texts( loading.view ).contains( "Loading..." ) )
        XCTAssertTrue( texts( loading.view ).contains( "Ann" ) )
        XCTAssertTrue( texts( loading.view ).contains( "Ben" ) )

        let nobody = opened( [] )
        XCTAssertTrue( texts( nobody.view ).contains( "There is no one else to add" ) )
    }

    func testAPressRingsThemAndTheirRowSaysHowItStands() {
        let screen = opened( [ ann, ben ] )
        press( row( "Ann", in: screen.view )! )
        XCTAssertEqual( added.map( \.person ), [ ann ] )
        XCTAssertEqual( row( "Ben", in: screen.view )?.isEnabled, false, "one at a time, as the web" )

        press( row( "Ben", in: screen.view )! )
        XCTAssertEqual( added.count, 1 )

        rings = [ .init( id: "r1", to: "43", state: "ringing", canCancel: true ) ]
        added.removeLast().done( nil )
        XCTAssertNotNil( panel( screen.view ), "it stays, where the row says how the ring stands" )
        XCTAssertTrue( texts( screen.view ).contains( "Ringing…" ) )
        XCTAssertEqual( row( "Ann", in: screen.view )?.isEnabled, false, "ringing, not rung again" )
        XCTAssertEqual( row( "Ben", in: screen.view )?.isEnabled, true )
    }

    func testEachWayARingEndsIsSaid() {
        let screen = opened( [ ann ] )
        for ( state, said ) in [
            ( "answered", "Answered" ), ( "rejected", "Declined" ), ( "busy", "Busy" ), ( "no_answer", "No answer" ), ( "cancelled", "Cancelled" ),
        ] {
            rings = [ .init( id: "r", to: "43", state: state, canCancel: false ) ]
            screen.apply( state: self.state( phase: "in_progress" ) )
            XCTAssertTrue( texts( screen.view ).contains( said ), state )
            XCTAssertEqual( row( "Ann", in: screen.view )?.isEnabled, true, "\( state ): the person can be rung again" )
            XCTAssertNil( pill( panel( screen.view )! ), "\( state ): nothing to call off" )
        }
    }

    func testAPersonsLastRingIsWhatTheirRowSays() {
        rings = [
            .init( id: "old", to: "43", state: "busy", canCancel: false ),
            .init( id: "new", to: "43", state: "no_answer", canCancel: false ),
        ]
        let screen = opened( [ ann ] )
        XCTAssertTrue( texts( screen.view ).contains( "No answer" ) )
        XCTAssertFalse( texts( screen.view ).contains( "Busy" ) )
    }

    func testCancelCallsOffARingThisAppRangAlone() {
        rings = [ .init( id: "r1", to: "43", state: "ringing", canCancel: false ) ]
        let screen = opened( [ ann ] )
        XCTAssertNil( pill( panel( screen.view )! ), "a ring of someone else in the call" )

        rings = [ .init( id: "r1", to: "43", state: "ringing", canCancel: true ) ]
        screen.apply( state: state( phase: "in_progress" ) )
        let cancel = pill( panel( screen.view )! )
        XCTAssertEqual( cancel?.accessibilityLabel, "Cancel Ann" )
        XCTAssertFalse( row( "Ann", in: screen.view )?.isAccessibilityElement ?? true, "read beside its Cancel, not over it" )

        press( cancel! )
        XCTAssertEqual( cancelled.map( \.ring ), [ "r1" ] )
        XCTAssertEqual( pill( panel( screen.view )! )?.isEnabled, false, "once" )

        rings = [ .init( id: "r1", to: "43", state: "cancelled", canCancel: false ) ]
        cancelled.removeLast().done( nil )
        XCTAssertNotNil( panel( screen.view ) )
        XCTAssertTrue( texts( screen.view ).contains( "Cancelled" ) )
        XCTAssertNil( pill( panel( screen.view )! ) )
    }

    func testACancelThatFailedIsSaid() {
        rings = [ .init( id: "r1", to: "43", state: "ringing", canCancel: true ) ]
        let screen = opened( [ ann ] )
        press( pill( panel( screen.view )! )! )
        cancelled.removeLast().done( "You cannot make this call" )
        XCTAssertNil( panel( screen.view ) )
        XCTAssertTrue( texts( screen.view ).contains( "You cannot make this call" ) )
    }

    func testAFailureClosesItAndTheScreenSaysWhy() {
        let screen = opened( [ ann ] )
        press( row( "Ann", in: screen.view )! )
        added.removeLast().done( "You cannot make this call" )
        XCTAssertNil( panel( screen.view ) )
        XCTAssertEqual( button( screen.view )?.isOn, false )
        XCTAssertTrue( texts( screen.view ).contains( "You cannot make this call" ) )
    }

    func testAPressOfItsButtonClosesItAndAnotherPanelTakesItsPlace() {
        let screen = opened( [ ann ] )
        screen.showAddPerson()
        XCTAssertNil( panel( screen.view ), "the same press closes it" )

        screen.showAddPerson()
        XCTAssertNotNil( panel( screen.view ) )
        screen.showPanel( title: "Something else", rows: [] )
        XCTAssertNil( panel( screen.view ), "one at a time" )
    }

    func testItStaysOverACallBecomingAGroupCall() {
        let screen = opened( [ ann ] )
        rings = [ .init( id: "r1", to: "43", state: "ringing", canCancel: true ) ]

        for ( phase, group ) in [ ( "connecting", true ), ( "reconnecting", true ), ( "in_progress", true ) ] {
            screen.apply( state: state( phase: phase, group: group ) )
            XCTAssertNotNil( panel( screen.view ), phase )
            XCTAssertTrue( texts( screen.view ).contains( "Ringing…" ), phase )
        }
        XCTAssertEqual( button( screen.view )?.isHidden, false )
        XCTAssertEqual( button( screen.view )?.isOn, true )
    }

    func testAChangeOfTheCallLeavesItsRowsWhereNothingOfThemChanged() {
        let screen = opened( [ ann ] )
        let before = row( "Ann", in: screen.view )
        screen.apply( state: state( phase: "in_progress" ) )
        XCTAssertTrue( row( "Ann", in: screen.view ) === before, "a finger on one stays on it" )

        rings = [ .init( id: "r1", to: "43", state: "busy", canCancel: false ) ]
        screen.apply( state: state( phase: "in_progress" ) )
        XCTAssertFalse( row( "Ann", in: screen.view ) === before )
    }

    func testItGoesWithTheCallAndWithAHostThatStopsGivingIt() {
        let screen = opened( [ ann ] )
        screen.apply( state: state( phase: "idle" ) )
        XCTAssertNil( panel( screen.view ) )
        XCTAssertEqual( button( screen.view )?.isHidden, true )

        screen.apply( state: state( phase: "in_progress" ) )
        screen.showAddPerson()
        XCTAssertNotNil( panel( screen.view ) )
        CallsAddPersonStore.current = nil
        screen.apply( state: state( phase: "in_progress" ) )
        XCTAssertNil( panel( screen.view ) )
        XCTAssertEqual( button( screen.view )?.isHidden, true )
    }

    func testTheAppArrangesItByItsId() {
        var ids: [ String ] = []
        CallScreen.shared.pieces = .init( controls: { ours, _ in
            ids = ours.map( \.id )
            return ours.filter { $0.id != "add" }
        } )
        defer { CallScreen.shared.pieces = .init() }
        let arranged = screen()
        XCTAssertTrue( ids.contains( "add" ) )
        XCTAssertLessThan( ids.firstIndex( of: "share" )!, ids.firstIndex( of: "add" )! )
        XCTAssertLessThan( ids.firstIndex( of: "add" )!, ids.firstIndex( of: "end" )! )
        XCTAssertNil( button( arranged.view ), "an app can take it away" )
    }

    func testTheScreenOffersThoseListedLessWhomTheRuleRefusesAndAnyoneInTheCall() {
        let listed = [
            CallPerson( id: "1", name: "One" ), CallPerson( id: "2", name: "Two", avatar: "https://example.invalid/2.png" ),
            CallPerson( id: "3", name: "Three" ), CallPerson( id: "4", name: "Four" ),
        ]
        XCTAssertEqual(
            CallScreen.offered( listed, may: [ true, nil, false, true ], inCall: [ "4" ] ),
            [ .init( id: "1", name: "One", avatar: "" ), .init( id: "2", name: "Two", avatar: "https://example.invalid/2.png" ) ],
            "no answer keeps them, as the ring still asks the rule"
        )
        XCTAssertEqual( CallScreen.offered( listed, may: [], inCall: [] ).count, 4, "a route that gave no answers at all" )
        XCTAssertEqual( CallScreen.offered( [], may: [], inCall: [] ), [] )
    }

    func testARingThatDidNotGoOutIsSaidAsACallThatDidNot() {
        XCTAssertEqual( CallScreen.addFailure( CallError( "forbidden" ) ), "You cannot make this call" )
        XCTAssertEqual( CallScreen.addFailure( CallError( "not_connected" ) ), "This call could not be connected" )
    }
}
"""## ),
    ( "Tests/AvatarsTests.swift", ##"""
#if canImport(UIKit)
import UIKit
import XCTest
@testable import WordPlusRealtimeUI

/// The avatars of the call screens (CallsAvatars): an SVG, which UIKit has no decoder for and letter-avatar generators
/// serve, comes out a picture drawn by WebKit with its colours where the SVG put them, known by its type or by its bytes;
/// bytes that are no picture are none; and the initials that stand in for a picture. Run on a simulator, as PiecesTests.
final class AvatarsTests: XCTestCase {
    /// A letter avatar as one such generator writes it: a square of colour, two letters on it.
    private let svg = """
        <svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="100px" height="100px" \
        viewBox="0 0 100 100" style="user-select: none;"><rect fill="#c86ec8" cx="50" width="100" height="100" cy="50" \
        r="50"/><text x="50%" y="50%" style="color: #fff; line-height: 1;font-family: -apple-system, sans-serif;" \
        alignment-baseline="middle" text-anchor="middle" font-size="50" font-weight="400" dy=".1em" \
        dominant-baseline="middle" fill="#fff">IN</text></svg>
        """

    private func picture( _ data: Data, type: String? ) -> UIImage? {
        let drawn = expectation( description: "the picture is decided" )
        var image: UIImage?

        CallsAvatars.picture( from: data, type: type ) { picture in
            image = picture
            drawn.fulfill()
        }

        wait( for: [ drawn ], timeout: 30 )

        return image
    }

    /// The colour at a point of the picture, as 0–255 red, green and blue.
    private func colour( of image: UIImage, x: Int, y: Int ) -> [ Int ] {
        guard let cg = image.cgImage else { return [] }

        var pixel = [ UInt8 ]( repeating: 0, count: 4 )
        let context = CGContext(
            data: &pixel, width: 1, height: 1, bitsPerComponent: 8, bytesPerRow: 4,
            space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        )!

        context.draw( cg, in: CGRect( x: -x, y: y - cg.height + 1, width: cg.width, height: cg.height ) )

        return pixel.prefix( 3 ).map( Int.init )
    }

    private func near( _ seen: [ Int ], _ wanted: [ Int ] ) -> Bool {
        seen.count == 3 && zip( seen, wanted ).allSatisfy { abs( $0 - $1 ) <= 6 }
    }

    func testAnSvgIsDrawnToAPicture() throws {
        let image = try XCTUnwrap( picture( Data( svg.utf8 ), type: "image/svg+xml" ), "an SVG avatar is a picture" )

        XCTAssertEqual( image.cgImage?.width, CallsSvgPictures.side, "drawn as large as the largest avatar on screen" )
        XCTAssertEqual( image.cgImage?.height, CallsSvgPictures.side )
        XCTAssertTrue( near( colour( of: image, x: 4, y: 4 ), [ 200, 110, 200 ] ), "its colour in the corner: \( colour( of: image, x: 4, y: 4 ) )" )

        // The letters are white, somewhere across the middle of it.
        let middle = CallsSvgPictures.side / 2
        let across = stride( from: middle - 60, to: middle + 60, by: 2 ).map { colour( of: image, x: $0, y: middle + 4 ) }
        XCTAssertTrue( across.contains { near( $0, [ 255, 255, 255 ] ) }, "its letters are drawn: \( across )" )
    }

    func testAnSvgIsKnownByItsBytesUnderAnotherType() {
        XCTAssertNotNil( picture( Data( svg.utf8 ), type: "application/octet-stream" ), "a server's other word for it is no matter" )
        XCTAssertNotNil( picture( Data( ( "<?xml version=\"1.0\"?>\n" + svg ).utf8 ), type: nil ), "nor an XML prolog" )
    }

    func testOneSvgAfterAnotherIsEachDrawn() {
        let first = expectation( description: "the first" )
        let second = expectation( description: "the second" )
        var drawn = [ Bool ]()

        CallsAvatars.picture( from: Data( svg.utf8 ), type: "image/svg+xml" ) { drawn.append( $0 != nil ); first.fulfill() }
        CallsAvatars.picture( from: Data( svg.replacingOccurrences( of: "#c86ec8", with: "#3a7bd5" ).utf8 ), type: "image/svg+xml" ) {
            drawn.append( $0 != nil )
            second.fulfill()
        }

        wait( for: [ first, second ], timeout: 30, enforceOrder: true )
        XCTAssertEqual( drawn, [ true, true ], "two avatars asked for at once are both drawn" )
    }

    func testWhatIsNoPictureIsNone() {
        XCTAssertNil( picture( Data( "<html><body>Not found</body></html>".utf8 ), type: "text/html" ), "a page of an error is no avatar" )
        XCTAssertNil( picture( Data(), type: "image/png" ), "nor is nothing" )
        XCTAssertNil( picture( Data( "<svg xmlns=\"http://www.w3.org/2000/svg\"><rect".utf8 ), type: "image/svg+xml" ), "nor an SVG cut short" )
    }

    func testInitials() {
        XCTAssertEqual( CallsAvatars.initials( of: "ann lee" ), "AL" )
        XCTAssertEqual( CallsAvatars.initials( of: "Ann Lee Cole" ), "AL", "two letters at most" )
        XCTAssertEqual( CallsAvatars.initials( of: "Ann" ), "A" )
        XCTAssertEqual( CallsAvatars.initials( of: "" ), "?" )
        XCTAssertEqual( CallsAvatars.initials( of: "  " ), "?" )
    }
}
#endif
"""## ),
    ( "Tests/CallNoticesTests.swift", ##"""
#if canImport(UIKit)
import UIKit
import XCTest
import WordPlusRealtimeCalls
@testable import WordPlusRealtimeUI

/// What the SDK's call screen says of a group call that goes on, and what its dock leaves out. Run on a simulator, as
/// PiecesTests.
@MainActor
final class CallNoticesTests: XCTestCase {
    func testTheCallsWordsForWhatCouldNotGoOut() {
        XCTAssertEqual( CallScreen.failure( GroupCallFailure( code: "publish_failed", source: "camera" ) ), "Your camera could not be sent." )
        XCTAssertEqual( CallScreen.failure( GroupCallFailure( code: "publish_failed", source: "microphone" ) ), "Your microphone could not be sent." )
        XCTAssertEqual( CallScreen.failure( GroupCallFailure( code: "encryption_failed", message: "no key" ) ), "Part of this call could not be encrypted." )
        XCTAssertEqual( CallScreen.failure( GroupCallFailure( code: "something_new" ) ), "Something went wrong in this call." )
    }

    func testAnSDKListenerHasNoHandToRaise() {
        // The call's own hands are a host's and its site's (`carriesRoomRules`): the SDK's group call has no way to send
        // one, so a listener's dock has no button that would do nothing. An app adds a control of its own (docs).
        let screen = CallsScreen()
        screen.loadViewIfNeeded()
        screen.view.frame = CGRect( x: 0, y: 0, width: 390, height: 844 )
        var state = CallScreenPreview.state( .group )
        state[ "phase" ] = "in_progress"
        screen.apply( state: state )
        let listener = CallsRoomParticipant(
            identity: "me", name: "You", avatar: "", isLocal: true, video: nil, screen: nil,
            speaking: false, audioLevel: 0, muted: true, micMuted: false, handRaised: false,
            isPinned: false, canPublish: false, canAdmin: false, mode: "viewer", lost: false
        )
        screen.setRoster( [ listener ] )
        screen.apply( state: state )

        func labels( _ view: UIView ) -> [ String ] {
            ( view.isHidden ? [] : [ view.accessibilityLabel ].compactMap { $0 } ) + ( view.isHidden ? [] : view.subviews.flatMap( labels ) )
        }
        XCTAssertFalse( labels( screen.view ).contains( "Raise Hand" ) )
    }
}
#endif
"""## ),
    ( "Tests/CallRecordingStateTests.swift", ##"""
#if canImport(UIKit)
import UIKit
import XCTest
import WordPlusRealtimeCalls
@testable import WordPlusRealtimeUI

/// A group call's recording as the SDK's CallScreen names it to the screens (`state["recording"]`): Start for a host, its
/// answer, REC from the room's flag for everyone, and what a refusal leaves. Who is told what from there is RecordingTests.
@MainActor
final class CallRecordingStateTests: XCTestCase {
    private let rec = GroupRecording( id: "rec_0123456789", state: "recording" )

    override func setUp() {
        super.setUp()
        UserDefaults.standard.removeObject( forKey: CallsEngine.recordingNoticeNeverKey )
    }

    override func tearDown() {
        UserDefaults.standard.removeObject( forKey: CallsEngine.recordingNoticeNeverKey )
        super.tearDown()
    }

    func testNothingForSomeoneWhoMayNotWhileNothingRecords() {
        XCTAssertNil( CallRecordingState().state( can: false ) )
        let host = CallRecordingState().state( can: true )
        XCTAssertEqual( host?[ "state" ] as? String, "off" )
        XCTAssertEqual( host?[ "can" ] as? Bool, true )
    }

    func testAHostStartsAndStopsIt() {
        var state = CallRecordingState()
        state.ask( "starting" )
        XCTAssertEqual( state.state( can: true )?[ "state" ] as? String, "starting" )

        state.started( rec, now: 1_000 )
        var named = state.state( can: true )
        XCTAssertEqual( named?[ "state" ] as? String, "on" )
        XCTAssertEqual( named?[ "id" ] as? String, "rec_0123456789" )
        XCTAssertEqual( named?[ "since" ] as? Int, 1_000 )
        XCTAssertEqual( named?[ "mine" ] as? Bool, true )
        XCTAssertEqual( named?[ "can" ] as? Bool, true )

        // The room says so a moment later: the same recording, not another.
        state.flagged( true, now: 1_002 )
        XCTAssertEqual( state.state( can: true )?[ "id" ] as? String, "rec_0123456789" )
        XCTAssertEqual( state.state( can: true )?[ "since" ] as? Int, 1_000 )

        state.ask( "stopping" )
        XCTAssertEqual( state.state( can: true )?[ "state" ] as? String, "stopping" )

        // Stopped, and still stopping until the room says it has.
        state.stopped()
        named = state.state( can: true )
        XCTAssertEqual( named?[ "state" ] as? String, "stopping" )
        XCTAssertEqual( named?[ "id" ] as? String, "rec_0123456789" )
        state.flagged( false, now: 1_060 )
        XCTAssertEqual( state.state( can: true )?[ "state" ] as? String, "off" )
    }

    func testARoomThatNeverSaidSoStopsAtOnce() {
        var state = CallRecordingState()
        state.started( rec, now: 1_000 )
        state.stopped()
        XCTAssertEqual( state.state( can: true )?[ "state" ] as? String, "off" )
    }

    func testARefusalLeavesItAsItWas() {
        var state = CallRecordingState()
        state.ask( "starting" )
        state.refused()
        XCTAssertEqual( state.state( can: true )?[ "state" ] as? String, "off" )

        state.started( rec, now: 1_000 )
        state.ask( "stopping" )
        state.refused()
        XCTAssertEqual( state.state( can: true )?[ "state" ] as? String, "on" )
    }

    func testSomeoneElsesRecordingIsRECWithNoStop() {
        // Joined while it records, or there as someone else started it: the room's flag names no id to stop.
        var state = CallRecordingState( flag: true, now: 2_000 )
        var named = state.state( can: true )
        XCTAssertEqual( named?[ "state" ] as? String, "on" )
        XCTAssertEqual( named?[ "can" ] as? Bool, false )
        XCTAssertEqual( named?[ "mine" ] as? Bool, nil )
        XCTAssertEqual( named?[ "tell" ] as? String, "notice" )
        XCTAssertEqual( named?[ "since" ] as? Int, 2_000 )
        let first = named?[ "id" ] as? String
        XCTAssertFalse( first?.isEmpty ?? true )

        // The next one is told again, as the answers are kept by its id.
        state.flagged( false, now: 2_100 )
        XCTAssertNil( state.state( can: false ) )
        state.flagged( true, now: 2_200 )
        named = state.state( can: false )
        XCTAssertNotEqual( named?[ "id" ] as? String, first )
    }

    func testTheRoomStoppingItEndsOurOwnToo() {
        var state = CallRecordingState( flag: false, now: 0 )
        state.started( rec, now: 1_000 )
        state.flagged( true, now: 1_001 )
        state.flagged( false, now: 1_100 )
        XCTAssertEqual( state.state( can: true )?[ "state" ] as? String, "off" )
        XCTAssertNil( state.own )
    }

    func testDoNotShowAgainLeavesRECAlone() {
        XCTAssertEqual( CallRecordingState( flag: true, now: 1 ).state( can: false )?[ "notice" ] as? Bool, true )
        CallsEngine.shared.recordingNoticeNever()
        XCTAssertEqual( CallRecordingState( flag: true, now: 1 ).state( can: false )?[ "notice" ] as? Bool, false )
    }

    func testTheEngineAsksWhoeverAnswersAndRefusesWithNobody() {
        CallsEngine.shared.onRecord = nil
        var answer: Bool?
        CallsEngine.shared.startRecording { ok, _ in answer = ok }
        XCTAssertEqual( answer, false )

        var asked: [ Bool ] = []
        CallsEngine.shared.onRecord = { start, completion in
            asked.append( start )
            completion( true, nil )
        }
        defer { CallsEngine.shared.onRecord = nil }
        CallsEngine.shared.startRecording { ok, _ in answer = ok }
        XCTAssertEqual( answer, true )
        CallsEngine.shared.stopRecording { _, _ in }
        XCTAssertEqual( asked, [ true, false ] )
    }
}
#endif
"""## ),
    ( "Tests/GroupCornerTests.swift", ##"""
#if canImport(UIKit)
import UIKit
import XCTest
@testable import WordPlusRealtimeUI

/// A group call's corner window: whom it shows, as the web's pipFocus chooses (realtime-ui inc/calls/pip-focus.ts), and
/// when the dock offers it, as its useGroupPip. The system's window itself takes a real device: on a simulator the tests
/// stop at what is handed to it. Run on a simulator, as PiecesTests.
@MainActor
final class GroupCornerTests: XCTestCase {
    private typealias Person = CallsPipFocus.Person

    private let me = Person( identity: "me", isLocal: true, camera: true )
    private let ann = Person( identity: "ann", camera: true )
    private let ben = Person( identity: "ben" )

    func testTheSpotlightAndThePinsComeFirst() {
        let sharing = Person( identity: "cara", screen: true )
        XCTAssertEqual( CallsPipFocus.pick( [ me, ann, ben, sharing ], first: [ "ben" ], last: "ann" ), "ben" )
        // This user's own tile, where they are the one in the spotlight.
        XCTAssertEqual( CallsPipFocus.pick( [ me, ann ], first: [ "me" ], last: nil ), "me" )
        // Of several, the loudest while they speak, then who spoke last, then the first.
        let talking = Person( identity: "ann", camera: true, speaking: true, level: 0.2 )
        let louder = Person( identity: "ben", speaking: true, level: 0.6 )
        XCTAssertEqual( CallsPipFocus.pick( [ me, talking, louder ], first: [ "ann", "ben" ], last: nil ), "ben" )
        XCTAssertEqual( CallsPipFocus.pick( [ me, ann, ben ], first: [ "ann", "ben" ], last: "ben" ), "ben" )
        XCTAssertEqual( CallsPipFocus.pick( [ me, ann, ben ], first: [ "ann", "ben" ], last: nil ), "ann" )
        // Someone who left is not kept ahead.
        XCTAssertEqual( CallsPipFocus.pick( [ me, ann ], first: [ "gone" ], last: nil ), "ann" )
    }

    func testAScreenThenWhoSpeaksThenWhoSpokeLast() {
        let sharing = Person( identity: "cara", screen: true )
        let talking = Person( identity: "ben", speaking: true, level: 0.4 )
        XCTAssertEqual( CallsPipFocus.pick( [ me, talking, sharing ], first: [], last: nil ), "cara" )
        XCTAssertEqual( CallsPipFocus.pick( [ me, ann, talking ], first: [], last: nil ), "ben" )
        XCTAssertEqual( CallsPipFocus.pick( [ me, ann, ben ], first: [], last: "ben" ), "ben" )
        // Who spoke last and has gone is nobody, and a share of this user's own is not what the window is for.
        XCTAssertEqual( CallsPipFocus.pick( [ me, ben, ann ], first: [], last: "gone" ), "ann" )
        let ownShare = Person( identity: "me", isLocal: true, screen: true )
        XCTAssertEqual( CallsPipFocus.pick( [ ownShare, ben ], first: [], last: nil ), "ben" )
    }

    func testTheFirstWithAPictureTheFirstOtherThenTheUser() {
        XCTAssertEqual( CallsPipFocus.pick( [ me, ben, ann ], first: [], last: nil ), "ann" )
        XCTAssertEqual( CallsPipFocus.pick( [ me, ben ], first: [], last: nil ), "ben" )
        XCTAssertEqual( CallsPipFocus.pick( [ me ], first: [], last: nil ), "me" )
        XCTAssertNil( CallsPipFocus.pick( [], first: [], last: nil ) )
    }

    func testAVideoCallHasItAllThroughAnAudioCallOnlyForAScreen() {
        XCTAssertTrue( CallsPipFocus.offered( [ me, ben ], video: true ) )
        XCTAssertFalse( CallsPipFocus.offered( [], video: true ) )
        XCTAssertFalse( CallsPipFocus.offered( [ me, ben ], video: false ) )
        XCTAssertTrue( CallsPipFocus.offered( [ me, Person( identity: "cara", screen: true ) ], video: false ) )
        // This user's own share would show them what they are sharing.
        XCTAssertFalse( CallsPipFocus.offered( [ Person( identity: "me", isLocal: true, screen: true ), ben ], video: false ) )
    }

    private func screen( video: Bool ) -> CallsScreen {
        let screen = CallsScreen()
        screen.loadViewIfNeeded()
        screen.view.frame = CGRect( x: 0, y: 0, width: 390, height: 844 )
        screen.show( name: "Daily meeting", avatar: "", video: video )
        let state = CallScreenPreview.state( video ? .group : .groupVoice )
        screen.apply( state: state )
        screen.setRoster( CallScreenPreview.people() )
        screen.apply( state: state )
        screen.view.layoutIfNeeded()
        return screen
    }

    private func dock( _ screen: CallsScreen ) -> [ String ] {
        func find( _ view: UIView ) -> UIStackView? {
            if let stack = view as? UIStackView, stack.arrangedSubviews.contains( where: { $0.accessibilityLabel == "Exit Chat" } ) { return stack }
            return view.subviews.lazy.compactMap( find ).first
        }
        return find( screen.view )?.arrangedSubviews.filter { !$0.isHidden }.map { $0.accessibilityLabel ?? "?" } ?? []
    }

    func testTheDockAndTheWindowFollowTheChoice() throws {
        defer { CallsPip.shared.detach() }
        let screen = screen( video: true )
        // The one speaking, by name, and their face: the preview's people send no picture.
        XCTAssertEqual( CallsPip.shared.who, CallsPip.Who( name: "Ann", avatar: "" ) )
        XCTAssertTrue( CallsPip.shared.hasContent )

        screen.togglePinForMe( "ben" )
        XCTAssertEqual( CallsPip.shared.who?.name, "Ben" )
        screen.togglePinForMe( "ben" )

        if CallsPip.isSupported {
            XCTAssertTrue( dock( screen ).contains( "Picture In Picture" ), "\( dock( screen ) )" )
        }

        // Nobody is left, and the window goes with them.
        screen.setRoster( [] )
        XCTAssertNil( CallsPip.shared.who )
        XCTAssertFalse( CallsPip.shared.hasContent )
    }

    func testAnAudioCallHasNoWindowWithNoScreen() {
        defer { CallsPip.shared.detach() }
        let screen = screen( video: false )
        XCTAssertNil( CallsPip.shared.who )
        XCTAssertFalse( CallsPip.shared.hasContent )
        XCTAssertFalse( dock( screen ).contains( "Picture In Picture" ), "\( dock( screen ) )" )
    }

    func testTheSameWindowForACallBetweenTwo() {
        // No one named over a picture of the other side: as it was.
        defer { CallsPip.shared.detach() }
        CallsPip.shared.showRoom( nil )
        XCTAssertNil( CallsPip.shared.who )
        XCTAssertFalse( CallsPip.shared.hasContent )
    }
}
#endif
"""## ),
    ( "Tests/JoinPromptTests.swift", ##"""
#if canImport(UIKit)
import UIKit
import XCTest
@testable import WordPlusRealtimeUI

/// The notice of a group call's join, as the web's JoinPrompt draws it: Do Not Show Again beside Preview where the host
/// keeps the user's choice, and none where it keeps none. Run on a simulator, as RecordingTests.
@MainActor
final class JoinPromptTests: XCTestCase {
    private func pills( _ view: UIView ) -> [ CallsDevicePill ] {
        view.subviews.flatMap { ( $0 as? CallsDevicePill ).map { [ $0 ] } ?? pills( $0 ) }
    }

    /// A tap's actions, run as UIKit would: the tests have no application to send them through.
    private func press( _ control: UIControl ) {
        for target in control.allTargets {
            for action in control.actions( forTarget: target, forControlEvent: .touchUpInside ) ?? [] {
                _ = ( target as NSObject ).perform( Selector( action ) )
            }
        }
    }

    func testDoNotShowAgainOnlyWhereTheHostKeepsTheChoice() {
        XCTAssertEqual( pills( CallsJoinPrompt( video: true ) ).map { $0.accessibilityLabel }, [ "Preview" ] )
        XCTAssertEqual( pills( CallsJoinPrompt( video: false ) ).map { $0.accessibilityLabel }, [ "Test Microphone" ] )

        let prompt = CallsJoinPrompt( video: true, never: true )
        XCTAssertEqual( pills( prompt ).map { $0.accessibilityLabel }, [ "Preview", "Do Not Show Again" ] )

        var never = 0
        var preview = 0
        prompt.onNever = { never += 1 }
        prompt.onPreview = { preview += 1 }
        pills( prompt ).last.map( press )
        XCTAssertEqual( never, 1 )
        XCTAssertEqual( preview, 0 )
    }

    func testTheButtonsStayInsideANarrowCard() {
        let host = UIView( frame: CGRect( x: 0, y: 0, width: 320, height: 640 ) )
        let dock = UIView()
        dock.translatesAutoresizingMaskIntoConstraints = false
        host.addSubview( dock )
        NSLayoutConstraint.activate( [
            dock.leadingAnchor.constraint( equalTo: host.leadingAnchor ),
            dock.trailingAnchor.constraint( equalTo: host.trailingAnchor ),
            dock.bottomAnchor.constraint( equalTo: host.bottomAnchor ),
            dock.heightAnchor.constraint( equalToConstant: 80 ),
        ] )

        let prompt = CallsJoinPrompt( video: false, never: true )
        prompt.place( in: host, above: dock )
        host.layoutIfNeeded()

        for pill in pills( prompt ) {
            let frame = pill.convert( pill.bounds, to: prompt )
            XCTAssertLessThanOrEqual( frame.maxX, prompt.bounds.maxX, "\( pill.accessibilityLabel ?? "" ) runs out of the card" )
        }
    }
}
#endif
"""## ),
    ( "Tests/ModerationTests.swift", ##"""
#if canImport(UIKit)
import UIKit
import XCTest
@testable import WordPlusRealtimeUI
import WordPlusRealtime
import WordPlusRealtimeCalls

/// A host on the SDK's group calls, as the web's SDK screens have one (realtime-ui's use-group-call.ts): the person
/// menu's acts as the SDK's calls take them, the user a tile is, and Host Controls without the room's own rules, which
/// the cloud doesn't keep. Run on a simulator: `xcodebuild test -scheme WordPlusRealtime-Package -destination
/// 'platform=iOS Simulator,name=iPhone 16' -only-testing:WordPlusRealtimeUITests/ModerationTests`.
@MainActor
final class ModerationTests: XCTestCase {
    override func tearDown() {
        let engine = CallsEngine.shared
        engine.canModerate = false
        engine.carriesRoomRules = false
        engine.carriesSpotlight = false
        engine.onSpotlight = nil
        engine.isVideo = true
        engine.offers = nil
        engine.carriesAsks = false
        engine.canEndForEveryone = false
        engine.onBan = nil
        engine.callMode = "participatory"
        engine.roomLocked = false
        engine.roomMuted = false
        super.tearDown()
    }

    func testTheSDKsActsAreTheWebs() {
        let all = CallAct.allCases
        XCTAssertEqual( CallScreen.act( for: "remove_participant", offered: all ), .remove )
        XCTAssertEqual( CallScreen.act( for: "mute_participant", offered: all ), .listen )
        XCTAssertEqual( CallScreen.act( for: "demote_participant", offered: all ), .listen )
        XCTAssertEqual( CallScreen.act( for: "unmute_participant", offered: all ), .speak )
        XCTAssertEqual( CallScreen.act( for: "promote_participant", offered: all ), .speak )
        // Mute Microphone holds it where the call holds one, else mutes it once; Allow Microphone lets it go.
        XCTAssertEqual( CallScreen.act( for: "mute_mic", offered: all ), .holdMic )
        XCTAssertEqual( CallScreen.act( for: "mute_mic", offered: CallAct.base ), .mute )
        XCTAssertEqual( CallScreen.act( for: "unmute_mic", offered: all ), .releaseMic )
        // What the SDK's calls carry none of answers false.
        XCTAssertNil( CallScreen.act( for: "lock_room", offered: all ) )
        XCTAssertNil( CallScreen.act( for: "pin_participant", offered: all ) )
        // The room's rules and the asks, in the screens' words.
        XCTAssertEqual( CallScreen.rule( for: "mute_all" )?.muted, true )
        XCTAssertEqual( CallScreen.rule( for: "unlock_room" )?.locked, false )
        XCTAssertEqual( CallScreen.rule( for: "set_broadcast_mode" )?.mode, .broadcast )
        XCTAssertEqual( CallScreen.rule( for: "set_participatory_mode" )?.mode, .participatory )
        XCTAssertNil( CallScreen.rule( for: "remove_participant" ) )
        XCTAssertEqual( CallScreen.devices( for: "ask_camera_microphone" ), [ .camera, .microphone ] )
        XCTAssertEqual( CallScreen.devices( for: "ask_microphone" ), [ .microphone ] )

        XCTAssertEqual( CallScreen.user( of: "user_42" ), "42" )
        XCTAssertEqual( CallScreen.user( of: "user_auth0|5f7c8e" ), "auth0|5f7c8e" )
        XCTAssertNil( CallScreen.user( of: "user_" ) )
        XCTAssertNil( CallScreen.user( of: "ingest" ) )
    }

    private func person( _ id: Int, local: Bool = false, admin: Bool = false ) -> CallsRoomParticipant {
        CallsRoomParticipant(
            identity: "user_\( id )", name: local ? "Me" : "Person \( id )", avatar: "", isLocal: local, video: nil, screen: nil,
            speaking: false, audioLevel: 0, muted: false, micMuted: false, handRaised: false, isPinned: false,
            canPublish: true, canAdmin: admin, mode: "participant", lost: false
        )
    }

    private func screen( _ people: [ CallsRoomParticipant ], spotlight: [ String ] = [] ) -> CallsScreen {
        let screen = CallsScreen()
        screen.loadViewIfNeeded()
        screen.view.frame = CGRect( x: 0, y: 0, width: 390, height: 844 )
        screen.show( name: "Group", avatar: "", video: true )
        screen.apply( state: [ "phase": "in_progress", "type": "video", "group": true, "local": [ "muted": true, "camera": false ], "spotlight": spotlight ] )
        screen.setRoster( people )
        screen.view.layoutIfNeeded()
        return screen
    }

    private func texts( _ view: UIView ) -> [ String ] {
        guard !view.isHidden else { return [] }
        return ( ( view as? UILabel )?.text.map { [ $0 ] } ?? [] ) + view.subviews.flatMap { texts( $0 ) }
    }

    private func hostControls( _ screen: CallsScreen ) -> [ String ] {
        CallsModeration.show( from: screen, participants: screen.roster )
        defer { screen.closePopover() }
        return screen.view.subviews.compactMap { $0 as? CallsPopover }.last.map { texts( $0 ) } ?? []
    }

    func testHostControlsHoldTheRoomsRulesOnlyWhereTheCallCarriesThem() {
        let engine = CallsEngine.shared
        engine.canModerate = true
        let people = [ person( 1, local: true, admin: true ), person( 2 ) ]

        // The SDK's calls: the join alerts, no rule of the room.
        engine.carriesRoomRules = false
        let sdk = hostControls( screen( people ) )
        XCTAssertTrue( sdk.contains( "Host Controls" ) )
        XCTAssertTrue( sdk.contains( "Join Alerts" ) )
        for rule in [ "Mute Everyone", "Lock Room", "Broadcast Mode", "Sound for Raised Hands" ] {
            XCTAssertFalse( sdk.contains( rule ), rule )
        }

        // An engine with them (Better Messages' app): every one, as before.
        engine.carriesRoomRules = true
        let rules = hostControls( screen( people ) )
        for rule in [ "Mute Everyone", "Lock Room", "Broadcast Mode", "Sound for Raised Hands", "Join Alerts" ] {
            XCTAssertTrue( rules.contains( rule ), rule )
        }
    }

    func testAHostOfTheSDKsCallsClearsTheSpotlightFromHostControls() {
        let engine = CallsEngine.shared
        engine.canModerate = true
        engine.carriesSpotlight = true
        let people = [ person( 1, local: true, admin: true ), person( 2 ) ]

        XCTAssertFalse( hostControls( screen( people ) ).contains( "Clear Spotlight" ) )
        let spotlit = hostControls( screen( people, spotlight: [ "user_2" ] ) )
        XCTAssertTrue( spotlit.contains( "Clear Spotlight" ) )
        XCTAssertFalse( spotlit.contains( "Lock Room" ) )
    }

    func testTheSpotlightGoesWhereTheCallScreenSendsIt() {
        let engine = CallsEngine.shared
        var answers: [ String ] = []
        func say( _ ok: Bool, _ error: String? ) { answers.append( ok ? "ok" : error ?? "failed" ) }

        // Nobody answering it: nothing happens.
        engine.spotlight( identity: "user_2", on: true, completion: say )

        var asked: [ String ] = []
        engine.onSpotlight = { identity, on, completion in
            asked.append( ( identity ?? "everyone" ) + ( on ? " on" : " off" ) )
            identity == "user_5" ? completion( false, CallsSpotlight.fullText ) : completion( true, nil )
        }
        engine.spotlight( identity: "user_2", on: true, completion: say )
        engine.spotlight( identity: "user_1", on: true, completion: say )
        engine.spotlight( identity: nil, on: false, completion: say )
        engine.spotlight( identity: "user_5", on: true, completion: say )

        XCTAssertEqual( asked, [ "user_2 on", "user_1 on", "everyone off", "user_5 on" ] )
        XCTAssertEqual( answers, [ "failed", "ok", "ok", "ok", "Up to four people can be in the spotlight." ] )
    }

    // MARK: What the call offers (GroupCall.acts), row by row

    private func who( _ id: Int, muted: Bool = false, micMuted: Bool = false, hand: Bool = false, publish: Bool = true ) -> CallsRoomParticipant {
        CallsRoomParticipant(
            identity: "user_\( id )", name: "Person \( id )", avatar: "", isLocal: false, video: nil, screen: nil,
            speaking: false, audioLevel: 0, muted: muted, micMuted: micMuted, handRaised: hand, isPinned: false,
            canPublish: publish, canAdmin: false, mode: "participant", lost: false
        )
    }

    private func menu( _ target: CallsRoomParticipant, offers: [ CallAct ] ) -> [ String ] {
        let engine = CallsEngine.shared
        engine.canModerate = true
        engine.offers = Set( offers.map( \.rawValue ) )
        engine.carriesAsks = offers.contains( .ask )
        engine.carriesSpotlight = offers.contains( .spotlight )
        let shown = screen( [ person( 1, local: true, admin: true ), target ] )
        return CallsModeration.personEntries( target, screen: shown ).compactMap { entry in
            if case let .row( row ) = entry { return row.label }
            return nil
        }
    }

    func testAPersonsMenuOffersOnlyWhatTheCallOffers() {
        CallsEngine.shared.onBan = { _, _, done in done( true ) }

        // Today's five: Mute Microphone once, Stop Camera & Mic, Remove from Call, the spotlight. No ban, no asks.
        let base = menu( who( 2 ), offers: CallAct.base )
        for row in [ "Mute Microphone", "Stop Camera & Mic", "Remove from Call", "Spotlight for Everyone", "Pin for Me" ] {
            XCTAssertTrue( base.contains( row ), row )
        }
        for row in [ "Remove and Ban from Calls…", "Ask to Turn On Camera" ] { XCTAssertFalse( base.contains( row ), row ) }

        // Every act: the ban, and the asks for what is off.
        let all = menu( who( 2, muted: true ), offers: CallAct.allCases )
        for row in [ "Keep Microphone Off", "Remove from Call", "Remove and Ban from Calls…", "Ask to Turn On Camera and Microphone" ] {
            XCTAssertTrue( all.contains( row ), row )
        }

        // None: nothing to do to them, and no pin for everyone of an older engine.
        let none = menu( who( 2 ), offers: [] )
        XCTAssertEqual( none, [ "Pin for Me" ] )

        // A microphone off already, with a mute once alone: nothing to keep off.
        XCTAssertFalse( menu( who( 2, muted: true ), offers: CallAct.base ).contains( "Keep Microphone Off" ) )
        // Without the engine's way to ban, no ban row, whatever the call offers.
        CallsEngine.shared.onBan = nil
        XCTAssertFalse( menu( who( 2 ), offers: CallAct.allCases ).contains( "Remove and Ban from Calls…" ) )
    }

    func testAListenerIsLetSpeakOnlyWhereTheCallOffersSpeak() {
        let listener = who( 2, muted: true, publish: false )
        XCTAssertTrue( menu( listener, offers: [ .speak, .remove ] ).contains( "Allow Camera & Mic" ) )
        XCTAssertFalse( menu( listener, offers: [ .listen, .remove ] ).contains( "Allow Camera & Mic" ) )
        XCTAssertFalse( menu( who( 2 ), offers: [ .speak ] ).contains( "Stop Camera & Mic" ) )
        CallsEngine.shared.callMode = "broadcast"
        XCTAssertTrue( menu( listener, offers: [ .speak ] ).contains( "Promote to Speaker" ) )
        XCTAssertFalse( menu( listener, offers: [ .listen ] ).contains( "Promote to Speaker" ) )
        XCTAssertTrue( menu( who( 2 ), offers: [ .listen ] ).contains( "Demote to Viewer" ) )
    }

    func testAHeldMicrophoneIsLetGoOnlyWhereTheCallOffersIt() {
        let held = who( 2, micMuted: true )
        XCTAssertTrue( menu( held, offers: CallAct.allCases ).contains( "Allow Microphone" ) )
        XCTAssertFalse( menu( held, offers: [ .remove, .holdMic ] ).contains( "Allow Microphone" ) )
        // Its header says who holds it.
        XCTAssertEqual( CallsModeration.personState( held ).map( \.label ), [ "Muted by a moderator" ] )
    }

    func testHandsAreLoweredWhereTheCallKeepsThem() {
        let up = who( 2, hand: true )
        XCTAssertTrue( menu( up, offers: [ .hand, .remove ] ).contains( "Lower Hand" ) )
        XCTAssertFalse( menu( up, offers: [ .remove ] ).contains( "Lower Hand" ) )

        let engine = CallsEngine.shared
        engine.canModerate = true
        engine.offers = [ "hand" ]
        XCTAssertFalse( engine.carriesRoomRules )
        XCTAssertTrue( engine.carriesHands )
        let controls = hostControls( screen( [ person( 1, local: true, admin: true ), up ] ) )
        XCTAssertTrue( controls.contains( "Lower All Hands" ) )
        XCTAssertFalse( controls.contains( "Lock Room" ) )
        engine.offers = [ "remove" ]
        XCTAssertFalse( hostControls( screen( [ person( 1, local: true, admin: true ), up ] ) ).contains( "Lower All Hands" ) )
        // An engine that names no acts keeps hands with its rules, as before.
        engine.offers = nil
        engine.carriesRoomRules = true
        XCTAssertTrue( engine.carriesHands )
    }

    func testHostControlsFollowTheRoomsRulesAndOfferEndButNoRecording() {
        let engine = CallsEngine.shared
        engine.canModerate = true
        engine.offers = Set( CallAct.allCases.map( \.rawValue ) )
        engine.carriesRoomRules = true
        engine.canEndForEveryone = true
        let people = [ person( 1, local: true, admin: true ), person( 2 ) ]

        let rules = hostControls( screen( people ) )
        for row in [ "Mute Everyone", "Lock Room", "Broadcast Mode", "End for Everyone" ] { XCTAssertTrue( rules.contains( row ), row ) }
        XCTAssertFalse( rules.contains( "Start Recording" ) )
        // The call screen offers no recording: a room nobody records shows none, and one recorded shows REC alone.
        XCTAssertNil( CallRecordingState().state( can: false ) )
        XCTAssertEqual( CallRecordingState( flag: true, now: 1 ).state( can: false )?[ "can" ] as? Bool, false )

        // Without `end`, End for Everyone isn't there.
        engine.canEndForEveryone = false
        XCTAssertFalse( hostControls( screen( people ) ).contains( "End for Everyone" ) )
    }

    func testAJoinRefusedIsSaidInTheWebsWords() {
        XCTAssertEqual( CallScreen.refusal( CallError( "locked" ) ), "This call is locked" )
        XCTAssertEqual( CallScreen.refusal( CallError( "banned" ) ), "A moderator removed you from this call until it ends" )
        let until = CallScreen.refusal( CallError( "banned", until: Date( timeIntervalSince1970: 1_800_000_000 ) ) ) ?? ""
        XCTAssertTrue( until.hasPrefix( "A moderator removed you from the calls of this conversation until " ), until )
        XCTAssertFalse( until.contains( "%s" ) )
        XCTAssertNil( CallScreen.refusal( CallError( "forbidden" ) ) )
    }

    func testABanIsAskedForInMinutesHoursOrDaysAtMostSevenDays() {
        XCTAssertEqual( CallsBan.minutes( amount: 1, unit: 60 ), 60 )
        XCTAssertEqual( CallsBan.minutes( amount: 0, unit: 1 ), 1 )
        XCTAssertEqual( CallsBan.minutes( amount: 9999, unit: 60 * 24 ), 7 * 24 * 60 )
        let form = CallsBan.Form()
        XCTAssertEqual( form.minutes, 60 )
        form.unit.selectedSegmentIndex = 2
        form.amount.text = "3"
        XCTAssertEqual( form.minutes, 3 * 24 * 60 )
    }

    func testATileOfSomeoneAwaySaysReconnecting() {
        let away = CallScreen.away( identity: "user_3", info: .object( [ "name": .string( "Ann" ) ] ), publish: true, hand: true )
        XCTAssertTrue( away.reconnecting )
        XCTAssertNil( away.video )
        XCTAssertEqual( away.name, "Ann" )
        XCTAssertTrue( away.handRaised )
    }
}
#endif
"""## ),
    ( "Tests/PiecesTests.swift", ##"""
#if canImport(UIKit)
import UIKit
import XCTest
@testable import WordPlusRealtimeUI

/// The call screen's pieces (CallScreen.Pieces), on the real screen with no call:
/// the dock arranged as the app answers, its own button drawn as ours are and hanging up still last, the status line,
/// the view over the stage, and none of it without pieces. Run on a simulator: `xcodebuild test -scheme
/// WordPlusRealtime-Package -destination 'platform=iOS Simulator,name=iPhone 16'`.
@MainActor
final class PiecesTests: XCTestCase {
    override func tearDown() {
        CallScreen.shared.pieces = .init()
        super.tearDown()
    }

    private func screen( phase: String ) -> CallsScreen {
        _ = CallScreen.shared
        let screen = CallsScreen()
        screen.loadViewIfNeeded()
        screen.view.frame = CGRect( x: 0, y: 0, width: 390, height: 844 )
        screen.apply( state: [ "phase": phase, "type": "video", "group": false, "local": [ "muted": false, "camera": false ] ] )
        screen.view.layoutIfNeeded()
        return screen
    }

    /// The dock's buttons, in their order: by what VoiceOver says of them.
    private func dock( _ screen: CallsScreen ) -> [ String ] {
        func find( _ view: UIView ) -> UIStackView? {
            if let stack = view as? UIStackView, stack.arrangedSubviews.contains( where: { $0.accessibilityLabel == "End Call" } ) { return stack }
            return view.subviews.lazy.compactMap( find ).first
        }
        return find( screen.view )?.arrangedSubviews.map { $0.accessibilityLabel ?? "?" } ?? []
    }

    private func label( _ screen: CallsScreen, _ text: String ) -> UILabel? {
        func find( _ view: UIView ) -> UILabel? {
            if let label = view as? UILabel, label.text == text { return label }
            return view.subviews.lazy.compactMap( find ).first
        }
        return find( screen.view )
    }

    /// A share needs the broadcast extension of the app (ScreenShare), so the dock asks before it shows the button.
    func testTheDockSharesTheScreenOnlyWhereTheAppCan() {
        func button( _ view: UIView ) -> UIView? {
            if view.accessibilityLabel == "Share Screen" { return view }
            return view.subviews.lazy.compactMap( button ).first
        }
        let without = screen( phase: "in_progress" )
        XCTAssertEqual( button( without.view )?.isHidden, true, "by default it is hidden" )

        let can = CallsScreen()
        can.canShareScreen = true
        can.loadViewIfNeeded()
        can.view.frame = CGRect( x: 0, y: 0, width: 390, height: 844 )
        can.apply( state: [ "phase": "in_progress", "type": "video", "group": false, "canShareScreen": true, "local": [ "muted": false, "camera": false ] ] )
        can.view.layoutIfNeeded()
        XCTAssertEqual( button( can.view )?.isHidden, false )
    }

    func testWithoutPiecesTheScreenIsOurs() {
        let ours = screen( phase: "ringing_out" )
        XCTAssertEqual( dock( ours ).last, "End Call" )
        XCTAssertFalse( dock( ours ).contains( "Call notes" ) )
        XCTAssertNotNil( label( ours, "Calling…" ) )
    }

    func testTheAppArrangesTheDockAndAddsItsOwnButtonWithHangingUpLast() {
        var pressed = 0
        var phases: [ String ] = []
        CallScreen.shared.pieces = .init( controls: { ours, state in
            phases.append( state.phase )
            // Hanging up put first: it stays last. Picture in picture dropped, the app's button added.
            let end = ours.filter { $0.id == "end" }
            return end + ours.filter { $0.id != "end" && $0.id != "pip" } + [
                .init( id: "notes", label: "Call notes", icon: CallScreen.CallControl.icons[ "alert" ]! ) { pressed += 1 },
            ]
        } )
        let screen = screen( phase: "ringing_out" )
        let row = dock( screen )

        XCTAssertEqual( row.last, "End Call" )
        XCTAssertEqual( row[ row.count - 2 ], "Call notes" )
        XCTAssertFalse( row.contains( "Picture In Picture" ) )
        XCTAssertTrue( phases.contains( "ringing_out" ) )

        // Drawn as ours: a dock button, sized with the rest, and it does what the app said.
        func find( _ view: UIView ) -> UIView? {
            if view.accessibilityIdentifier == "call-control-notes" { return view }
            return view.subviews.lazy.compactMap( find ).first
        }
        func labelled( _ label: String, in view: UIView ) -> UIView? {
            if view.accessibilityLabel == label { return view }
            return view.subviews.lazy.compactMap { labelled( label, in: $0 ) }.first
        }
        let notes = find( screen.view )
        XCTAssertTrue( notes is CallsButton )
        XCTAssertGreaterThan( notes?.bounds.width ?? 0, 0 )
        XCTAssertEqual( notes?.bounds.height ?? 0, labelled( "End Call", in: screen.view )?.bounds.height ?? -1, "the app's button is not the size of the rest" )
        XCTAssertTrue( notes?.accessibilityActivate() ?? false )
        XCTAssertEqual( pressed, 1 )
    }

    func testTheStatusLineAndTheViewOverTheStage() {
        let over = UIView()
        over.accessibilityIdentifier = "my-stage"
        CallScreen.shared.pieces = .init(
            status: { state in state.phase == "ringing_out" ? "Ringing Ann…" : nil },
            stage: { _ in over }
        )
        let ringing = screen( phase: "ringing_out" )
        XCTAssertNotNil( label( ringing, "Ringing Ann…" ) )
        XCTAssertNil( label( ringing, "Calling…" ) )
        XCTAssertTrue( over.superview === ringing.view )

        // A phase the app leaves to us: ours.
        let connecting = screen( phase: "connecting" )
        XCTAssertNotNil( label( connecting, "Connecting..." ) )
    }

    func testAButtonTheAppMakesAnewAtEachChangeKeepsTheDockAsItIsAndDoesTheNewestAction() {
        // As the docs write it: the app's button made in `controls`, so anew at every change of the call, many a second
        // while it connects. The dock keeps the one it shows, with what the newest one says, and isn't built again.
        var made = 0
        var pressed: [ Int ] = []
        CallScreen.shared.pieces = .init( controls: { ours, _ in
            made += 1
            let n = made
            return ours + [ .init( id: "order", label: "Order \( n )", icon: CallScreen.CallControl.icons[ "alert" ]! ) { pressed.append( n ) } ]
        } )
        let screen = screen( phase: "in_progress" )
        func row( _ view: UIView ) -> UIStackView? {
            if let stack = view as? UIStackView, stack.arrangedSubviews.contains( where: { $0.accessibilityLabel == "End Call" } ) { return stack }
            return view.subviews.lazy.compactMap( row ).first
        }
        let before = row( screen.view )?.arrangedSubviews ?? []
        let order = before.first { $0.accessibilityIdentifier == "call-control-order" }
        XCTAssertNotNil( order )

        for _ in 0..<5 {
            screen.apply( state: [ "phase": "in_progress", "type": "video", "group": false, "local": [ "muted": false, "camera": false ] ] )
        }

        XCTAssertGreaterThan( made, 5 )
        XCTAssertEqual( row( screen.view )?.arrangedSubviews ?? [], before )
        XCTAssertEqual( order?.accessibilityLabel, "Order \( made )" )
        XCTAssertTrue( order?.accessibilityActivate() ?? false )
        XCTAssertEqual( pressed, [ made ] )
    }
}
#endif
"""## ),
    ( "Tests/PresenceTests.swift", ##"""
import UIKit
import XCTest
@testable import WordPlusRealtimeUI

/// The presence parts (OnlineList, PersonRow, RowAction, OnlineCount, Avatar, PresenceDot, TypingDots and
/// ActivityIndicator), as realtime-ui's draw them, given plain values and no room. Run on a simulator, as PiecesTests.
@MainActor
final class PresenceTests: XCTestCase {
    override func tearDown() {
        CallScreen.shared.configure( .init() )
        super.tearDown()
    }

    /// The words on screen: every label's text, under no hidden view.
    private func texts( _ view: UIView ) -> [ String ] {
        guard !view.isHidden else { return [] }

        return [ ( view as? UILabel )?.text ].compactMap { $0 } + view.subviews.flatMap( texts )
    }

    /// A tap's actions, run as UIKit would: the tests have no application to send them through.
    private func press( _ control: UIControl ) {
        for target in control.allTargets {
            for action in control.actions( forTarget: target, forControlEvent: .touchUpInside ) ?? [] {
                _ = ( target as NSObject ).perform( Selector( action ) )
            }
        }
    }

    /// `view` laid out at `width`, in a window that writes in `direction`.
    private func laidOut( _ view: UIView, width: CGFloat = 320, height: CGFloat? = nil, direction: UITraitEnvironmentLayoutDirection = .leftToRight ) -> UIWindow {
        let parent = UIViewController()
        let child = UIViewController()
        parent.addChild( child )
        parent.view.addSubview( child.view )
        child.didMove( toParent: parent )
        parent.setOverrideTraitCollection( UITraitCollection( layoutDirection: direction == .rightToLeft ? .rightToLeft : .leftToRight ), forChild: child )

        let window = UIWindow( frame: CGRect( x: 0, y: 0, width: width, height: height ?? 600 ) )
        window.rootViewController = parent
        window.isHidden = false
        child.view.frame = window.bounds

        view.translatesAutoresizingMaskIntoConstraints = false
        child.view.addSubview( view )
        var pins = [
            view.leadingAnchor.constraint( equalTo: child.view.leadingAnchor ),
            view.trailingAnchor.constraint( equalTo: child.view.trailingAnchor ),
            view.topAnchor.constraint( equalTo: child.view.topAnchor ),
        ]
        if let height { pins.append( view.heightAnchor.constraint( equalToConstant: height ) ) }
        NSLayoutConstraint.activate( pins )
        window.layoutIfNeeded()
        return window
    }

    // MARK: OnlineCount

    func testACountDrawsNothingAtNoneAndNinetyNinePlusPastNinetyNine() {
        let count = OnlineCount()
        XCTAssertTrue( count.isHidden, "nothing at 0" )
        XCTAssertNil( OnlineCount.said( 0 ) )
        XCTAssertNil( OnlineCount.said( -1 ) )

        count.count = 1
        XCTAssertFalse( count.isHidden )
        XCTAssertEqual( texts( count ), [ "1" ] )
        XCTAssertEqual( count.accessibilityLabel, "1" )

        count.count = 99
        XCTAssertEqual( texts( count ), [ "99" ] )
        count.count = 100
        XCTAssertEqual( texts( count ), [ "99+" ] )

        count.count = 0
        XCTAssertTrue( count.isHidden, "and goes again" )
    }

    // MARK: OnlineList

    func testAListSaysItsTitleAndCountAndItsEmptyLineWithNobody() {
        let list = OnlineList()
        XCTAssertEqual( list.titleShown, "ONLINE (0)" )
        XCTAssertEqual( list.emptyShown, "No users online" )
        XCTAssertNil( list.closeShown, "no close button where the list can't be closed" )

        list.title = "In the shop"
        list.empty = "Nobody is in the shop"
        XCTAssertEqual( list.titleShown, "IN THE SHOP (0)" )
        XCTAssertEqual( list.emptyShown, "Nobody is in the shop" )

        list.rows = [ PersonRow( avatar: Avatar( name: "Ann", size: 32 ), name: "Ann" ) ]
        list.count = 1
        XCTAssertEqual( list.titleShown, "IN THE SHOP (1)" )
        XCTAssertNil( list.emptyShown, "the empty line goes with someone in it" )
        XCTAssertTrue( texts( list ).contains( "Ann" ) )

        list.rows = []
        list.count = 0
        XCTAssertFalse( texts( list ).contains( "Ann" ), "a row gone is gone" )
    }

    func testAListClosesWhereItIsToldHow() {
        var closed = 0
        let list = OnlineList( onClose: { closed += 1 } )
        let close = list.closeShown
        XCTAssertNotNil( close )
        XCTAssertEqual( close?.accessibilityLabel, "Close" )
        press( close! )
        XCTAssertEqual( closed, 1 )

        list.onClose = nil
        XCTAssertNil( list.closeShown )
    }

    func testAListScrollsWhatDoesNotFit() {
        let rows = ( 0..<40 ).map { PersonRow( avatar: Avatar( name: "P\( $0 )", size: 32 ), name: "P\( $0 )" ) }
        let list = OnlineList( count: 40, rows: rows )
        let window = laidOut( list, height: 200 )
        defer { window.isHidden = true }

        func scroll( _ view: UIView ) -> UIScrollView? {
            if let found = view as? UIScrollView { return found }
            return view.subviews.lazy.compactMap( scroll ).first
        }
        let found = scroll( list )
        XCTAssertNotNil( found )
        XCTAssertGreaterThan( found!.contentSize.height, found!.bounds.height )
        XCTAssertLessThanOrEqual( found!.contentSize.width, found!.bounds.width, "and never sideways" )
    }

    // MARK: PersonRow and RowAction

    func testARowDrawsTheFaceTheNameTheLineUnderItAndWhatMayBeDone() {
        var called = 0
        let action = RowAction( icon: RowAction.icons[ "phone" ]!, label: "Call Ann" ) { called += 1 }
        let row = PersonRow( avatar: Avatar( name: "Ann", size: 32, decorative: true ), name: "Ann", sub: "support", actions: [ action ] )
        XCTAssertEqual( texts( row ).filter { $0 == "Ann" || $0 == "support" }, [ "Ann", "support" ] )
        XCTAssertEqual( action.accessibilityLabel, "Call Ann" )
        XCTAssertTrue( action.accessibilityTraits.contains( .button ) )

        press( action )
        XCTAssertEqual( called, 1 )

        row.sub = nil
        XCTAssertNil( row.subShown, "no line under the name without one" )
        row.name = "Anna"
        XCTAssertTrue( texts( row ).contains( "Anna" ) )
    }

    func testARowActionTakesAFingerRoundItsSmallButton() {
        let action = RowAction( icon: CallScreen.CallControl.icons[ "phone" ]!, label: "Call" ) {}
        action.frame = CGRect( x: 0, y: 0, width: 28, height: 28 )
        XCTAssertTrue( action.point( inside: CGPoint( x: -7, y: 35 ), with: nil ) )
        XCTAssertFalse( action.point( inside: CGPoint( x: -9, y: 14 ), with: nil ) )
    }

    func testARowEndsWhereTheLineEndsInEitherDirection() {
        func frames( _ direction: UITraitEnvironmentLayoutDirection ) -> ( avatar: CGRect, action: CGRect ) {
            let avatar = Avatar( name: "Ann", size: 32 )
            let action = RowAction( icon: RowAction.icons[ "phone" ]!, label: "Call" ) {}
            let row = PersonRow( avatar: avatar, name: "Ann", actions: [ action ] )
            let window = laidOut( row, direction: direction )
            defer { window.isHidden = true }
            return ( avatar.convert( avatar.bounds, to: row ), action.convert( action.bounds, to: row ) )
        }

        let leftToRight = frames( .leftToRight )
        XCTAssertLessThan( leftToRight.avatar.maxX, leftToRight.action.minX )
        let rightToLeft = frames( .rightToLeft )
        XCTAssertGreaterThan( rightToLeft.avatar.minX, rightToLeft.action.maxX, "the face at the start of the line, on the right" )
    }

    // MARK: Avatar and PresenceDot

    func testAFaceHasItsLettersWithNoPictureAndWhereThePictureDoesNotLoad() {
        XCTAssertEqual( Avatar( name: "Ann Lee" ).lettersShown, "AL" )
        XCTAssertEqual( Avatar( name: "ann" ).lettersShown, "A" )
        XCTAssertEqual( Avatar().lettersShown, "?" )
        let own = AvatarLetters( text: "Z", background: .black, color: .white )
        XCTAssertEqual( Avatar( name: "Ann", letters: own ).lettersShown, "Z", "an app's own letters" )
        XCTAssertTrue( texts( Avatar( name: "Ann", picture: "https://example.invalid/none.png" ) ).contains( "A" ) )
    }

    func testAFaceWearsItsDotWhileThePersonIsNotOffline() {
        let avatar = Avatar( name: "Ann" )
        XCTAssertNil( avatar.dotShown, "no status, no dot" )

        avatar.presence = .online
        XCTAssertEqual( avatar.dotShown?.presence, .online )
        XCTAssertEqual( avatar.accessibilityLabel, "Ann, Online" )

        avatar.presence = .busy
        XCTAssertEqual( avatar.dotShown?.presence, .busy, "the same dot, in the new status" )
        XCTAssertEqual( avatar.accessibilityLabel, "Ann, Do not disturb" )

        avatar.presence = .offline
        XCTAssertNil( avatar.dotShown, "no dot for someone offline, where no dot says as much" )
        XCTAssertEqual( avatar.accessibilityLabel, "Ann" )

        avatar.showOffline = true
        XCTAssertEqual( avatar.dotShown?.presence, .offline, "unless asked" )
    }

    func testAFaceBesideItsNameSaysNothing() {
        let avatar = Avatar( name: "Ann", presence: .online, decorative: true )
        XCTAssertFalse( avatar.isAccessibilityElement )
        XCTAssertNil( avatar.accessibilityLabel )
        XCTAssertTrue( avatar.accessibilityElementsHidden )
    }

    func testTheDotSitsAtTheCornerTheLineEndsOn() {
        func dotRightOfCentre( _ direction: UITraitEnvironmentLayoutDirection ) -> Bool {
            let avatar = Avatar( name: "Ann", size: 40, presence: .online )
            let holder = UIView()
            holder.addSubview( avatar )
            NSLayoutConstraint.activate( [
                avatar.centerXAnchor.constraint( equalTo: holder.centerXAnchor ),
                avatar.topAnchor.constraint( equalTo: holder.topAnchor ),
                holder.heightAnchor.constraint( equalToConstant: 60 ),
            ] )
            let window = laidOut( holder, direction: direction )
            defer { window.isHidden = true }
            return avatar.dotShown!.frame.midX > avatar.bounds.midX
        }

        XCTAssertTrue( dotRightOfCentre( .leftToRight ) )
        XCTAssertFalse( dotRightOfCentre( .rightToLeft ) )
    }

    func testTheDotsAreInTheTokensOfTheWebAndAnAppsOwnColourWhileNotOffline() {
        CallScreen.shared.configure( .init( tokens: [
            "--wplus-color-online": "1, 2, 3", "--wplus-color-busy": "4, 5, 6", "--wplus-color-away": "7, 8, 9", "--wplus-color-offline": "10, 11, 12",
        ] ) )
        func rgb( _ color: UIColor? ) -> [ Int ] {
            var red: CGFloat = 0, green: CGFloat = 0, blue: CGFloat = 0, alpha: CGFloat = 0
            color?.getRed( &red, green: &green, blue: &blue, alpha: &alpha )
            return [ red, green, blue ].map { Int( ( $0 * 255 ).rounded() ) }
        }
        XCTAssertEqual( rgb( PresenceDot( presence: .online ).backgroundColor ), [ 1, 2, 3 ] )
        XCTAssertEqual( rgb( PresenceDot( presence: .busy ).backgroundColor ), [ 4, 5, 6 ] )
        XCTAssertEqual( rgb( PresenceDot( presence: .away ).backgroundColor ), [ 7, 8, 9 ] )
        XCTAssertEqual( rgb( PresenceDot( presence: .offline ).backgroundColor ), [ 10, 11, 12 ] )
        XCTAssertEqual( rgb( PresenceDot( presence: nil ).backgroundColor ), [ 10, 11, 12 ], "no status is drawn as offline" )

        let own = UIColor( red: 0, green: 0, blue: 1, alpha: 1 )
        XCTAssertEqual( rgb( PresenceDot( presence: .online, color: own ).backgroundColor ), [ 0, 0, 255 ] )
        XCTAssertEqual( rgb( PresenceDot( presence: .offline, color: own ).backgroundColor ), [ 10, 11, 12 ] )
    }

    // MARK: TypingDots and ActivityIndicator

    func testTheLineSaysWhoAsTheWebGroupsThem() {
        func said( _ list: [ ActivityEntry ] ) -> String { ActivityIndicator.said( list ) }

        XCTAssertEqual( said( [ .init() ] ), "typing", "nobody named" )
        XCTAssertEqual( said( [ .init( name: "Anna" ) ] ), "Anna typing" )
        XCTAssertEqual( said( [ .init( name: "Anna" ), .init( name: "Bob" ) ] ), "Anna, Bob typing" )
        XCTAssertEqual( said( [ .init( name: "Anna" ), .init( name: "Bob" ), .init( name: "Cara" ) ] ), "3 typing", "past two, a count" )
        XCTAssertEqual( said( [ .init(), .init() ] ), "2 typing" )
        XCTAssertEqual( said( [ .init( name: " " ) ] ), "typing", "a name of nothing is no name" )

        XCTAssertEqual( said( [ .init( activity: .recording ) ] ), "recording" )
        XCTAssertEqual( said( [ .init( name: "Carol", activity: .recording ) ] ), "Carol recording" )
        XCTAssertEqual( said( [ .init( activity: .uploading ) ] ), "sending file" )
        XCTAssertEqual( said( [ .init( name: "Dan", activity: .uploading ) ] ), "Dan sending file" )

        XCTAssertEqual(
            said( [ .init( name: "Carol", activity: .recording ), .init( name: "Anna" ), .init( name: "Bob" ) ] ),
            "Anna, Bob typing, Carol recording",
            "each activity its own part, typing first"
        )
    }

    func testTheLineHasTheIconOfItsOneActivityAndTheDotsOnceTheyMix() {
        XCTAssertEqual( ActivityIndicator.iconActivity( [ .init() ] ), .typing )
        XCTAssertEqual( ActivityIndicator.iconActivity( [ .init( activity: .recording ) ] ), .recording )
        XCTAssertEqual( ActivityIndicator.iconActivity( [ .init( activity: .uploading ) ] ), .uploading )
        XCTAssertEqual( ActivityIndicator.iconActivity( [ .init( activity: .recording ), .init( activity: .uploading ) ] ), .typing )

        let line = ActivityIndicator( names: [ "Anna" ] )
        XCTAssertTrue( line.iconView is TypingDots )
        XCTAssertEqual( line.accessibilityLabel, "Anna typing" )
        XCTAssertTrue( texts( line ).contains( "Anna typing" ) )

        line.activity = .recording
        XCTAssertFalse( line.iconView is TypingDots )
        XCTAssertEqual( line.accessibilityLabel, "Anna recording" )

        line.entries = [ .init( name: "Bob" ), .init( name: "Cara", activity: .uploading ) ]
        XCTAssertTrue( line.iconView is TypingDots )
        XCTAssertEqual( line.accessibilityLabel, "Bob typing, Cara sending file" )
    }

    func testTheWordsAreTheAppsWhereItGivesThem() {
        CallScreen.shared.configure( .init( strings: [
            "typing": "schreibt", "typing_named": "%s schreibt", "recording_named": "%s nimmt auf", "uploading": "sendet",
            "online": "Da", "online_empty": "Niemand", "close": "Schliessen", "presence_online": "Anwesend",
        ] ) )
        XCTAssertEqual( ActivityIndicator.said( [ .init() ] ), "schreibt" )
        XCTAssertEqual( ActivityIndicator.said( [ .init( name: "Anna" ) ] ), "Anna schreibt" )
        XCTAssertEqual( ActivityIndicator.said( [ .init( name: "Anna", activity: .recording ) ] ), "Anna nimmt auf" )
        XCTAssertEqual( ActivityIndicator.said( [ .init( activity: .uploading ) ] ), "sendet" )

        let list = OnlineList( onClose: {} )
        XCTAssertEqual( list.titleShown, "DA (0)" )
        XCTAssertEqual( list.emptyShown, "Niemand" )
        XCTAssertEqual( list.closeShown?.accessibilityLabel, "Schliessen" )
        XCTAssertEqual( Avatar( name: "Ann", presence: .online ).accessibilityLabel, "Ann, Anwesend" )
    }

    func testTheDotsMoveOnAWindowAndStopOffIt() {
        let dots = TypingDots()
        XCTAssertFalse( dots.moving, "off a window nothing moves" )

        let window = laidOut( dots )
        defer { window.isHidden = true }
        XCTAssertEqual( dots.moving, !UIAccessibility.isReduceMotionEnabled, "and still where motion is asked to be reduced" )
        XCTAssertFalse( dots.isAccessibilityElement, "the line says what they mean" )

        dots.removeFromSuperview()
        XCTAssertFalse( dots.moving )
    }

    // MARK: Plain values

    /// These views are fed by whoever draws them: none imports the rooms or the calls, so none can read a room.
    func testNoneOfThemReadsARoom() throws {
        let tests = URL( fileURLWithPath: #filePath ).deletingLastPathComponent()
        let sources = tests.deletingLastPathComponent().deletingLastPathComponent().appendingPathComponent( "Sources/WordPlusRealtimeUI" )
        for name in [ "Presence.swift", "OnlineList.swift" ] {
            // A copy of the screen in an app keeps these tests beside its own folders.
            guard let text = try? String( contentsOf: sources.appendingPathComponent( name ), encoding: .utf8 ) else {
                throw XCTSkip( "the package's sources are not beside these tests" )
            }
            let imports = text.split( separator: "\n" ).filter { $0.hasPrefix( "import " ) || $0.hasPrefix( "@_spi" ) }
            XCTAssertEqual( imports, [ "import UIKit" ], "\( name ) imports the view kit alone" )
            for word in [ "Room", "Realtime", "GroupCall", "RealtimeCalls" ] {
                XCTAssertFalse( text.contains( ": \( word )" ), "\( name ) takes no \( word )" )
            }
        }
    }
}
"""## ),
    ( "Tests/PreviewTests.swift", ##"""
#if canImport(UIKit)
import UIKit
import XCTest
@testable import WordPlusRealtimeUI

/// The preview (CallScreenPreview): every state draws the real
/// screen with no call, ringing in offers Answer and Reject, a call offers End Call, a group call has its people, and the
/// list names every state. Run on a simulator, as PiecesTests.
@MainActor
final class PreviewTests: XCTestCase {
    private func labels( _ view: UIView ) -> [ String ] {
        ( view.isHidden ? [] : [ view.accessibilityLabel ].compactMap { $0 } ) + view.subviews.flatMap( labels )
    }

    /// The words on screen: every label's text, under no hidden view.
    private func texts( _ view: UIView ) -> [ String ] {
        guard !view.isHidden else { return [] }

        return [ ( view as? UILabel )?.text ].compactMap { $0 } + view.subviews.flatMap( texts )
    }

    private func drawn( _ shown: CallScreenPreview.Shown ) -> ( CallScreenPreview, CallsScreen ) {
        let preview = CallScreenPreview( shown )
        preview.loadViewIfNeeded()
        preview.view.frame = CGRect( x: 0, y: 0, width: 390, height: 844 )
        preview.view.layoutIfNeeded()
        let screen = preview.children.compactMap { $0 as? CallsScreen }.first
        XCTAssertNotNil( screen, "\( shown ) draws the screen" )
        return ( preview, screen! )
    }

    func testEveryStateDrawsTheScreen() {
        for shown in CallScreenPreview.Shown.allCases {
            let ( _, screen ) = drawn( shown )
            let said = labels( screen.view )
            if shown == .ringing {
                XCTAssertTrue( said.contains( "Answer" ), "ringing in offers to answer: \( said )" )
                XCTAssertTrue( said.contains( "Reject" ), "ringing in offers to reject: \( said )" )
            } else if shown.isGroup {
                // A group call is left, not ended, and draws its people. Host Controls is a moderator's alone, and
                // nobody in the preview moderates.
                XCTAssertTrue( said.contains( "Exit Chat" ), "\( shown ) offers Exit Chat: \( said )" )
                let words = texts( screen.view )
                let people = shown == .groupJoining || shown == .groupWaiting ? [ "You" ] : [ "You", "Ann", "Ben", "Cara" ]
                XCTAssertTrue( people.allSatisfy( words.contains ), "\( shown ) draws its people: \( words )" )
                XCTAssertFalse( said.contains( "Host Controls" ), "\( shown ) offers Host Controls to nobody who moderates: \( said )" )
            } else {
                XCTAssertTrue( said.contains( "End Call" ), "\( shown ) offers End Call: \( said )" )
            }
        }
    }

    func testAJoinWaitingForAPlaceSaysSo() {
        // The web's status of a group call waiting (use-group-call.ts).
        XCTAssertTrue( texts( drawn( .groupWaiting ).1.view ).contains( "Waiting for a free place in the call..." ) )
        XCTAssertFalse( texts( drawn( .groupJoining ).1.view ).contains( "Waiting for a free place in the call..." ) )
    }

    func testARecordingIsTold() {
        // Someone else's recording: the pill, and the notice.
        func pill( _ view: UIView ) -> CallsRecordingPill? {
            if let found = view as? CallsRecordingPill, !found.isHidden { return found }
            return view.subviews.lazy.compactMap( pill ).first
        }
        let recorded = drawn( .recording ).1.view!
        XCTAssertNotNil( pill( recorded ) )
        XCTAssertTrue( texts( recorded ).contains( "This call is being recorded" ) )
        XCTAssertNil( pill( drawn( .group ).1.view ) )
    }

    func testACameraChangingCodecIsSaidOnItsTileAndNowhereElse() {
        let words = "Optimizing video quality..."
        let ( _, changing ) = drawn( .optimizing )
        XCTAssertEqual( labels( changing.view ).filter { $0 == words }.count, 1, "one tile says it: \( labels( changing.view ) )" )
        let ( _, still ) = drawn( .group )
        XCTAssertFalse( labels( still.view ).contains( words ), "no tile says it with no camera changing" )
    }

    func testACameraChangingCodecIsToldOncePerPersonWhereverTheirTileGoes() {
        let said = CallsOptimizingSaid()
        XCTAssertTrue( said.first( "ann" ) )
        XCTAssertFalse( said.first( "ann" ), "another tile of Ann's, or hers drawn again" )
        XCTAssertTrue( said.first( "ben" ) )
        said.keep( [ "ben" ] )
        XCTAssertTrue( said.first( "ann" ), "Ann's change over: her next one is told" )
        XCTAssertFalse( said.first( "ben" ) )
    }

    /// The web's group call while its room connects: the grid, no "Connecting..." over it, the spinner before the dock,
    /// and the dock Show Chat and Exit Chat alone. Connected, the spinner is gone and the dock is whole.
    func testAGroupCallBeingJoinedSaysSoBeforeItsDock() {
        let ( preview, joining ) = drawn( .groupJoining )
        preview.view.layoutIfNeeded()
        let said = labels( joining.view )
        let words = texts( joining.view )
        XCTAssertFalse( words.contains( "Connecting..." ), "nothing says Connecting... over the grid: \( words )" )
        XCTAssertTrue( said.contains( "Connection Status (Quality)" ), "the bar starts with the connection: \( said )" )
        XCTAssertTrue( said.contains( "Exit Chat" ), "the way out is there: \( said )" )
        for control in [ "Enable Microphone", "Disable Microphone", "Enable Camera", "Disable Camera", "Speaker", "Device Settings" ] {
            XCTAssertFalse( said.contains( control ), "\( control ) waits for the room: \( said )" )
        }

        XCTAssertEqual( pill( joining.view )?.accessibilityValue, "Connecting...", "the bar says it connects" )

        let ( connected, joined ) = drawn( .group )
        connected.view.layoutIfNeeded()
        let offered = labels( joined.view )
        XCTAssertTrue( offered.contains( "Connection Status (Quality)" ), "a connected call keeps its connection, as a dot: \( offered )" )
        XCTAssertNil( pill( joined.view )?.accessibilityValue, "a connected call still turns its spinner" )
        XCTAssertTrue( offered.contains( "Disable Microphone" ) || offered.contains( "Enable Microphone" ), "a connected call has its microphone: \( offered )" )
    }

    private func everything( _ view: UIView ) -> [ UIView ] {
        [ view ] + view.subviews.flatMap( everything )
    }

    private func pill( _ view: UIView ) -> UIView? {
        everything( view ).first { $0 is CallsConnectionPill }
    }

    /// The web's group bar on a phone: its tiles stop above the dock, 8 from the screen's edges and from each other,
    /// the connection at the bar's start and the dock at its end. A tap leaves the bar where it is.
    func testAGroupCallsTilesStopAboveItsBar() {
        let ( preview, screen ) = drawn( .group )
        preview.view.layoutIfNeeded()
        let root = screen.view!
        let width = root.bounds.width
        guard let dock = everything( root ).first( where: { $0 is CallsDock } ), let badge = pill( root ) else {
            return XCTFail( "the bar is drawn" )
        }

        let docked = dock.convert( dock.bounds, to: root )
        let started = badge.convert( badge.bounds, to: root )
        let tiles = everything( root )
            .filter { String( describing: type( of: $0 ) ) == "Tile" && !$0.isHidden }
            .map { $0.convert( $0.bounds, to: root ) }
            .sorted { $0.minY < $1.minY }

        XCTAssertEqual( tiles.count, 4, "every person has a tile" )
        for tile in tiles {
            XCTAssertLessThanOrEqual( tile.maxY, docked.minY - 9 + 0.5, "a tile runs under the dock: \( tile ) over \( docked )" )
            XCTAssertEqual( tile.minX, 8, accuracy: 0.5, "a tile is 8 from the start: \( tile )" )
            XCTAssertEqual( tile.maxX, width - 8, accuracy: 0.5, "a tile is 8 from the end: \( tile )" )
        }
        for ( above, below ) in zip( tiles, tiles.dropFirst() ) {
            XCTAssertEqual( below.minY - above.maxY, 8, accuracy: 0.5, "the tiles are 8 apart" )
        }
        XCTAssertEqual( tiles.last?.maxY ?? 0, docked.minY - 9, accuracy: 0.5, "the last tile ends where the bar starts" )

        XCTAssertFalse( badge.isHidden, "the bar starts with the connection" )
        XCTAssertEqual( started.minX, 14, accuracy: 0.5, "the connection is 14 from the start" )
        XCTAssertEqual( docked.maxX, width - 14, accuracy: 0.5, "the dock is 14 from the end" )
        XCTAssertLessThanOrEqual( started.maxX + 10, docked.minX + 0.5, "the dock leaves the connection its room" )
        XCTAssertEqual( started.midY, docked.midY, accuracy: 0.5, "the two are level" )

        // The web's controls on a phone: 30 across, hanging up 16 wider, 5 apart, 6 in from the dock's edge.
        let buttons = ( dock as? CallsDock )?.row.arrangedSubviews.filter { !$0.isHidden }.map { $0.convert( $0.bounds, to: root ) } ?? []
        XCTAssertFalse( buttons.isEmpty, "the dock has controls" )
        for button in buttons {
            XCTAssertEqual( button.height, 30, accuracy: 0.5, "a control is not the web's 30: \( button )" )
        }
        XCTAssertEqual( buttons.last?.width ?? 0, 46, accuracy: 0.5, "leaving is not 16 wider than a control" )
        for ( before, after ) in zip( buttons, buttons.dropFirst() ) {
            XCTAssertEqual( after.minX - before.maxX, 5, accuracy: 0.5, "the controls are not 5 apart" )
        }
        XCTAssertEqual( ( buttons.first?.minX ?? 0 ) - docked.minX, 6, accuracy: 0.5, "the first control is not 6 in from the dock's edge" )
        XCTAssertEqual( docked.height, 42, accuracy: 0.5, "the dock is not the web's 42 tall" )

        screen.perform( NSSelectorFromString( "stageTapped" ) )
        XCTAssertEqual( dock.alpha, 1, "a tap put a group call's bar away" )
    }

    /// A press in Device Settings is the panel's: the screen's own tap took it from every button there (UIKit keeps a
    /// UIButton's tap from an ancestor's recognizer, not a UIControl of ours), so Done, Test and Preview did nothing.
    /// The dock is its own too, and a press on a tile is still the screen's.
    func testThePopupsKeepTheirPresses() {
        let ( preview, screen ) = drawn( .group )
        preview.view.layoutIfNeeded()
        guard let ground = screen.view.gestureRecognizers?.compactMap( { $0 as? CallsGroundTap } ).first else {
            return XCTFail( "the screen has its tap" )
        }

        screen.showDevices()
        preview.view.layoutIfNeeded()
        let panel = everything( screen.view ).compactMap { $0 as? CallsDevices }.first
        let done = panel.flatMap { everything( $0 ).first { $0 is CallsDevicePill } }
        XCTAssertNotNil( done, "Device Settings has its Done" )
        XCTAssertFalse( ground.takes( done ), "the screen takes the press on Done" )
        XCTAssertFalse( ground.takes( panel ), "the screen takes a press on the panel" )

        let dock = everything( screen.view ).first { $0 is CallsDock }
        XCTAssertFalse( ground.takes( dock?.subviews.first ), "the screen takes a press on the dock" )

        let tile = everything( screen.view ).first { String( describing: type( of: $0 ) ) == "Tile" }
        XCTAssertTrue( ground.takes( tile ), "a press on a tile is no longer the screen's" )
    }

    /// Device Settings: the camera in use is a field the width of its row with the system's own menu of the cameras, the
    /// one in use ticked, and the speaker's opens the system's list of outputs. As `.wplus-call-device-current`, where a
    /// line of quiet text read as a caption and people did not find where to choose a device.
    func testADeviceInUseIsAFieldThatOpensTheSystemsMenu() {
        let ( preview, screen ) = drawn( .video )
        screen.showDevices()
        preview.view.layoutIfNeeded()

        guard let panel = everything( screen.view ).compactMap( { $0 as? CallsDevices } ).first else {
            return XCTFail( "Device Settings opens" )
        }

        let rows = everything( panel ).compactMap { $0 as? CallsDeviceRow }
        XCTAssertEqual( rows.map( \.kind ), [ .camera, .microphone, .speaker ] )

        guard let camera = rows.first.flatMap( { everything( $0 ).compactMap { $0 as? CallsDeviceField }.first } ),
              let speaker = rows.last.flatMap( { everything( $0 ).compactMap { $0 as? CallsDeviceField }.first } ) else {
            return XCTFail( "each device has its field" )
        }

        XCTAssertTrue( camera.opens )
        XCTAssertTrue( camera.showsMenuAsPrimaryAction, "a press on the field is the menu" )
        XCTAssertEqual( camera.frame.height, 40, accuracy: 0.5, "the field is not a finger's height" )
        XCTAssertEqual( camera.frame.width, rows[ 0 ].frame.width - 16, accuracy: 0.5, "the field is not the width of its row" )

        let cameras = camera.menu?.children.compactMap { $0 as? UIAction } ?? []
        XCTAssertEqual( cameras.map( \.title ), [ "Front Camera", "Back Camera" ] )
        XCTAssertEqual( cameras.filter { $0.state == .on }.map( \.title ), [ camera.name.text ?? "" ], "the camera in use is not the one ticked" )

        XCTAssertTrue( speaker.opens )
        XCTAssertNil( speaker.menu, "the system keeps the list of outputs" )
        XCTAssertFalse( speaker.showsMenuAsPrimaryAction )
    }

    /// A device with nothing else to choose is plain text, with no arrow to press.
    func testADeviceWithNothingToChooseIsPlainText() {
        let field = CallsDeviceField()
        field.opens = false
        field.layoutIfNeeded()

        XCTAssertFalse( field.isUserInteractionEnabled )
        XCTAssertEqual( field.layer.borderWidth, 0 )
        XCTAssertTrue( everything( field ).filter { $0 is CallsIconView }.allSatisfy( \.isHidden ), "an arrow on a field that opens nothing" )
    }

    /// A window shrunk into the band under a page's header overlaps none of the screen's unsafe edges, so the call
    /// in it starts at its top: UIKit went on giving it the status bar's inset, an empty strip over the call. A window
    /// over the whole screen keeps every edge, and one reaching under the status bar keeps what it reaches.
    func testAWindowInABandHasNoStatusBarToClear() {
        let screen = CGRect( x: 0, y: 0, width: 402, height: 874 )
        let edges = UIEdgeInsets( top: 62, left: 0, bottom: 34, right: 0 )

        XCTAssertEqual( CallsScreen.safeArea( of: CGRect( x: 0, y: 118, width: 402, height: 302 ), on: screen, edges: edges ), .zero )
        XCTAssertEqual( CallsScreen.safeArea( of: screen, on: screen, edges: edges ), edges )
        XCTAssertEqual(
            CallsScreen.safeArea( of: CGRect( x: 0, y: 40, width: 402, height: 820 ), on: screen, edges: edges ),
            UIEdgeInsets( top: 22, left: 0, bottom: 20, right: 0 )
        )
    }

    func testAGroupCallHasItsPeople() {
        let ( _, screen ) = drawn( .group )
        XCTAssertEqual( screen.roster.map( \.name ), [ "You", "Ann", "Ben", "Cara" ] )
    }

    func testTheListNamesEveryState() {
        let preview = CallScreenPreview()
        preview.loadViewIfNeeded()
        let list = preview.view.subviews.compactMap { $0 as? UITableView }.first
        XCTAssertEqual( list?.numberOfRows( inSection: 0 ), CallScreenPreview.Shown.allCases.count )
    }
}
#endif
"""## ),
    ( "Tests/RecordingTests.swift", ##"""
#if canImport(UIKit)
import UIKit
import XCTest
@testable import WordPlusRealtimeUI

/// A group call's recording on the call screens, as the web's recording.tsx draws it: who is told and asked under each
/// of the site's ways of telling, the words, the time, the start's facts, and the real screen drawing the notice, the
/// question to stay or leave and REC from the engine's state. Run on a simulator: `xcodebuild test -scheme
/// WordPlusRealtime-Package -destination 'platform=iOS Simulator,name=iPhone 16' -only-testing:WordPlusRealtimeUITests`.
@MainActor
final class RecordingTests: XCTestCase {
    private func recording( _ values: [ String: Any ] ) -> CallsRecording {
        var base: [ String: Any ] = [ "state": "on", "id": "7", "since": 0, "can": false, "tell": "notice", "by": "Ann", "mine": false, "notice": true, "answer": "" ]
        base.merge( values ) { $1 }
        return CallsRecording( base )!
    }

    // MARK: Who is told

    func testEachWayOfTellingAsTheWebTellsIt() {
        // REC alone: nobody is told or asked more.
        XCTAssertFalse( recording( [ "tell": "indicator" ] ).told )
        XCTAssertTrue( recording( [ "tell": "indicator" ] ).pillShown )

        // Only moderators know: a member sees no REC and is told nothing; a moderator sees REC.
        XCTAssertFalse( recording( [ "tell": "moderators" ] ).pillShown )
        XCTAssertFalse( recording( [ "tell": "moderators" ] ).told )
        XCTAssertTrue( recording( [ "tell": "moderators", "can": true ] ).pillShown )

        // A notice, until it is seen or turned off for good.
        XCTAssertTrue( recording( [ "tell": "notice" ] ).noticeShown )
        XCTAssertFalse( recording( [ "tell": "notice" ] ).asking )
        XCTAssertFalse( recording( [ "tell": "notice", "answer": "seen" ] ).noticeShown )
        XCTAssertFalse( recording( [ "tell": "notice", "notice": false ] ).noticeShown )

        // The question, until they agree, with the microphone and camera held for `muted`.
        XCTAssertTrue( recording( [ "tell": "ask" ] ).asking )
        XCTAssertTrue( recording( [ "tell": "muted" ] ).asking )
        XCTAssertFalse( recording( [ "tell": "muted", "answer": "agreed" ] ).asking )
        XCTAssertFalse( recording( [ "tell": "ask" ] ).noticeShown )

        // Whoever started it is told and asked nothing, and nothing is told before it records.
        XCTAssertFalse( recording( [ "tell": "ask", "mine": true ] ).asking )
        XCTAssertFalse( recording( [ "tell": "notice", "mine": true ] ).noticeShown )
        XCTAssertFalse( recording( [ "tell": "ask", "state": "starting" ] ).asking )
        XCTAssertFalse( recording( [ "tell": "ask", "id": "" ] ).asking )

        // Unknown ways are a notice, and the store's states read as the call screen's.
        XCTAssertEqual( recording( [ "tell": "shout" ] ).tell, "notice" )
        XCTAssertEqual( CallsRecording.stateOf( "recording" ), "on" )
        XCTAssertEqual( CallsRecording.stateOf( "finishing" ), "off" )
        XCTAssertEqual( recording( [ "id": 42 ] ).id, "42" )
    }

    func testJoinedWhileItRecordedOrThereAsItStarted() {
        var there = CallsRecordingLate()
        there.see( connected: true, recording: recording( [ "state": "off" ] ) )
        there.see( connected: true, recording: recording( [ "state": "on" ] ) )
        XCTAssertFalse( there.isLate( "7" ) )

        var joined = CallsRecordingLate()
        joined.see( connected: false, recording: recording( [ "state": "on" ] ) )
        joined.see( connected: true, recording: recording( [ "state": "on" ] ) )
        XCTAssertTrue( joined.isLate( "7" ) )

        let said = recording( [ "settings": [ "watch": "people" ] ] )
        XCTAssertEqual( said.noticeTitle( late: false ), "Ann started recording this call" )
        XCTAssertEqual( said.noticeTitle( late: true ), "This call is being recorded" )
        XCTAssertEqual( said.noticeNote( late: true ), "Ann started recording. The people who were in the call can watch it afterwards." )
        XCTAssertEqual( said.noticeNote( late: false ), "The people who were in the call can watch it afterwards." )
    }

    func testTheQuestionAndTheModeratorsWords() {
        XCTAssertEqual( recording( [ "tell": "muted" ] ).questionLead, "Ann started recording. Your microphone and camera stay off until you agree to be recorded." )
        XCTAssertEqual( recording( [ "tell": "muted" ] ).questionYes, "I Agree" )
        XCTAssertEqual( recording( [ "tell": "ask", "by": "" ] ).questionLead, "If you stay in the call, you agree to be recorded." )
        XCTAssertEqual( recording( [ "tell": "ask" ] ).questionYes, "Stay in Call" )

        XCTAssertEqual( recording( [ "tell": "moderators" ] ).startNote, "Asks you first. Nobody else in the call is told." )
        XCTAssertEqual( recording( [ "tell": "indicator" ] ).startNote, "Asks you first. Everyone in the call then sees REC beside the call controls." )
        XCTAssertEqual( recording( [ "settings": [ "watch": "admins" ] ] ).readyLead, "Site administrators can watch it in a few minutes." )
        XCTAssertEqual( recording( [ "settings": [ "watch": "admins" ] ] ).watchNote, "" )
        XCTAssertEqual( recording( [ "settings": [ "watch": "everyone", "transcript": true ] ] ).watchNote,
                        "Everyone in the conversation can watch it afterwards. A transcript is made too." )
    }

    func testTheTimeAndTheStartsFacts() {
        XCTAssertEqual( CallsRecording.elapsed( 0 ), "0:00" )
        XCTAssertEqual( CallsRecording.elapsed( 724 ), "12:04" )
        XCTAssertEqual( CallsRecording.elapsed( 3725 ), "1:02:05" )
        XCTAssertEqual( CallsRecording.elapsed( -5 ), "0:00" )

        let video = recording( [ "settings": [ "size": 720, "layout": "gallery", "transcript": true, "language": "auto", "watch": "moderators", "keepDays": 0 ] ] )
        let rows = video.facts( audio: false ).map { $0.0 + ": " + $0.1 }
        XCTAssertEqual( rows, [ "Picture: 720p, Gallery layout", "Transcript: Automatic", "Who can watch: Moderators", "Kept: Until deleted" ] )

        // An audio call's picture only where the site has its layout; a language and days only in the host's words.
        let audio = recording( [ "settings": [ "size": 1080, "transcript": true, "language": "uk", "keepDays": 30 ], "words": [ "kept": "30 днів", "language": "українська" ] ] )
        XCTAssertEqual( audio.facts( audio: true ).map { $0.0 + ": " + $0.1 }, [ "Transcript: українська", "Kept: 30 днів" ] )
        XCTAssertEqual( recording( [ "settings": [ "keepDays": 30, "transcript": true, "language": "uk" ] ] ).facts( audio: false ).count, 0 )
    }

    // MARK: On the screen

    private func person( local: Bool, admin: Bool = false ) -> CallsRoomParticipant {
        CallsRoomParticipant(
            identity: local ? "user_1" : "user_2", name: local ? "Me" : "Ann", avatar: "", isLocal: local, video: nil, screen: nil,
            speaking: false, audioLevel: 0, muted: true, micMuted: false, handRaised: false, isPinned: false,
            canPublish: true, canAdmin: admin, mode: "participant", lost: false
        )
    }

    /// `full`: the dock an app's moderator has on a phone, Show Chat and Share Screen too.
    private func screen( _ recording: [ String: Any ], admin: Bool = false, full: Bool = false ) -> CallsScreen {
        let screen = CallsScreen()
        screen.loadViewIfNeeded()
        if full {
            screen.canShareScreen = true
            screen.onToggleChat = {}
        }
        screen.view.frame = CGRect( x: 0, y: 0, width: 390, height: 844 )
        screen.setRoster( [ person( local: true, admin: admin ), person( local: false ) ] )
        apply( screen, recording )
        return screen
    }

    private func apply( _ screen: CallsScreen, _ recording: [ String: Any ] ) {
        var base: [ String: Any ] = [ "state": "on", "id": "9", "since": Int( Date().timeIntervalSince1970 ) - 65, "can": false, "tell": "notice", "by": "Ann", "mine": false, "notice": true, "answer": "" ]
        base.merge( recording ) { $1 }
        screen.apply( state: [ "phase": "in_progress", "type": "video", "group": true, "local": [ "muted": true, "camera": false ], "recording": base ] )
        screen.view.layoutIfNeeded()
    }

    private func find<T: UIView>( _ type: T.Type, in view: UIView ) -> T? {
        if let found = view as? T, !found.isHidden { return found }
        return view.subviews.lazy.compactMap { self.find( type, in: $0 ) }.first
    }

    private func texts( _ view: UIView ) -> [ String ] {
        ( ( view as? UILabel )?.text.map { [ $0 ] } ?? [] ) + view.subviews.flatMap { texts( $0 ) }
    }

    func testANoticeOverTheDockWithREC() {
        let screen = screen( [ "tell": "notice" ] )

        let notice = find( CallsRecordingNotice.self, in: screen.view )
        XCTAssertNotNil( notice )
        // There as it started? The screen first saw it running while connected, with nothing before: a join.
        XCTAssertEqual( notice?.content.title, "This call is being recorded" )
        XCTAssertTrue( texts( notice! ).contains( "Got It" ) )
        XCTAssertTrue( texts( notice! ).contains( "Do Not Show Again" ) )
        XCTAssertNil( find( CallsConfirm.self, in: screen.view ) )

        let pill = find( CallsRecordingPill.self, in: screen.view )
        XCTAssertNotNil( pill )
        XCTAssertEqual( pill?.accessibilityLabel, "This call is being recorded." )
        // A member's REC is no button, and on a phone it shows the dot and the time alone.
        XCTAssertFalse( pill?.accessibilityTraits.contains( .button ) ?? true )
        XCTAssertTrue( texts( pill! ).contains( where: { $0.hasPrefix( "1:0" ) } ) )

        // Got It: gone for this recording, REC stays.
        apply( screen, [ "tell": "notice", "answer": "seen" ] )
        XCTAssertNil( find( CallsRecordingNotice.self, in: screen.view ) )
        XCTAssertNotNil( find( CallsRecordingPill.self, in: screen.view ) )
    }

    func testTheQuestionToStayOrLeaveIsAnsweredBeforeAnythingElse() {
        let screen = screen( [ "tell": "muted" ] )

        let question = find( CallsConfirm.self, in: screen.view )
        XCTAssertNotNil( question )
        let said = texts( question! )
        XCTAssertTrue( said.contains( "This call is being recorded" ) )
        XCTAssertTrue( said.contains( "Ann started recording. Your microphone and camera stay off until you agree to be recorded." ) )
        XCTAssertTrue( said.contains( "Leave Call" ) )
        XCTAssertTrue( said.contains( "I Agree" ) )
        XCTAssertNil( find( CallsRecordingNotice.self, in: screen.view ) )

        // Escape does not put it away.
        _ = question?.accessibilityPerformEscape()
        XCTAssertNotNil( question?.superview )

        // Leave Call leaves.
        var left = false
        screen.onEnd = { left = true }
        question?.finish( false )
        XCTAssertTrue( left )

        // Agreed, it goes and stays gone; stopped, it goes too.
        let again = self.screen( [ "tell": "ask" ] )
        XCTAssertNotNil( find( CallsConfirm.self, in: again.view ) )
        apply( again, [ "tell": "ask", "answer": "agreed" ] )
        XCTAssertNil( find( CallsConfirm.self, in: again.view ) )

        let stopped = self.screen( [ "tell": "ask" ] )
        apply( stopped, [ "tell": "ask", "state": "stopping" ] )
        XCTAssertNil( find( CallsConfirm.self, in: stopped.view ) )
    }

    func testOnlyModeratorsKnow() {
        let member = screen( [ "tell": "moderators", "can": false ] )
        XCTAssertNil( find( CallsRecordingPill.self, in: member.view ) )
        XCTAssertNil( find( CallsRecordingNotice.self, in: member.view ) )
        XCTAssertNil( find( CallsConfirm.self, in: member.view ) )

        let moderator = screen( [ "tell": "moderators", "can": true ], admin: true, full: true )
        let pill = find( CallsRecordingPill.self, in: moderator.view )
        XCTAssertNotNil( pill )
        XCTAssertTrue( pill?.accessibilityTraits.contains( .button ) ?? false )
        XCTAssertTrue( pill?.accessibilityLabel?.hasPrefix( "Recording, 1:0" ) ?? false )
        XCTAssertTrue( pill?.accessibilityLabel?.hasSuffix( ". Stop recording" ) ?? false )

    }

    func testAModeratorsRECOnAPhoneStandsInTheBar() {
        // A moderator's REC with Stop beside a dock with Host Controls, Show Chat and Share Screen, on a phone: the dock
        // laid out before any recording, then REC arriving and the call redrawn before the next layout, as the app's
        // state and the ticking time do. REC stands in the bar, level with the dock and clear of it, never over the
        // bar's start where it covers the last tile's name.
        let moderator = screen( [ "tell": "notice", "can": true, "mine": true, "state": "off", "id": "" ], admin: true, full: true )
        moderator.view.layoutIfNeeded()

        let running: [ String: Any ] = [ "tell": "notice", "can": true, "mine": true, "state": "on", "id": "12" ]
        let state: [ String: Any ] = [ "phase": "in_progress", "type": "video", "group": true, "local": [ "muted": true, "camera": false ],
                                       "recording": running.merging( [ "since": Int( Date().timeIntervalSince1970 ) - 5, "by": "Me", "notice": true, "answer": "" ] ) { $1 } ]
        moderator.apply( state: state )
        moderator.apply( state: state )

        for _ in 0..<3 { moderator.view.layoutIfNeeded() }

        let pill = find( CallsRecordingPill.self, in: moderator.view )
        let dock = find( CallsDock.self, in: moderator.view )
        XCTAssertNotNil( pill )
        XCTAssertNotNil( dock )
        XCTAssertEqual( pill!.frame.midY, dock!.frame.midY, accuracy: 1 )
        XCTAssertFalse( pill!.frame.intersects( dock!.frame ) )

        // Stopped: Saving recording… is wider still, and where no place in the bar holds it, it stands at the top of the
        // call, never just over the bar on the last tile's name.
        var stopping = state
        stopping[ "recording" ] = ( state[ "recording" ] as! [ String: Any ] ).merging( [ "state": "stopping" ] ) { $1 }
        moderator.apply( state: stopping )
        moderator.apply( state: stopping )

        for _ in 0..<3 { moderator.view.layoutIfNeeded() }

        XCTAssertTrue( texts( pill! ).contains( "Saving recording…" ) )
        XCTAssertFalse( pill!.frame.intersects( dock!.frame ) )
        XCTAssertTrue( abs( pill!.frame.midY - dock!.frame.midY ) < 1 || pill!.frame.minY < moderator.view.bounds.height / 4,
                       "Saving recording… stands just over the bar, at \( pill!.frame )" )
    }

    func testAModeratorsStopIsAskedFirst() {
        let screen = screen( [ "tell": "notice", "can": true, "mine": true, "settings": [ "watch": "people" ] ], admin: true )

        XCTAssertNil( find( CallsRecordingNotice.self, in: screen.view ) )
        screen.askRecording( "stop" )

        let confirm = find( CallsConfirm.self, in: screen.view )
        XCTAssertNotNil( confirm )
        XCTAssertTrue( texts( confirm! ).contains( "Stop recording?" ) )
        XCTAssertTrue( texts( confirm! ).contains( "The people who were in the call can watch it in a few minutes." ) )

        // It no longer fits once it stops.
        apply( screen, [ "tell": "notice", "can": true, "mine": true, "state": "stopping" ] )
        XCTAssertNil( find( CallsConfirm.self, in: screen.view ) )

        // Start only while it is off.
        apply( screen, [ "tell": "notice", "can": true, "state": "off", "id": "" ] )
        screen.askRecording( "start" )
        XCTAssertTrue( texts( find( CallsConfirm.self, in: screen.view )! ).contains( "Start recording?" ) )
    }

    func testNothingWithoutARecordingOrOutsideAGroupCall() {
        let screen = CallsScreen()
        screen.loadViewIfNeeded()
        screen.view.frame = CGRect( x: 0, y: 0, width: 390, height: 844 )
        screen.apply( state: [ "phase": "in_progress", "type": "video", "group": false, "local": [ "muted": true, "camera": false ],
                               "recording": [ "state": "on", "id": "3", "tell": "ask", "by": "Ann" ] ] )
        XCTAssertNil( find( CallsConfirm.self, in: screen.view ) )
        XCTAssertNil( find( CallsRecordingPill.self, in: screen.view ) )
    }
}
#endif
"""## ),
    ( "Tests/RingTests.swift", ##"""
import XCTest
@testable import WordPlusRealtimeUI

/// A ring's end takes its screen away, but for the answer this screen itself is making: the ring says it is over as it
/// is answered (@wordplus/realtime-client a738a57), and the call's screen comes with the answer. Run on a simulator:
/// `xcodebuild test -scheme WordPlusRealtime-Package -destination 'platform=iOS Simulator,name=iPhone 16'
/// -only-testing:WordPlusRealtimeUITests/RingTests`.
@MainActor
final class RingTests: XCTestCase {
    func testTheAnswerThisScreenIsMakingKeepsIt() {
        XCTAssertFalse(CallScreen.ringGoes(reason: "answered", answeringHere: true))
    }

    func testAnyOtherEndTakesItAway() {
        // The app answered through the API, or the system's screen did: the call's screen is shown as the answer comes.
        XCTAssertTrue(CallScreen.ringGoes(reason: "answered", answeringHere: false))
        for reason in ["declined", "busy", "cancelled", "answered_elsewhere"] {
            XCTAssertTrue(CallScreen.ringGoes(reason: reason, answeringHere: false))
            XCTAssertTrue(CallScreen.ringGoes(reason: reason, answeringHere: true))
        }
    }
}
"""## ),
    ( "Tests/SpotlightTests.swift", ##"""
#if canImport(UIKit)
import UIKit
import XCTest
@testable import WordPlusRealtimeUI

/// Spotlight for Everyone and Pin for Me on the call screens, as the web's calls/spotlight.tsx and
/// moderation-panels.tsx have them: who is in the spotlight and who is on the main tiles, the pins that wait for a
/// spotlight to end, the label on a spotlighted tile, and a moderator's rows in the person menu and Host Controls. Run on
/// a simulator: `xcodebuild test -scheme WordPlusRealtime-Package -destination 'platform=iOS Simulator,name=iPhone 16'
/// -only-testing:WordPlusRealtimeUITests/SpotlightTests`.
@MainActor
final class SpotlightTests: XCTestCase {
    private func person( _ id: Int, local: Bool = false, pinned: Bool = false, admin: Bool = false, publish: Bool = true ) -> CallsRoomParticipant {
        CallsRoomParticipant(
            identity: "user_\( id )", name: local ? "Me" : "Person \( id )", avatar: "", isLocal: local, video: nil, screen: nil,
            speaking: false, audioLevel: 0, muted: true, micMuted: false, handRaised: false, isPinned: pinned,
            canPublish: publish, canAdmin: admin, mode: "participant", lost: false
        )
    }

    override func tearDown() {
        let engine = CallsEngine.shared
        engine.canModerate = false
        engine.carriesSpotlight = false
        engine.isVideo = true
        super.tearDown()
    }

    // MARK: Who is in it, and the main tiles

    func testTheSpotlightInItsOrderAndAnOlderAppsPin() {
        let people = [ person( 1, local: true ), person( 2 ), person( 3, pinned: true ), person( 4 ) ]

        // The room's order, those in the call alone, once each; then anyone an older app pinned for everyone.
        XCTAssertEqual( CallsSpotlight.spotlit( people, spotlight: [ "user_4", "user_9", "user_2", "user_4" ] ), [ "user_4", "user_2", "user_3" ] )
        XCTAssertEqual( CallsSpotlight.spotlit( people, spotlight: [] ), [ "user_3" ] )
        XCTAssertEqual( CallsSpotlight.spotlit( [ person( 1 ) ], spotlight: [] ), [] )
        XCTAssertEqual( CallsSpotlight.most, 4 )
    }

    func testASpotlightComesFirstAndThePinsWaitForIt() {
        let people = [ person( 1, local: true ), person( 2 ), person( 3 ), person( 4, admin: true ), person( 5, publish: false ) ]

        // The spotlight alone, the pins and a broadcast's speakers waiting.
        XCTAssertEqual( CallsSpotlight.main( people, spotlight: [ "user_3" ], pinned: [ "user_2" ], broadcast: true ), [ "user_3" ] )
        // Nobody in it: this user's pins in the order pinned, someone gone no longer one.
        XCTAssertEqual( CallsSpotlight.main( people, spotlight: [], pinned: [ "user_3", "user_7", "user_2" ], broadcast: false ), [ "user_3", "user_2" ] )
        // In broadcast mode the speakers after the pins, a viewer not.
        XCTAssertEqual( CallsSpotlight.main( people, spotlight: [], pinned: [ "user_3" ], broadcast: true ), [ "user_3", "user_1", "user_2", "user_4" ] )
        XCTAssertEqual( CallsSpotlight.main( people, spotlight: [], pinned: [], broadcast: false ), [] )
        // A spotlight of someone who left is nobody's: the pins show.
        XCTAssertEqual( CallsSpotlight.main( people, spotlight: [ "user_9" ], pinned: [ "user_2" ], broadcast: false ), [ "user_2" ] )
    }

    func testPinsOnAndOffAndForThoseStillThere() {
        XCTAssertEqual( CallsSpotlight.toggled( [], "user_2" ), [ "user_2" ] )
        XCTAssertEqual( CallsSpotlight.toggled( [ "user_2", "user_3" ], "user_2" ), [ "user_3" ] )
        XCTAssertEqual( CallsSpotlight.toggled( [ "user_3" ], "user_2" ), [ "user_3", "user_2" ] )
        XCTAssertEqual( CallsSpotlight.kept( [ "user_2", "user_3" ], people: [ person( 1, local: true ), person( 3 ) ] ), [ "user_3" ] )
    }

    // MARK: On the screen

    private func screen( _ people: [ CallsRoomParticipant ], spotlight: [ String ], video: Bool = true ) -> CallsScreen {
        let screen = CallsScreen()
        screen.loadViewIfNeeded()
        screen.view.frame = CGRect( x: 0, y: 0, width: 390, height: 844 )
        screen.show( name: "Group", avatar: "", video: video )
        apply( screen, spotlight: spotlight, video: video )
        screen.setRoster( people )
        screen.view.layoutIfNeeded()
        return screen
    }

    private func apply( _ screen: CallsScreen, spotlight: [ String ], video: Bool = true ) {
        screen.apply( state: [ "phase": "in_progress", "type": video ? "video" : "audio", "group": true, "local": [ "muted": true, "camera": false ], "spotlight": spotlight ] )
        screen.view.layoutIfNeeded()
    }

    private func grid( _ screen: CallsScreen ) -> CallsGrid {
        find( CallsGrid.self, in: screen.view )!
    }

    private func find<T: UIView>( _ type: T.Type, in view: UIView ) -> T? {
        if let found = view as? T, !found.isHidden { return found }
        return view.subviews.lazy.compactMap { self.find( type, in: $0 ) }.first
    }

    private func texts( _ view: UIView ) -> [ String ] {
        guard !view.isHidden else { return [] }
        return ( ( view as? UILabel )?.text.map { [ $0 ] } ?? [] ) + view.subviews.flatMap { texts( $0 ) }
    }

    /// The people on the main tiles: their tiles stand outside the scroller, in the grid itself.
    private func main( _ screen: CallsScreen ) -> [ String ] {
        let grid = grid( screen )
        return grid.subviews.filter { !( $0 is UIScrollView ) }.flatMap { texts( $0 ) }.filter { $0.hasPrefix( "Person" ) || $0 == "Me" }
    }

    /// Who wears the Spotlight label, by the name beside it.
    private func labeled( _ screen: CallsScreen ) -> [ String ] {
        func tiles( _ view: UIView ) -> [ UIView ] {
            let words = view.subviews.compactMap { ( $0 as? UILabel )?.text }
            if words.contains( where: { $0.hasPrefix( "Person" ) || $0 == "Me" } ) { return [ view ] }
            return view.subviews.flatMap { tiles( $0 ) }
        }

        return tiles( grid( screen ) ).filter { texts( $0 ).contains( "Spotlight" ) }.compactMap { tile in
            tile.subviews.compactMap { ( $0 as? UILabel )?.text }.first { $0.hasPrefix( "Person" ) || $0 == "Me" }
        }
    }

    func testAJoinWithASpotlightOnShowsItLabeled() {
        let people = [ person( 1, local: true ), person( 2 ), person( 3 ), person( 4 ) ]
        let screen = screen( people, spotlight: [ "user_3", "user_2" ] )

        XCTAssertEqual( screen.spotlight, [ "user_3", "user_2" ] )
        XCTAssertEqual( main( screen ), [ "Person 3", "Person 2" ] )
        XCTAssertEqual( labeled( screen ).sorted(), [ "Person 2", "Person 3" ] )

        // Taken out for everyone: the usual tiles, no label.
        apply( screen, spotlight: [] )
        XCTAssertEqual( main( screen ), [] )
        XCTAssertEqual( labeled( screen ), [] )
    }

    func testPinForMeWaitsWhileASpotlightIsOn() {
        let people = [ person( 1, local: true ), person( 2 ), person( 3 ) ]
        let screen = screen( people, spotlight: [ "user_2" ] )

        screen.togglePinForMe( "user_3" )
        screen.view.layoutIfNeeded()
        XCTAssertEqual( screen.pinnedForMe, [ "user_3" ] )
        XCTAssertEqual( main( screen ), [ "Person 2" ] )

        // The spotlight ends: the pin shows, and the label goes.
        apply( screen, spotlight: [] )
        XCTAssertEqual( main( screen ), [ "Person 3" ] )
        XCTAssertEqual( labeled( screen ), [] )

        // Someone who leaves is unpinned.
        screen.setRoster( [ person( 1, local: true ), person( 2 ) ] )
        XCTAssertEqual( screen.pinnedForMe, [] )
    }

    func testAnAudioCallHasNoMainTiles() {
        let screen = screen( [ person( 1, local: true ), person( 2 ) ], spotlight: [ "user_2" ], video: false )

        XCTAssertEqual( screen.spotlight, [] )
        XCTAssertEqual( labeled( screen ), [] )
    }

    // MARK: A moderator's rows

    private func personMenu( _ screen: CallsScreen, _ who: CallsRoomParticipant ) -> [ String ] {
        CallsModeration.showFor( from: screen, person: who )
        defer { screen.closePopover() }
        // The newest: one closed a moment ago fades out over the call before it goes.
        return screen.view.subviews.compactMap { $0 as? CallsPopover }.last.map { texts( $0 ) } ?? []
    }

    func testAModeratorSpotlightsInPlaceOfThePin() {
        let engine = CallsEngine.shared
        engine.canModerate = true
        engine.carriesSpotlight = true

        let people = [ person( 1, local: true, admin: true ), person( 2 ), person( 3 ) ]
        let screen = screen( people, spotlight: [ "user_3" ] )

        let other = personMenu( screen, people[ 1 ] )
        XCTAssertTrue( other.contains( "Spotlight for Everyone" ) )
        XCTAssertTrue( other.contains( "Their tile is the main one for everyone in the call." ) )
        XCTAssertTrue( other.contains( "Pin for Me" ) )
        XCTAssertTrue( other.contains( "On your screen once nobody is in the spotlight." ) )
        XCTAssertFalse( other.contains( "Pin Participant" ) )

        let spotlit = personMenu( screen, people[ 2 ] )
        XCTAssertTrue( spotlit.contains( "Remove Spotlight" ) )
        XCTAssertFalse( spotlit.contains( "Spotlight for Everyone" ) )
    }

    func testAFifthIsRefusedAsTheWebRefusesIt() {
        let engine = CallsEngine.shared
        engine.canModerate = true
        engine.carriesSpotlight = true

        let people = [ person( 1, local: true, admin: true ) ] + ( 2 ... 6 ).map { person( $0 ) }
        let screen = screen( people, spotlight: [ "user_2", "user_3", "user_4", "user_5" ] )

        let fifth = personMenu( screen, people[ 5 ] )
        XCTAssertTrue( fifth.contains( "Spotlight for Everyone" ) )
        XCTAssertTrue( fifth.contains( "Up to four people can be in the spotlight." ) )
    }

    func testACallWithoutASpotlightKeepsThePin() {
        let engine = CallsEngine.shared
        engine.canModerate = true
        engine.carriesSpotlight = false

        let people = [ person( 1, local: true, admin: true ), person( 2 ) ]
        let screen = screen( people, spotlight: [] )

        let menu = personMenu( screen, people[ 1 ] )
        XCTAssertTrue( menu.contains( "Pin Participant" ) )
        XCTAssertTrue( menu.contains( "Pin for Me" ) )
        XCTAssertFalse( menu.contains( "Spotlight for Everyone" ) )
    }
}
#endif
"""## ),
    ( "Tests/ThemeTests.swift", ##"""
#if canImport(UIKit)
import UIKit
import XCTest
@testable import WordPlusRealtimeUI

/// The call screen's look from the app's tokens (CallScreen.Appearance, step 1 of customizing): the web's own names
/// for the stage, a grid's tiles, a control and the dock's glass recolour them, and without them the stage stays
/// near-black whatever the palette's other colours. Run on a simulator, as PiecesTests.
@MainActor
final class ThemeTests: XCTestCase {
    override func tearDown() {
        CallScreen.shared.configure( .init() )
        super.tearDown()
    }

    private func rgb( _ color: UIColor ) -> [ Int ] {
        var r: CGFloat = 0, g: CGFloat = 0, b: CGFloat = 0, a: CGFloat = 0
        color.getRed( &r, green: &g, blue: &b, alpha: &a )
        return [ r, g, b ].map { Int( ( $0 * 255 ).rounded() ) }
    }

    func testTheAppsTokensColourTheStageTilesControlsAndDock() {
        CallScreen.shared.configure( .init( tokens: [
            "--bm-call-canvas": "248, 250, 252",
            "--bm-call-tile": "226, 232, 240",
            "--bm-call-btn": "#2563eb",
            "--bm-call-dock": "255, 255, 255",
        ] ) )

        XCTAssertEqual( rgb( CallsTheme.stage ), [ 248, 250, 252 ] )
        XCTAssertEqual( rgb( CallsTheme.tile ), [ 226, 232, 240 ] )
        XCTAssertEqual( rgb( CallsTheme.control ), [ 37, 99, 235 ] )
        XCTAssertEqual( rgb( CallsTheme.dockGlass ), [ 255, 255, 255 ] )

        // On the real screen: its ground is the app's stage.
        let preview = CallScreenPreview( .video )
        preview.loadViewIfNeeded()
        let screen = preview.children.compactMap { $0 as? CallsScreen }.first
        XCTAssertEqual( screen.flatMap { $0.view.backgroundColor }.map( rgb ), [ 248, 250, 252 ] )
    }

    func testTheNamesOfTheWebCountAndTheOldOnesStill() {
        // @wordplus/realtime-ui 1.0.6 named its tokens `--wplus-…`, and the guides call these the web's names.
        CallScreen.shared.configure( .init( tokens: [
            "--wplus-color-accent": "37, 99, 235",
            "--wplus-call-canvas": "248, 250, 252",
            "--bm-call-tile": "226, 232, 240",
        ] ) )

        XCTAssertEqual( rgb( CallsTheme.accent ), [ 37, 99, 235 ] )
        XCTAssertEqual( rgb( CallsTheme.stage ), [ 248, 250, 252 ] )
        XCTAssertEqual( rgb( CallsTheme.tile ), [ 226, 232, 240 ] )

        // Both given, the new name wins.
        CallScreen.shared.configure( .init( tokens: [ "--wplus-color-accent": "37, 99, 235", "--bm-color-accent": "1, 2, 3" ] ) )
        XCTAssertEqual( rgb( CallsTheme.accent ), [ 37, 99, 235 ] )
    }

    func testWithoutThemTheStageStaysNearBlack() {
        CallScreen.shared.configure( .init( tokens: [ "--bm-color-accent": "37, 99, 235" ] ) )

        XCTAssertEqual( rgb( CallsTheme.stage ), [ 13, 15, 20 ] )
        XCTAssertEqual( rgb( CallsTheme.accent ), [ 37, 99, 235 ] )
    }
}
#endif
